-- Lookup pet details by Name
function EggsPetsData.GetPetByName(name)
    local query = tostring(name or ""):lower()
    for _, pet in ipairs(EggsPetsData.Pets) do
        if pet.Name:lower() == query then
            return pet
        end
    end
    -- Fallback checking RarityMap
    for petName, rarity in pairs(EggsPetsData.PetRarityMap) do
        if petName:lower() == query then
            return { Name = petName, Rarity = rarity, Multiplier = 1.0, Egg = "Unknown", Icon = "" }
        end
    end
    return { Name = name or "Unknown Pet", Rarity = "Common", Multiplier = 1.0, Egg = "Egg", Icon = "" }
end

-- Lookup pet rarity by Name
function EggsPetsData.GetPetRarity(name)
    local pet = EggsPetsData.GetPetByName(name)
    return pet and pet.Rarity or "Common"
end

-- Lookup Egg cost by Egg Name
function EggsPetsData.GetEggCost(eggName)
    local query = tostring(eggName or ""):lower()
    for _, egg in ipairs(EggsPetsData.Eggs) do
        if egg.Name:lower() == query then
            return egg.Cost
        end
    end
    return 0
end

return EggsPetsData
end)()

