PetMutationsData.PetMutationToEnum = {}
PetMutationsData.EnumToPetMutation = {}
PetMutationsData.MachineMutationTypes = {}
PetMutationsData.Level500MutationTypes = {}

for name, info in pairs(PetMutationsData.Registry) do
    if info.EnumId then
        PetMutationsData.EnumToPetMutation[info.EnumId] = name
        PetMutationsData.PetMutationToEnum[name] = info.EnumId
    end
    if info.Level500Only then
        PetMutationsData.Level500MutationTypes[name] = info
    elseif info.AvaliableFromMutationMachine then
        PetMutationsData.MachineMutationTypes[name] = info
    end
end

function PetMutationsData.RollRandomMutation(pool)
    pool = pool or PetMutationsData.MachineMutationTypes
    local totalWeight = 0
    for _, info in pairs(pool) do
        if info.Chance and info.Chance > 0 then
            totalWeight = totalWeight + info.Chance
        end
    end
    if totalWeight <= 0 then return nil end
    local roll = math.random() * totalWeight
    local current = 0
    for name, info in pairs(pool) do
        if info.Chance and info.Chance > 0 then
            current = current + info.Chance
            if current >= roll then
                return name
            end
        end
    end
    return nil
end

function PetMutationsData.GetPassiveBoost(mutationName)
    if not mutationName or mutationName == "" or mutationName == "None" then return 0 end
    local cleanName = tostring(mutationName):gsub("%s+", "")

    for name, info in pairs(PetMutationsData.Registry) do
        if name:gsub("%s+", ""):lower() == cleanName:lower() then
            if type(info.Boosts) == "table" then
                local totalBoost = 0
                for _, b in ipairs(info.Boosts) do
                    if type(b) == "table" and b.BoostType == "PASSIVE_BOOST" then
                        totalBoost = totalBoost + (tonumber(b.BoostAmount) or 0)
                    end
                end
                return totalBoost
            end
        end
    end

    return 0
end

return PetMutationsData
end)()

local MainFunctions = (function()
local MainFunctions = {}
--[[
    GAG 1 Hub - Main Functions: Movement & Anti-AFK
--]]

local Players = game:GetService("Players")
local VirtualUser = game:GetService("VirtualUser")
local LocalPlayer = Players.LocalPlayer

MainFunctions.DefaultSpeed = MainFunctions.DefaultSpeed or 16
MainFunctions.DefaultJump = MainFunctions.DefaultJump or 50
MainFunctions.CurrentSpeed = MainFunctions.CurrentSpeed or 16
MainFunctions.CurrentJump = MainFunctions.CurrentJump or 50
MainFunctions.AntiAFKConnection = MainFunctions.AntiAFKConnection or nil

-- WalkSpeed Modifier with Character Added hook
function MainFunctions.SetWalkSpeed(speed)
    MainFunctions.CurrentSpeed = speed
    local character = LocalPlayer.Character
    if character then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            humanoid.WalkSpeed = speed
        end
    end
end

-- JumpPower Modifier
function MainFunctions.SetJumpPower(power)
    MainFunctions.CurrentJump = power
    local character = LocalPlayer.Character
    if character then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            humanoid.UseJumpPower = true
            humanoid.JumpPower = power
        end
    end
end

-- Hook character respawn to apply speed & jump persistent values
LocalPlayer.CharacterAdded:Connect(function(character)
    character:WaitForChild("Humanoid")
    task.wait(0.5)
    if MainFunctions.CurrentSpeed ~= 16 then
        MainFunctions.SetWalkSpeed(MainFunctions.CurrentSpeed)
    end
    if MainFunctions.CurrentJump ~= 50 then
        MainFunctions.SetJumpPower(MainFunctions.CurrentJump)
    end
end)

-- Anti-AFK Engine
function MainFunctions.EnableAntiAFK()
    if MainFunctions.AntiAFKConnection then return end

    MainFunctions.AntiAFKConnection = LocalPlayer.Idled:Connect(function()
        VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
        task.wait(1)
        VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
    end)
end

function MainFunctions.DisableAntiAFK()
    if MainFunctions.AntiAFKConnection then
        MainFunctions.AntiAFKConnection:Disconnect()
        MainFunctions.AntiAFKConnection = nil
    end
end

--[[
    GAG 1 Hub - Main Functions: Player Info & Formatting
--]]

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

 

-- Helper number formatting (e.g., 1000000 -> 1,000,000)
function MainFunctions.FormatNumber(n)
    local num = tostring(n)
    return num:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
end

-- Return formatted Player Details for UI paragraph
function MainFunctions.GetPlayerInfo(player)
    player = player or LocalPlayer
    local userId = player.UserId
    local displayName = player.DisplayName
    local name = player.Name
    local accountAge = player.AccountAge

    local coins = 0
    local leaderstats = player:FindFirstChild("leaderstats")
    if leaderstats then
        local shecklesVal = leaderstats:FindFirstChild("Sheckles") or leaderstats:FindFirstChild("Coins") or leaderstats:FindFirstChild("Money")
        if shecklesVal then
            coins = shecklesVal.Value
        end
    end

    local coinFormatted = typeof(coins) == "number" and string.format("%s Sheckles", MainFunctions.FormatNumber(coins)) or tostring(coins)

    return string.format(
        "Username: %s (@%s)\nUser ID: %d\nAccount Age: %d Days\nBalance: %s",
        name, displayName, userId, accountAge, coinFormatted
    )
end
return MainFunctions
end)()

local HatchFunctions = (function()
local HatchFunctions = { Stats = { TotalHatches = 0, LastHatchedPet = 'None' } }
--[[
    GAG 1 Hub - Hatch Functions: Auto Hatching Engine
--]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

 

-- Initialize EggReadyToHatch_RE listener at module level
if not _G.GAG_EggReadyToHatchData then
    _G.GAG_EggReadyToHatchData = {}
    pcall(function()
        local gameEvents = ReplicatedStorage:WaitForChild("GameEvents", 2)
        local re = gameEvents and gameEvents:WaitForChild("EggReadyToHatch_RE", 2)
        if re then
            re.OnClientEvent:Connect(function(data, uuid)
                if uuid and data then
                    _G.GAG_EggReadyToHatchData[tostring(uuid)] = data
                    local clean = tostring(uuid):gsub("[{}]", ""):gsub("%-", ""):lower()
                    _G.GAG_EggReadyToHatchData[clean] = data
                end
            end)
        end
    end)
end

local function cleanUUID(u)
    if not u then return "" end
    return tostring(u):gsub("[{}]", ""):gsub("%-", ""):lower()
end

-- Helper function to find player's farm
local cachedFarm = nil
local cachedPetEggService = nil

-- Helper function to find player's farm (cached)
local function getPlayerFarm()
    if cachedFarm and cachedFarm.Parent then return cachedFarm end

    local ok, getFarm = pcall(function()
        return require(ReplicatedStorage:WaitForChild("Modules", 2):WaitForChild("GetFarm", 2))
    end)
    if ok and type(getFarm) == "function" then
        local farm = pcall(function() return getFarm(LocalPlayer) end) and getFarm(LocalPlayer)
        if farm then 
            cachedFarm = farm
            return farm 
        end
    end

    local farmFolder = workspace:FindFirstChild("Farm")
    if farmFolder then
        cachedFarm = farmFolder:FindFirstChild("Farm") or farmFolder
        return cachedFarm
    end

    for _, f in ipairs(workspace:GetChildren()) do
        if f.Name:lower():find("farm") or f:GetAttribute("Owner") == LocalPlayer.Name or f:GetAttribute("OwnerUserId") == LocalPlayer.UserId then
            cachedFarm = f
            return f
        end
    end
    return nil
end

-- Resolve PetEggService Remote Event (cached)
local function getPetEggService()
    if cachedPetEggService and cachedPetEggService.Parent then return cachedPetEggService end

    local gameEvents = ReplicatedStorage:FindFirstChild("GameEvents")
    if gameEvents and gameEvents:FindFirstChild("PetEggService") then
        cachedPetEggService = gameEvents.PetEggService
        return cachedPetEggService
    end

    cachedPetEggService = ReplicatedStorage:FindFirstChild("PetEggService", true)
    return cachedPetEggService
end

-- Helper to match hatched pet by egg type pool
function HatchFunctions.DetermineHatchedPet(eggName, eggsPetsData)
    if not eggsPetsData or not eggsPetsData.Pets then return nil end

    local matchingPets = {}
    for _, pet in ipairs(eggsPetsData.Pets) do
        if pet.Egg:lower() == tostring(eggName):lower() then
            table.insert(matchingPets, pet)
        end
    end

    if #matchingPets > 0 then
        return matchingPets[math.random(1, #matchingPets)]
    else
        return eggsPetsData.Pets[math.random(1, #eggsPetsData.Pets)]
    end
end

