local petsServiceCache = nil
local petsServiceRemoteCache = nil

local function getPetsService()
    if not petsServiceCache then
        pcall(function()
            if ReplicatedStorage:FindFirstChild("Modules") 
               and ReplicatedStorage.Modules:FindFirstChild("PetServices") 
               and ReplicatedStorage.Modules.PetServices:FindFirstChild("PetsService") then
