function HatchFunctions.EquipPet(uuid, cf)
    if not uuid or uuid == "" then return false end
    cf = cf or (LocalPlayer.Character and LocalPlayer.Character:GetPivot()) or CFrame.new()

    local serviceModule, serviceRemote = getPetsService()
    local success = false

    if serviceModule and typeof(serviceModule) == "table" and type(serviceModule.EquipPet) == "function" then
        success = pcall(function() serviceModule:EquipPet(uuid, cf) end)
    end
    if not success and serviceRemote then
        success = pcall(function() serviceRemote:FireServer("EquipPet", uuid, cf) end)
    end
    return success
end

function HatchFunctions.UnequipPet(uuid)
    if not uuid or uuid == "" then return false end

    local serviceModule, serviceRemote = getPetsService()
    local success = false

    if serviceModule and typeof(serviceModule) == "table" and type(serviceModule.UnequipPet) == "function" then
        success = pcall(function() serviceModule:UnequipPet(uuid) end)
    end
    if not success and serviceRemote then
        success = pcall(function() serviceRemote:FireServer("UnequipPet", uuid) end)
    end
    return success
end

function HatchFunctions.UnequipAllPets()
    local playerData = getPlayerData()
    local equipped = playerData and playerData.PetsData and playerData.PetsData.EquippedPets

    if type(equipped) == "table" and #equipped > 0 then
        for _, uuid in ipairs(equipped) do
            HatchFunctions.UnequipPet(uuid)
        end
    end

    pcall(function()
        local _, serviceRemote = getPetsService()
        if serviceRemote then
            for _, container in ipairs({LocalPlayer.Character, LocalPlayer:FindFirstChildOfClass("Backpack")}) do
                if container then
                    for _, tool in ipairs(container:GetChildren()) do
                        local uuid = tool:GetAttribute("PET_UUID") or tool:GetAttribute("d") or tool:GetAttribute("UUID")
                        if uuid then
                            serviceRemote:FireServer("UnequipPet", tostring(uuid))
                        end
                    end
                end
            end
        end
    end)
end

-- Central Pet Tool Discriminator strictly tailored to GAG 1 Pet Tool Attributes
function HatchFunctions.IsPetTool(tool)
    if not tool or not tool:IsA("Tool") then return false end

    local itemType = tool:GetAttribute("ItemType")
    local petType  = tool:GetAttribute("PetType")
    local petUuid  = tool:GetAttribute("PET_UUID")

    -- Strictly only properties from official GAG 1 Pet Tool: ItemType == "Pet" (or PetType == "Pet") and PET_UUID
    local isPet = (itemType == "Pet" or petType == "Pet") 
              and (petUuid ~= nil and type(petUuid) == "string" and petUuid ~= "")

    return isPet == true
end

-- Helper to format pet weight cleanly (e.g. 68 -> "68Kg", 70 -> "70Kg", 11.86 -> "11.86Kg")
local function formatPetWeightDisplay(w)
    if not w or not tonumber(w) then return "1Kg" end
    local num = tonumber(w)
    if num == math.floor(num) then
        return string.format("%dKg", num)
    else
        local s = string.format("%.2f", num):gsub("%.?0+$", "")
        return s .. "Kg"
    end
end

-- Comprehensive Backpack & Character Pet Scanner using exact Tool Name (e.g. "Alienated Magpie [11.64 KG]")
function HatchFunctions.GetFormattedBackpackPets()
    local player = LocalPlayer or Players.LocalPlayer
    if not player then return {}, {}, {} end

    local backpack = player:FindFirstChildOfClass("Backpack") or player:FindFirstChild("Backpack")
    local character = player.Character

    local rawPets = {}

    local function scanContainer(container)
        if not container then return end
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA("Tool") and HatchFunctions.IsPetTool(tool) then
                local petUuid = tool:GetAttribute("PET_UUID")
                local uuid = petUuid or tool.Name
                local exactToolName = tool.Name

                table.insert(rawPets, {
                    Tool = tool,
                    BaseDisplayName = exactToolName,
                    UUID = uuid
                })
            end
        end
    end

    scanContainer(backpack)
    scanContainer(character)

    local nameCounts = {}
    for _, p in ipairs(rawPets) do
        nameCounts[p.BaseDisplayName] = (nameCounts[p.BaseDisplayName] or 0) + 1
    end

    local nameIndexes = {}
    local petOptionList = {}
    local toolMap = {}
    local toolInstanceMap = {}

    for _, p in ipairs(rawPets) do
        local finalName = p.BaseDisplayName
        if nameCounts[p.BaseDisplayName] > 1 then
            nameIndexes[p.BaseDisplayName] = (nameIndexes[p.BaseDisplayName] or 0) + 1
            finalName = string.format("%s #%d", p.BaseDisplayName, nameIndexes[p.BaseDisplayName])
        end

        table.insert(petOptionList, finalName)

        toolMap[finalName] = p.UUID
        toolInstanceMap[finalName] = p.Tool

        if not toolMap[p.BaseDisplayName] then
            toolMap[p.BaseDisplayName] = p.UUID
            toolInstanceMap[p.BaseDisplayName] = p.Tool
        end
        if not toolMap[p.Tool.Name] then
            toolMap[p.Tool.Name] = p.UUID
            toolInstanceMap[p.Tool.Name] = p.Tool
        end
    end

    table.sort(petOptionList)
    return petOptionList, toolMap, toolInstanceMap
end

function HatchFunctions.EquipTeam(teamList)
    if not teamList or type(teamList) ~= "table" or #teamList == 0 then return end

    HatchFunctions.UnequipAllPets()
    task.wait(0.3)

    local petOptions, toolMap, toolInstanceMap = HatchFunctions.GetFormattedBackpackPets()
    local character = LocalPlayer.Character
    local baseCF = (character and character:GetPivot()) or CFrame.new()

    local targetUUIDs = {}
    for i, displayName in ipairs(teamList) do
        local uuid = toolMap and toolMap[displayName]
        if not uuid then
            local baseName = displayName:match("^(.-)%s*#%d+$") or displayName
            uuid = toolMap and toolMap[baseName]
        end

        if uuid then
            table.insert(targetUUIDs, tostring(uuid))
            local offsetCF = baseCF * CFrame.new(math.sin(i) * 3, 0, math.cos(i) * 3)
            HatchFunctions.EquipPet(uuid, offsetCF)
            task.wait(0.1)
        elseif toolInstanceMap and toolInstanceMap[displayName] then
            local tool = toolInstanceMap[displayName]
            pcall(function()
                if character and character:FindFirstChildOfClass("Humanoid") then
                    character.Humanoid:EquipTool(tool)
                end
            end)
            task.wait(0.1)
        end
    end

    -- Verification loop: Ensure all target pets are equipped before proceeding
    if #targetUUIDs > 0 then
        local startTime = tick()
        repeat
            local playerData = getPlayerData()
            local equipped = playerData and playerData.PetsData and playerData.PetsData.EquippedPets
            local allEquipped = true

            if type(equipped) == "table" then
                for _, targetUuid in ipairs(targetUUIDs) do
                    local found = false
                    for k, v in pairs(equipped) do
                        local eqUuid = (type(v) == "string" and v) or (type(k) == "string" and k) or v
                        if eqUuid and (cleanUUID(eqUuid) == cleanUUID(targetUuid) or tostring(eqUuid) == tostring(targetUuid)) then
                            found = true
                            break
                        end
                    end
                    if not found then
                        allEquipped = false
                        break
                    end
                end
            else
                allEquipped = true -- fallback if DataService EquippedPets unavailable
            end

            if allEquipped then break end
            task.wait(0.15)
        until tick() - startTime > 1.5 -- Timeout max 1.5s
    end

    task.wait(0.3)
end

local function getReplicatedPetData()
    local ok, repl = pcall(function()
        local repClass = require(ReplicatedStorage.Modules.ReplicationClass)
        local rep = repClass.get and repClass.get("ActivePetsService_Replicator")
        if rep and rep.YieldUntilData then
            return rep:YieldUntilData()
        end
        return nil
    end)
    if ok and repl and type(repl) == "table" then
        return repl.Table or repl
    end
    return nil
end

---- Helper to fetch t4 ready egg data from Roblox event connections upvalues
local function fetchT4FromConnections()
    local t4Cache = {}
    pcall(function()
        local getUp = debug.getupvalues or getupvalues
        local gameEvents = ReplicatedStorage:FindFirstChild("GameEvents")
        local re = gameEvents and gameEvents:FindFirstChild("EggReadyToHatch_RE")
        if re and typeof(getconnections) == "function" then
            for _, conn in ipairs(getconnections(re.OnClientEvent)) do
                local fn = conn.Function
                if fn and getUp then
                    local ups = getUp(fn)
                    if ups then
                        for _, v in pairs(ups) do
                            if type(v) == "table" then
                                for k, val in pairs(v) do
                                    local sk = tostring(k)
                                    t4Cache[sk] = val
                                    local clean = cleanUUID(sk)
                                    if clean ~= "" then t4Cache[clean] = val end
                                end
                            end
                        end
                    end
                end
            end
        end
    end)
    return t4Cache
end

------ Helper function to inspect pet details inside an egg on the farm (Identical to egg_esp.lua logic)
function HatchFunctions.GetEggInsidePetDetails(eggObj)
    if not eggObj then return nil, nil end
    local childEggModel = eggObj:FindFirstChildWhichIsA("Model")

    -- Helper to clean pet name string
    local function cleanPetNameStr(str)
        if not str or type(str) ~= "string" then return nil end
        local s = str:gsub("%s*%[[%d%.]+%s*[Kk][Gg]%]", ""):gsub("%s*%(([%d%.]+)%s*[Kk][Gg]%)", ""):gsub("%s*[%d%.]+%s*[Kk][Gg]", ""):gsub("%s*%[Age%s*%d+%]", "")
        s = s:gsub("%s*%[.-%]", ""):gsub("%s*%((.-)%)", ""):gsub("^Hatch%s*", ""):gsub("^Open%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
        local l = s:lower()
        if l == "egg" or l == "petegg" or l == "common egg" or l:find("proximity") or s == "" then
            return nil
        end
        return s
    end

    -- 1. Direct attribute checks
    local petName = cleanPetNameStr(eggObj:GetAttribute("PetName") or eggObj:GetAttribute("Species") or (childEggModel and (childEggModel:GetAttribute("PetName") or childEggModel:GetAttribute("Species"))))
    
    local petWeight = eggObj:GetAttribute("Weight") 
                   or eggObj:GetAttribute("KG") 
                   or eggObj:GetAttribute("w")
                   or eggObj:GetAttribute("PetWeight")
                   or eggObj:GetAttribute("RealWeight")
                   or eggObj:GetAttribute("CalculatedWeight")
                   or (childEggModel and (childEggModel:GetAttribute("Weight") or childEggModel:GetAttribute("KG") or childEggModel:GetAttribute("w") or childEggModel:GetAttribute("PetWeight")))

    if not petWeight then
        for attrName, attrVal in pairs(eggObj:GetAttributes()) do
            local lAttr = attrName:lower()
            if lAttr:find("weight") or lAttr == "kg" or lAttr == "w" or lAttr:find("petweight") then
                if tonumber(attrVal) then
                    petWeight = tonumber(attrVal)
                    break
                end
            end
        end
    end

    -- Try parsing weight from instance names & descendants (ProximityPrompt, BillboardGui, TextLabels)
    if not petWeight then
        local textSources = { eggObj.Name }
        if childEggModel then table.insert(textSources, childEggModel.Name) end
        for _, child in ipairs(eggObj:GetDescendants()) do
            if child:IsA("ProximityPrompt") then
                if child.ActionText and child.ActionText ~= "" then table.insert(textSources, child.ActionText) end
                if child.ObjectText and child.ObjectText ~= "" then table.insert(textSources, child.ObjectText) end
            elseif child:IsA("TextLabel") or child:IsA("TextButton") then
                if child.Text and child.Text ~= "" then table.insert(textSources, child.Text) end
            end
        end
        for _, txt in ipairs(textSources) do
            local sTxt = tostring(txt)
            local parsedKG = sTxt:match("%[([%d%.]+)%s*[Kk][Gg]%]") or sTxt:match("%(([%d%.]+)%s*[Kk][Gg]%)") or sTxt:match("([%d%.]+)%s*[Kk][Gg]")
            if parsedKG and tonumber(parsedKG) then
                petWeight = tonumber(parsedKG)
                break
            end
        end
    end

    if petName and petWeight then
        return petName, tonumber(petWeight)
    end

    -- 2. Inspect candidates list for Network/Cache/Upvalues/DataService (Exact egg_esp.lua algorithm)
    local candidates = {}
    local function cleanUUID(raw)
        if not raw then return "" end
        return tostring(raw):gsub("[{}]", ""):gsub("%-", ""):lower()
    end

    local function addCandidate(val)
        if not val or val == "" then return end
        local s = tostring(val)
        table.insert(candidates, s)
        local clean = cleanUUID(s)
        if clean ~= "" and clean ~= s:lower() then
            table.insert(candidates, clean)
        end
    end

    addCandidate(eggObj:GetAttribute("OBJECT_UUID"))
    addCandidate(eggObj:GetAttribute("CosmeticUUID"))
    addCandidate(eggObj:GetAttribute("UUID"))
    addCandidate(eggObj:GetAttribute("EggUUID"))
    addCandidate(eggObj:GetAttribute("Id") or eggObj:GetAttribute("ID"))
    for attrName, attrVal in pairs(eggObj:GetAttributes()) do
        if type(attrVal) == "string" and (#attrVal > 8 or attrVal:find("%-")) then
            addCandidate(attrVal)
        end
    end
    if childEggModel then
        addCandidate(childEggModel:GetAttribute("OBJECT_UUID"))
        addCandidate(childEggModel:GetAttribute("CosmeticUUID"))
        addCandidate(childEggModel:GetAttribute("UUID"))
        addCandidate(childEggModel:GetAttribute("EggUUID"))
        for attrName, attrVal in pairs(childEggModel:GetAttributes()) do
            if type(attrVal) == "string" and (#attrVal > 8 or attrVal:find("%-")) then
                addCandidate(attrVal)
            end
        end
    end

    local petRegistry = getPetRegistry()
    local petUtils = getPetUtils()
    local playerData = getPlayerData()
    local replData = getReplicatedPetData()

    local function extractPetDetails(e)
        if not e then return nil, nil end
        local rawName, weight = nil, nil

        if type(e) == "string" then
            rawName = e
        elseif type(e) == "table" then
            local targetTbl = e
            if type(e.GeneratedPetData) == "table" then
                targetTbl = e.GeneratedPetData
            elseif type(e.PetData) == "table" then
                targetTbl = e.PetData
            elseif type(e.Data) == "table" then
                targetTbl = e.Data
            end

            rawName = targetTbl.PetType or targetTbl.Species or targetTbl.PetName or targetTbl.Name or targetTbl.Type or targetTbl.Pet or e.PetType or e.Species or e.PetName or e.Name or e.Type or e.Pet or e.IncubatedEgg

            if petUtils and type(targetTbl) == "table" then
                pcall(function()
                    local res = nil
                    if type(petUtils.GetPetWeight) == "function" then
                        res = petUtils.GetPetWeight(targetTbl) or petUtils.GetPetWeight(e)
                    elseif type(petUtils.CalculatePetWeight) == "function" then
                        res = petUtils.CalculatePetWeight(targetTbl) or petUtils.CalculatePetWeight(e)
                    elseif type(petUtils.CalculateWeight) == "function" then
                        res = petUtils.CalculateWeight(targetTbl) or petUtils.CalculateWeight(e)
                    elseif type(petUtils.GetWeight) == "function" then
                        res = petUtils.GetWeight(targetTbl) or petUtils.GetWeight(e)
                    end
                    if res and tonumber(res) then
                        weight = tonumber(res)
                    end
                end)
            end

            local function scanForWeight(tbl)
                if type(tbl) ~= "table" then return nil end

                local explicitW = tbl.PetWeight or tbl.petWeight or tbl.WeightKG or tbl.weightKG or tbl.weight_kg or tbl.RealWeight or tbl.realWeight or tbl.CalculatedWeight or tbl.calculatedWeight or tbl.FinalWeight or tbl.finalWeight or tbl.DisplayWeight or tbl.displayWeight
                if explicitW and tonumber(explicitW) then
                    return tonumber(explicitW)
                end

                local bw = tbl.BaseWeight or tbl.baseWeight or tbl.base_weight
                local rawW = tbl.Weight or tbl.weight or tbl.KG or tbl.kg or tbl.Kg
                local baseVal = tonumber(bw) or tonumber(rawW)
                local wm = tbl.WeightMultiplier or tbl.weightMultiplier or tbl.WeightMult or tbl.weightMult or tbl.WeightScale or tbl.weightScale or tbl.WeightMod or tbl.weightMod or tbl.Multiplier or tbl.multiplier or tbl.Scale or tbl.scale

                if baseVal and wm and tonumber(wm) and tonumber(wm) ~= 1 then
                    return baseVal * tonumber(wm)
                end

                if baseVal then return baseVal end

                for k, v in pairs(tbl) do
                    local lk = tostring(k):lower()
                    if (lk:find("petweight") or lk:find("realweight") or lk:find("finalweight") or lk:find("weightkg") or lk == "weight" or lk == "kg" or lk == "w") then
                        if tonumber(v) then return tonumber(v) end
                    end
                end

                for k, v in pairs(tbl) do
                    local lk = tostring(k):lower()
                    if type(v) == "number" and v > 0.05 and v < 10000 and lk ~= "hatchtime" and lk ~= "timetohatch" and lk ~= "cost" and lk ~= "price" and lk ~= "multiplier" and lk ~= "chance" then
                        return v
                    end
                end
                return nil
            end

            if not weight then
                weight = scanForWeight(targetTbl) or scanForWeight(e)
            end

            if weight and tonumber(weight) then
                local wNum = tonumber(weight)
                pcall(function()
                    local applied = false
                    if rawName and petRegistry then
                        local petDef = (petRegistry.Pets and petRegistry.Pets[tostring(rawName)])
                                    or (petRegistry.PetData and petRegistry.PetData[tostring(rawName)])
                                    or (type(petRegistry) == "table" and petRegistry[tostring(rawName)])
                        if petDef then
                            local speciesBaseW = petDef.BaseWeight or petDef.baseWeight or petDef.Weight or petDef.weight or petDef.BaseKG or petDef.baseKG or petDef.WeightMultiplier or petDef.weightMultiplier
                            if speciesBaseW and tonumber(speciesBaseW) and tonumber(speciesBaseW) > 0 then
                                wNum = wNum * tonumber(speciesBaseW)
                                applied = true
                            end
                        end
                    end
                    if not applied and not (type(targetTbl) == "table" and (targetTbl.PetWeight or targetTbl.FinalWeight or targetTbl.CalculatedWeight)) then
                        wNum = wNum * 1.10
                    end
                end)
                weight = wNum
            end
        end

        if not rawName then return nil, weight and tonumber(weight) or nil end
        local sName = cleanPetNameStr(tostring(rawName))
        local lowerPName = sName:lower()

        if lowerPName:find("egg") or lowerPName == "egg" or lowerPName == "petegg" then
            return nil, weight and tonumber(weight) or nil
        end

        return sName, weight and tonumber(weight) or nil
    end

    local t4Data = fetchT4FromConnections()
    for _, cand in ipairs(candidates) do
        local readyEntry = (_G.GAG_EggReadyToHatchData and _G.GAG_EggReadyToHatchData[cand]) or t4Data[cand]
        if readyEntry then
            local n, w = extractPetDetails(readyEntry)
            if n and not petName then petName = n end
            if w and not petWeight then petWeight = w end
        end

        if (not petName or not petWeight) and playerData and playerData.PetsData and playerData.PetsData.PetEggIncubatorData and playerData.PetsData.PetEggIncubatorData.IncubatorData then
            local incData = playerData.PetsData.PetEggIncubatorData.IncubatorData
            local entry = incData[cand]
            if not entry then
                for k, v in pairs(incData) do
                    if cleanUUID(k) == cand or tostring(k) == cand then
                        entry = v
                        break
                    end
                end
            end
            if entry then
                local n, w = extractPetDetails(entry)
                if n and not petName then petName = n end
                if w and not petWeight then petWeight = w end
            end
        end

        if (not petName or not petWeight) and replData then
            if type(replData.ServerPetData) == "table" then
                for k, sp in pairs(replData.ServerPetData) do
                    if cleanUUID(k) == cand or cleanUUID(sp.UUID) == cand or cleanUUID(sp.OBJECT_UUID) == cand or tostring(k) == cand then
                        local n, w = extractPetDetails(sp)
                        if n and not petName then petName = n end
                        if w and not petWeight then petWeight = w end
                    end
                end
            end

            if (not petName or not petWeight) and type(replData.PlayerPetData) == "table" then
                for _, pData in pairs(replData.PlayerPetData) do
                    if type(pData) == "table" and pData.PetInventory and type(pData.PetInventory.Data) == "table" then
                        for k, pItem in pairs(pData.PetInventory.Data) do
                            if cleanUUID(k) == cand or cleanUUID(pItem.UUID) == cand or cleanUUID(pItem.OBJECT_UUID) == cand or tostring(k) == cand then
                                local n, w = extractPetDetails(pItem)
                                if n and not petName then petName = n end
                                if w and not petWeight then petWeight = w end
                            end
                        end
                    end
                end
            end
        end

        if petName and petWeight then break end
    end

    if (not petName or not petWeight) and playerData then
        local function searchTable(tbl, depth)
            if depth > 5 or type(tbl) ~= "table" then return end
            
            for k, v in pairs(tbl) do
                if type(v) == "table" then
                    local kClean = cleanUUID(k)
                    local match = false
                    for _, cand in ipairs(candidates) do
                        if kClean == cand or tostring(k) == cand or
                           (v.UUID and cleanUUID(v.UUID) == cand) or
                           (v.OBJECT_UUID and cleanUUID(v.OBJECT_UUID) == cand) or
                           (v.CosmeticUUID and cleanUUID(v.CosmeticUUID) == cand) or
                           (v.EggUUID and cleanUUID(v.EggUUID) == cand) or
                           (v.Id and cleanUUID(v.Id) == cand) then
                            match = true
                            break
                        end
                    end
                    
                    if match then
                        local n, w = extractPetDetails(v)
                        if n and not petName then petName = n end
                        if w and not petWeight then petWeight = w end
                        if petName and petWeight then return end
                    else
                        searchTable(v, depth + 1)
                        if petName and petWeight then return end
                    end
                end
            end
        end

        searchTable(playerData, 1)
    end

    if not petName or not petWeight then
        for _, child in ipairs(eggObj:GetChildren()) do
            if child:IsA("Model") and child.Name ~= "Data" and child.Name ~= "PetEgg" then
                if not petName then petName = cleanPetNameStr(child.Name) end
            end
            if child.Name == "Data" or child.Name == "PetEgg" then
                if not petName then
                    local nv = child:FindFirstChild("PetName") or child:FindFirstChild("Species") or child:FindFirstChild("Name")
                    if nv and nv:IsA("StringValue") then petName = cleanPetNameStr(nv.Value) end
                end
                if not petWeight then
                    local wv = child:FindFirstChild("Weight") or child:FindFirstChild("KG") or child:FindFirstChild("PetWeight")
                    if wv and (wv:IsA("NumberValue") or wv:IsA("IntValue")) then petWeight = wv.Value end
                end
            end
        end
    end

    return petName, petWeight and tonumber(petWeight) or petWeight
end



---- Helper function to get all ready placed eggs on player's farm (Normal Hatch & Hatch Filter)
function HatchFunctions.GetReadyPlacedEggs(automation, enforceHatchFilter)
    local readyEggs = {}
    local playerFarm = getPlayerFarm()
    local important = playerFarm and playerFarm:FindFirstChild("Important", true)
    local objectsPhys = important and important:FindFirstChild("Objects_Physical")
    
    if not objectsPhys and playerFarm then
        objectsPhys = playerFarm:FindFirstChild("Objects_Physical", true)
    end

    local localPlayer = LocalPlayer or Players.LocalPlayer
    local localName = localPlayer and localPlayer.Name or ""
    local localUserId = localPlayer and localPlayer.UserId or 0

    local function isPlayerEggOwner(eggObj)
        local ownerAttr = eggObj:GetAttribute("OWNER") or eggObj:GetAttribute("Owner") or eggObj:GetAttribute("OwnerUserId") or eggObj:GetAttribute("Player") or eggObj:GetAttribute("UserId")
        if not ownerAttr then return true end
        if type(ownerAttr) == "string" and (ownerAttr == localName or ownerAttr:lower() == localName:lower()) then
            return true
        elseif tonumber(ownerAttr) and tonumber(ownerAttr) == localUserId then
            return true
        end
        return false
    end

    local function processEgg(eggObj)
        if not isPlayerEggOwner(eggObj) then return end

        local isEgg = eggObj:GetAttribute("OBJECT_TYPE") == "PetEgg"
                   or eggObj:GetAttribute("EggName") ~= nil

        if not isEgg then return end

        local timeToHatch = tonumber(eggObj:GetAttribute("TimeToHatch"))
        if timeToHatch and timeToHatch <= 0 then
            table.insert(readyEggs, eggObj)
        end
    end

    if objectsPhys then
        for _, eggObj in ipairs(objectsPhys:GetChildren()) do
            processEgg(eggObj)
        end
    end

    pcall(function()
        local cs = game:GetService("CollectionService")
        for _, serverEgg in ipairs(cs:GetTagged("PetEggServer")) do
            if isPlayerEggOwner(serverEgg) then
                if not table.find(readyEggs, serverEgg) then
                    processEgg(serverEgg)
                end
            end
        end
    end)

    if #readyEggs == 0 then return {} end

    local targetHatchPets = automation and automation.Settings and automation.Settings.HatchTargetPets
    local hasTargetHatchPets = false
    if type(targetHatchPets) == "table" then
        if #targetHatchPets > 0 then
            hasTargetHatchPets = true
        else
            for _, isSel in pairs(targetHatchPets) do
                if isSel then hasTargetHatchPets = true; break end
            end
        end
    end

    if enforceHatchFilter then
        if not hasTargetHatchPets then
            -- SAFETY SKIP: No target pets selected in Hatch filter -> DO NOT HATCH ANY EGG!
            return {}
        end

        local filteredEggs = {}
        for _, eggObj in ipairs(readyEggs) do
            local petName, _ = HatchFunctions.GetEggInsidePetDetails(eggObj)
            if petName then
                local pNameClean = tostring(petName):gsub("%s*%((.-)%)", ""):gsub("%s*%[.-%]", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
                local matched = false
                if type(targetHatchPets) == "table" and #targetHatchPets > 0 then
                    for _, target in ipairs(targetHatchPets) do
                        local tClean = tostring(target):gsub("%s*%((.-)%)", ""):gsub("%s*%[.-%]", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
                        if pNameClean == tClean or pNameClean:find(tClean, 1, true) or tClean:find(pNameClean, 1, true) then
                            matched = true
                            break
                        end
                    end
                else
                    for target, isSel in pairs(targetHatchPets) do
                        if isSel then
                            local tClean = tostring(target):gsub("%s*%((.-)%)", ""):gsub("%s*%[.-%]", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
                            if pNameClean == tClean or pNameClean:find(tClean, 1, true) or tClean:find(pNameClean, 1, true) then
                                matched = true
                                break
                            end
                        end
                    end
                end
                if matched then table.insert(filteredEggs, eggObj) end
            end
        end
        return filteredEggs
    else
        return readyEggs
    end
end

-- Core Hatch Execution Step using PetEggService:FireServer("HatchPet", eggObj)
function HatchFunctions.HatchEggStep(eggName, amount, eggsPetsData, automation, enforceHatchFilter)
    amount = amount or 99
    local petEggService = getPetEggService()

    local readyEggs = HatchFunctions.GetReadyPlacedEggs(automation, enforceHatchFilter)
    local totalHatchedCount = 0

    if readyEggs and #readyEggs > 0 then
        for i = 1, math.min(amount, #readyEggs) do
            local eggObj = readyEggs[i]
            local actualEggName = eggObj:GetAttribute("EggName") or eggName or "Egg"

            local success = false
            if petEggService then
                success = pcall(function()
                    petEggService:FireServer("HatchPet", eggObj)
                end)
            end

            pcall(function()
                local petEgg = eggObj:FindFirstChild("PetEgg") or eggObj
                local promptAtt = petEgg:FindFirstChild("ProximityPromptAtt") or eggObj:FindFirstChild("ProximityPromptAtt")
                local prompt = (promptAtt or petEgg):FindFirstChild("ProximityPrompt") or eggObj:FindFirstChildWhichIsA("ProximityPrompt", true)
                if prompt and typeof(fireproximityprompt) == "function" then
                    fireproximityprompt(prompt)
                    success = true
                end
            end)

            if success then
                totalHatchedCount = totalHatchedCount + 1
                HatchFunctions.Stats.TotalHatches = (HatchFunctions.Stats.TotalHatches or 0) + 1
                
                local petHatched = HatchFunctions.DetermineHatchedPet(actualEggName, eggsPetsData)
                if petHatched then
                    HatchFunctions.Stats.LastHatchedPet = petHatched.Name
                end
            end
        end
    end

    -- Fallback: If no placed egg instances found and filter not enforced, fire general remote
    if totalHatchedCount == 0 and (#readyEggs == 0) and not enforceHatchFilter then
        if petEggService then
            pcall(function()
                petEggService:FireServer("HatchPet")
            end)
        end
    end

    if totalHatchedCount > 0 and typeof(HatchFunctions.UIUpdateCallback) == "function" then
        pcall(HatchFunctions.UIUpdateCallback)
    end

    return totalHatchedCount > 0
end

-- Helper to count total eggs currently placed in player's garden (ready or in cooldown)
function HatchFunctions.GetTotalPlacedEggsCount()
    local totalEggs = {}
    local playerFarm = getPlayerFarm()
    local objectsPhys = playerFarm and (playerFarm:FindFirstChild("Important", true) and playerFarm:FindFirstChild("Important", true):FindFirstChild("Objects_Physical") or playerFarm:FindFirstChild("Objects_Physical", true))
    local localName = (LocalPlayer or Players.LocalPlayer).Name

    local function checkEgg(eggObj)
        local owner = eggObj:GetAttribute("OWNER")
        if owner and owner ~= localName then return end

        -- Identify egg by OBJECT_TYPE or EggName attribute
        local isEgg = eggObj:GetAttribute("OBJECT_TYPE") == "PetEgg"
                   or eggObj:GetAttribute("EggName") ~= nil

        if isEgg and not table.find(totalEggs, eggObj) then
            table.insert(totalEggs, eggObj)
        end
    end

    if objectsPhys then
        for _, eggObj in ipairs(objectsPhys:GetChildren()) do
            checkEgg(eggObj)
        end
    end

    pcall(function()
        local cs = game:GetService("CollectionService")
        for _, serverEgg in ipairs(cs:GetTagged("PetEggServer")) do
            local owner = serverEgg:GetAttribute("OWNER")
            if not owner or owner == localName then
                checkEgg(serverEgg)
            end
        end
    end)

    return #totalEggs
end

--[[
    GAG 1 Hub - Hatch Functions: Bronto Mode Engine
    Dedicated file for Bronto Mode filtering, matching logic & remote execution.
--]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- Resolve Bronto Remote
local GameEvents = ReplicatedStorage:FindFirstChild("GameEvents")
local BrontoRemote = (GameEvents and GameEvents:FindFirstChild("BrontoMode")) 
    or ReplicatedStorage:FindFirstChild("BrontoMode", true) 
    or ReplicatedStorage:FindFirstChild("PetBronto", true)

-- Helper function to check if egg inside pet matches Bronto Mode criteria
function HatchFunctions.IsBrontoMatchEgg(eggObj, automation)
    if not eggObj or not automation or not automation.Settings then return false end
    
    local minKG = tonumber(automation.Settings.BrontoMinKG) or 0.0
    local weightCondition = automation.Settings.BrontoWeightCondition or "Above"
    local modeType = automation.Settings.BrontoModeType or "Weight Only"
    
    local rawTargetPets = automation.Settings.BrontoTargetPets or automation.Settings.BrontoPets or automation.Settings.BrontoPet
    local targetPetList = {}
    if type(rawTargetPets) == "table" then
        targetPetList = rawTargetPets
    elseif type(rawTargetPets) == "string" and rawTargetPets ~= "" then
        targetPetList = { rawTargetPets }
    end

    local petName, petWeight = HatchFunctions.GetEggInsidePetDetails(eggObj)
    
    local eggName = tostring(eggObj:GetAttribute("EggName") or eggObj.Name or ""):lower()
    local name = tostring(petName or ""):lower()
    local kg = tonumber(petWeight)

    -- Strict real-time direct fallback scan on egg instance if petWeight was not in data tables
    if not kg then
        local rawW = eggObj:GetAttribute("Weight") 
               or eggObj:GetAttribute("KG") 
               or eggObj:GetAttribute("w") 
               or eggObj:GetAttribute("PetWeight") 
               or eggObj:GetAttribute("RealWeight") 
               or eggObj:GetAttribute("CalculatedWeight")
               or eggObj:GetAttribute("WeightKG")
        if not rawW then
            local childModel = eggObj:FindFirstChildWhichIsA("Model")
            if childModel then
                rawW = childModel:GetAttribute("Weight") or childModel:GetAttribute("KG") or childModel:GetAttribute("w") or childModel:GetAttribute("PetWeight")
            end
        end
        if not rawW then
            local sTxt = eggObj.Name .. " "
            for _, child in ipairs(eggObj:GetDescendants()) do
                if child:IsA("ProximityPrompt") then
                    sTxt = sTxt .. (child.ActionText or "") .. " " .. (child.ObjectText or "") .. " "
                elseif child:IsA("TextLabel") or child:IsA("TextButton") then
                    sTxt = sTxt .. (child.Text or "") .. " "
                end
            end
            local parsedKG = sTxt:match("%[([%d%.]+)%s*[Kk][Gg]%]") or sTxt:match("%(([%d%.]+)%s*[Kk][Gg]%)") or sTxt:match("([%d%.]+)%s*[Kk][Gg]")
            if parsedKG then rawW = parsedKG end
        end
        if rawW and tonumber(rawW) then
            kg = tonumber(rawW)
        end
    end

    -- Strict Weight Evaluation: if weight cannot be resolved, isWeightMatch MUST be false!
    local isWeightMatch = false
    if kg then
        if weightCondition == "Below" then
            isWeightMatch = (kg <= minKG)
        else
            isWeightMatch = (kg >= minKG)
        end
    end

    local isNameMatch = false
    if #targetPetList > 0 then
        for _, rawTarget in ipairs(targetPetList) do
            local targetPetName = tostring(rawTarget):gsub("%s*%((.-)%)", ""):gsub("%s*%[.-%]", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
            if targetPetName ~= "" then
                if (name ~= "" and name ~= "egg" and name ~= "petegg" and (name:find(targetPetName, 1, true) or targetPetName:find(name, 1, true)))
                   or (eggName ~= "" and eggName:find(targetPetName:gsub("%s*egg$", ""), 1, true)) then
                    isNameMatch = true
                    break
                end
            end
        end
    end

    if modeType == "Weight Only" then
        return isWeightMatch
    elseif modeType == "Weight + Selected Pet" then
        return isNameMatch or isWeightMatch
    end
    
    return false
end

-- Helper function to get only ready eggs matching Bronto Mode criteria
function HatchFunctions.GetReadyBrontoEggs(automation)
    local readyBronto = {}
    local playerFarm = getPlayerFarm()
    local important = playerFarm and playerFarm:FindFirstChild("Important", true)
    local objectsPhys = important and important:FindFirstChild("Objects_Physical")
    
    if not objectsPhys and playerFarm then
        objectsPhys = playerFarm:FindFirstChild("Objects_Physical", true)
    end

    local localPlayer = LocalPlayer or Players.LocalPlayer
    local localName = localPlayer and localPlayer.Name or ""
    local localUserId = localPlayer and localPlayer.UserId or 0

    local function isPlayerEggOwner(eggObj)
        local ownerAttr = eggObj:GetAttribute("OWNER") or eggObj:GetAttribute("Owner") or eggObj:GetAttribute("OwnerUserId") or eggObj:GetAttribute("Player") or eggObj:GetAttribute("UserId")
        if not ownerAttr then return true end
        if type(ownerAttr) == "string" and (ownerAttr == localName or ownerAttr:lower() == localName:lower()) then
            return true
        elseif tonumber(ownerAttr) and tonumber(ownerAttr) == localUserId then
            return true
        end
        return false
    end

    local function checkBrontoEgg(eggObj)
        if not isPlayerEggOwner(eggObj) then return end

        local isEgg = eggObj:GetAttribute("OBJECT_TYPE") == "PetEgg"
                   or eggObj:GetAttribute("EggName") ~= nil

        if not isEgg then return end

        local timeToHatch = tonumber(eggObj:GetAttribute("TimeToHatch"))
        if timeToHatch and timeToHatch <= 0 then
            if HatchFunctions.IsBrontoMatchEgg(eggObj, automation) then
                table.insert(readyBronto, eggObj)
            end
        end
    end

    if objectsPhys then
        for _, eggObj in ipairs(objectsPhys:GetChildren()) do
            checkBrontoEgg(eggObj)
        end
    end

    pcall(function()
        local cs = game:GetService("CollectionService")
        for _, serverEgg in ipairs(cs:GetTagged("PetEggServer")) do
            if isPlayerEggOwner(serverEgg) then
                if not table.find(readyBronto, serverEgg) then
                    checkBrontoEgg(serverEgg)
                end
            end
        end
    end)

    return readyBronto
end

-- Helper function to calculate active Bronto skill percentage capped at max 30%
function HatchFunctions.GetActiveBrontoSkillPercent()
    local totalPercent = 0
    local found = false

    local petList = nil
    local passReg = nil
    pcall(function()
        if ReplicatedStorage:FindFirstChild("Data") and ReplicatedStorage.Data:FindFirstChild("PetRegistry") then
            local pr = ReplicatedStorage.Data.PetRegistry
            if pr:FindFirstChild("PetList") then petList = require(pr.PetList) end
            if pr:FindFirstChild("PassiveRegistry") then passReg = require(pr.PassiveRegistry) end
        end
    end)

    local function inspectCandidate(petName, petWeight, petMutation, petLevel)
        if not petName or petName == "" then return end
        local pLower = tostring(petName):lower()
        if not (pLower:find("bronto") or pLower:find("giant incubator")) then return end

        local petDef = petList and (petList[tostring(petName)] or petList[tostring(petName):gsub("%s*%[[^%]]+%]%s*", "")])
        local passives = {}
        if petDef and petDef.Passives then
            for _, p in pairs(petDef.Passives) do
                if type(p) == "string" then table.insert(passives, p) end
            end
        end
        if #passives == 0 then table.insert(passives, "Giant Incubator") end

        local wVal = tonumber(petWeight) or 1
        local pb = 0
        pcall(function()
            if typeof(PetMutationsData) == "table" and typeof(PetMutationsData.GetPassiveBoost) == "function" then
                pb = PetMutationsData.GetPassiveBoost(petMutation)
            elseif typeof(MiscFunctions) == "table" and typeof(MiscFunctions.GetPassiveBoostForMutation) == "function" then
                pb = MiscFunctions.GetPassiveBoostForMutation(petMutation)
            end
        end)

        if passReg then
            for _, pName in ipairs(passives) do
                local pDef = passReg[tostring(pName)]
                if not pDef then
                    for rK, rV in pairs(passReg) do
                        if tostring(rK):lower() == tostring(pName):lower() then
                            pDef = rV
                            break
                        end
                    end
                end

                if pDef and pDef.States and type(pDef.States) == "table" then
                    for sKey, sDef in pairs(pDef.States) do
                        if type(sDef) == "table" then
                            local base = tonumber(sDef.Base) or 5
                            local scale = tonumber(sDef.Scale) or 0.1
                            local rawV = (base * (1 + pb)) + (wVal * scale)
                            totalPercent = totalPercent + rawV
                            found = true
                        elseif type(sDef) == "number" then
                            totalPercent = totalPercent + sDef
                            found = true
                        end
                    end
                end
            end
        end
    end

    local player = LocalPlayer or Players.LocalPlayer
    if player then
        for _, container in ipairs({player.Character, player:FindFirstChildOfClass("Backpack") or player:FindFirstChild("Backpack")}) do
            if container then
                for _, tool in ipairs(container:GetChildren()) do
                    if tool:IsA("Tool") then
                        local pName = tool:GetAttribute("PetType") or tool:GetAttribute("Species") or tool.Name
                        local pWeight = tool:GetAttribute("Weight") or tool:GetAttribute("KG")
                        local pMutation = tool:GetAttribute("Mutation") or tool:GetAttribute("PetMutation")
                        local pLevel = tool:GetAttribute("Age") or tool:GetAttribute("Level")
                        inspectCandidate(pName, pWeight, pMutation, pLevel)
                    end
                end
            end
        end
    end

    pcall(function()
        local ds = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("DataService") and require(ReplicatedStorage.Modules.DataService)
        if ds and typeof(ds.GetData) == "function" then
            local data = ds:GetData()
            if data and data.PetsData and type(data.PetsData.Pets) == "table" then
                for _, petData in ipairs(data.PetsData.Pets) do
                    if petData.Equipped or petData.IsEquipped then
                        inspectCandidate(petData.PetType or petData.Species or petData.Name, petData.Weight or petData.KG, petData.Mutation, petData.Age or petData.Level)
                    end
                end
            end
        end
    end)

    if not found or totalPercent <= 0 then
        totalPercent = 30 -- Default fallback
    end

    -- Strict Max Cap Rule: Cap at 30% if > 30, but keep actual percentage if < 30%
    return math.min(30, math.max(0, totalPercent))
end

-- Core Hatch Step specifically for Bronto Mode Eggs
function HatchFunctions.HatchBrontoEggStep(eggName, amount, eggsPetsData, automation)
    amount = amount or 99
    local petEggService = getPetEggService()

    local brontoEggs = HatchFunctions.GetReadyBrontoEggs(automation)
    local totalHatchedCount = 0

    if brontoEggs and #brontoEggs > 0 then
        for i = 1, math.min(amount, #brontoEggs) do
            local eggObj = brontoEggs[i]
            local actualEggName = eggObj:GetAttribute("EggName") or eggName or "Egg"

            -- Inspect pet details inside the egg before hatching
            local pName, pWeight = nil, nil
            if typeof(HatchFunctions.GetEggInsidePetDetails) == "function" then
                pcall(function()
                    pName, pWeight = HatchFunctions.GetEggInsidePetDetails(eggObj)
                end)
            end
            if not pName and eggObj then
                pName = eggObj:GetAttribute("PetName") or eggObj:GetAttribute("Species")
            end
            if not pWeight and eggObj then
                pWeight = eggObj:GetAttribute("Weight") or eggObj:GetAttribute("KG") or eggObj:GetAttribute("w") or eggObj:GetAttribute("PetWeight")
            end

            local success = false
            if petEggService then
                success = pcall(function()
                    petEggService:FireServer("HatchPet", eggObj)
                end)
            end

            pcall(function()
                local petEgg = eggObj:FindFirstChild("PetEgg") or eggObj
                local promptAtt = petEgg:FindFirstChild("ProximityPromptAtt") or eggObj:FindFirstChild("ProximityPromptAtt")
                local prompt = (promptAtt or petEgg):FindFirstChild("ProximityPrompt") or eggObj:FindFirstChildWhichIsA("ProximityPrompt", true)
                if prompt and typeof(fireproximityprompt) == "function" then
                    fireproximityprompt(prompt)
                    success = true
                end
            end)

            if success then
                totalHatchedCount = totalHatchedCount + 1
                HatchFunctions.Stats.TotalHatches = (HatchFunctions.Stats.TotalHatches or 0) + 1
                
                local petHatched = HatchFunctions.DetermineHatchedPet(actualEggName, eggsPetsData)
                if petHatched then
                    HatchFunctions.Stats.LastHatchedPet = petHatched.Name
                end

                local finalName = pName
                if (not finalName or finalName == "" or finalName == "Pet" or finalName == "Egg") and petHatched and petHatched.Name then
                    finalName = petHatched.Name
                end
                finalName = tostring(finalName or actualEggName or "Pet"):gsub("%s*%[[^%]]+%]%s*", ""):gsub("%s*%((.-)%)", ""):gsub("^%s+", ""):gsub("%s+$", "")

                -- Calculate Bronto Weight Boost: Capped at Max 30%, or actual if < 30%
                local brontoPercent = HatchFunctions.GetActiveBrontoSkillPercent()
                local brontoMulti = 1 + (brontoPercent / 100)

                local wStr = "Unknown KG"
                local numW = tonumber(pWeight)
                if numW and numW > 0 then
                    local finalW = numW * brontoMulti
                    if finalW % 1 == 0 then
                        wStr = string.format("%dKG", finalW)
                    else
                        wStr = string.format("%.2fKG", finalW):gsub("%.00KG", "KG")
                    end
                elseif type(pWeight) == "string" and pWeight ~= "" then
                    local pParsed = tonumber(pWeight:match("([%d%.]+)"))
                    if pParsed then
                        local finalW = pParsed * brontoMulti
                        if finalW % 1 == 0 then
                            wStr = string.format("%dKG", finalW)
                        else
                            wStr = string.format("%.2fKG", finalW):gsub("%.00KG", "KG")
                        end
                    else
                        wStr = pWeight
                    end
                end

                if typeof(HatchFunctions.RecordBrontoHatch) == "function" then
                    HatchFunctions.RecordBrontoHatch(finalName, wStr)
                end
            end
        end
    end

    if totalHatchedCount > 0 and typeof(HatchFunctions.UIUpdateCallback) == "function" then
        pcall(HatchFunctions.UIUpdateCallback)
    end

    return totalHatchedCount > 0
end

-- Bronto Mode Execution (Support for "Weight Only" and "Weight + Selected Pet", Above/Below conditions)
function HatchFunctions.RunBrontoMode(targetPetName, minKG, weightCondition, brontoModeType)
    minKG = tonumber(minKG) or 50.0
    weightCondition = weightCondition or "Above"
    brontoModeType = brontoModeType or "Weight Only"
    
    local petFolder = LocalPlayer:FindFirstChild("Pets") 
        or (LocalPlayer:FindFirstChild("PlayerData") and LocalPlayer.PlayerData:FindFirstChild("Pets")) 
        or LocalPlayer:FindFirstChild("Backpack")
    if not petFolder then return false end

    for _, petObj in ipairs(petFolder:GetChildren()) do
        local weightVal = petObj:FindFirstChild("Weight") or petObj:FindFirstChild("KG") or petObj:GetAttribute("Weight") or petObj:GetAttribute("KG")
        local kg = tonumber(weightVal and (typeof(weightVal) == "Instance" and weightVal.Value or weightVal)) or 1.0
        local petName = petObj.Name

        local isWeightMatch = (weightCondition == "Below") and (kg <= minKG) or (kg >= minKG)
        local shouldBronto = false

        if brontoModeType == "Weight Only" then
            if isWeightMatch then
                shouldBronto = true
            end
        elseif brontoModeType == "Weight + Selected Pet" then
            if isWeightMatch then
                shouldBronto = true
            elseif targetPetName and petName:lower() == tostring(targetPetName):lower() then
                shouldBronto = true
            end
        end

        if shouldBronto then
            if BrontoRemote then
                pcall(function()
                    if BrontoRemote:IsA("RemoteFunction") then
                        BrontoRemote:InvokeServer(petObj)
                    else
                        BrontoRemote:FireServer(petObj)
                    end
                end)
                return true
            end
        end
    end
    return false
end

--[[
    GAG 1 Hub - Master Auto Hatch Loop Workflow
    Separate module for easier editing & maintenance
--]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

--------------------------------------------------------------------------------
-- WEBHOOK & DATA HELPERS FOR MASTER HATCH
--------------------------------------------------------------------------------

-- Helper: Get client player data from DataService:GetData()
local function getPlayerData()
    local data = nil
    pcall(function()
        local ds = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("DataService") and require(ReplicatedStorage.Modules.DataService)
        if ds then
            if typeof(ds.GetData) == "function" then
                data = ds:GetData() or ds.GetData()
            elseif typeof(ds.Data) == "table" then
                data = ds.Data
            end
        end
    end)
    return data
end

-- Helper 1: Count total pets and max inventory slots from DataService (PetsData.PetInventorySlots)
local function getPetInventorySlotInfo()
    local livePetCount = 0
    local maxSlots = nil
    local countedUUIDs = {}

    -- 1. Scan Backpack and Character tools for EXACT live inventory pet count
    local backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    local character = LocalPlayer.Character

    local toolCount = 0
    local function isPetToolInstance(tool)
        if HatchFunctions and typeof(HatchFunctions.IsPetTool) == "function" then
            return HatchFunctions.IsPetTool(tool)
        end
        return false
    end

    local function scanContainer(container)
        if not container then return end
        for _, tool in ipairs(container:GetChildren()) do
            if isPetToolInstance(tool) then
                toolCount = toolCount + 1
                local petUuid = tool:GetAttribute("PET_UUID")
                             or tool:GetAttribute("OBJECT_UUID")
                             or tool:GetAttribute("UUID")
                             or tool:GetAttribute("ID")
                             or tool:GetAttribute("Id")
                local id = (petUuid and type(petUuid) == "string" and petUuid) or (tool.Name .. "_" .. tostring(toolCount))
                if not countedUUIDs[id] then
                    countedUUIDs[id] = true
                end
            end
        end
    end

    scanContainer(backpack)
    scanContainer(character)

    livePetCount = toolCount

    -- 2. Read server DataService for maxSlots and active pets fallback
    pcall(function()
        local data = getPlayerData()
        if data then
            if type(data.PetsData) == "table" then
                local pd = data.PetsData

                -- Count active non-deleted pets from DataService if toolCount is 0
                if livePetCount == 0 and type(pd.Pets) == "table" then
                    local serverActiveCount = 0
                    for k, pet in pairs(pd.Pets) do
                        if type(pet) == "table" then
                            local isDeleted = (pet.Deleted == true) or (pet.IsDeleted == true) or (pet.Sold == true) or (pet.isDeleted == true)
                            local hasPetID  = (pet.UUID ~= nil) or (pet.PET_UUID ~= nil) or (pet.ID ~= nil) or (pet.Id ~= nil) or (pet.Species ~= nil) or (pet.PetType ~= nil) or (pet.f ~= nil) or (pet.Name ~= nil)
                            if hasPetID and not isDeleted then
                                serverActiveCount = serverActiveCount + 1
                            end
                        end
                    end
                    livePetCount = serverActiveCount
                end

                -- Read Max Slots
                local rawSlots = pd.PetInventorySlots
                              or pd.MaxPetInventorySlots
                              or pd.InventorySlots
                              or pd.PetSlots
                              or pd.MaxPets
                              or pd.PetCapacity
                              or pd.MaxPetCapacity
                              or pd.MaxSlots
                              or pd.Slots
                if rawSlots and tonumber(rawSlots) and tonumber(rawSlots) > 0 then
                    maxSlots = tonumber(rawSlots)
                end
            end

            if not maxSlots and type(data) == "table" then
                local rawSlots = data.PetInventorySlots
                              or data.MaxPetInventorySlots
                              or data.PetSlots
                              or data.MaxPets
                              or data.PetCapacity
                              or data.MaxPetCapacity
                              or data.InventorySlots
                if rawSlots and tonumber(rawSlots) and tonumber(rawSlots) > 0 then
                    maxSlots = tonumber(rawSlots)
                end
            end

            -- Deep Recursive Search across server DataService payload for Max Slots
            if not maxSlots and type(data) == "table" then
                local foundVal = nil
                local function searchTable(tbl, depth)
                    if depth > 4 or foundVal then return end
                    for k, v in pairs(tbl) do
                        local lk = tostring(k):lower()
                        if (lk:find("slot") or lk:find("capacity") or lk:find("maxpet")) and (lk:find("pet") or lk:find("inv") or lk:find("storage")) then
                            local numV = tonumber(v)
                            if numV and numV >= 20 and numV <= 10000 then
                                foundVal = numV
                                return
                            end
                        end
                        if type(v) == "table" and k ~= "Pets" and k ~= "Inventory" and k ~= "Crops" and k ~= "Seeds" then
                            searchTable(v, depth + 1)
                        end
                    end
                end
                searchTable(data, 1)
                if foundVal then maxSlots = foundVal end
            end
        end
    end)

    return livePetCount, maxSlots
end
HatchFunctions.GetPetInventorySlotInfo = getPetInventorySlotInfo

-- Helper 2: Get total egg count and breakdown in backpack
local function getBackpackEggsSummary()
    local backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    local totalEggs = 0
    local eggCounts = {}

    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA("Tool") then
                local attrH = tool:GetAttribute("h")
                local name = tool.Name
                local eggName = nil

                if attrH and type(attrH) == "string" and attrH:find("Egg") then
                    eggName = attrH
                elseif name:find("Egg") then
                    eggName = name:match("^(.-)%s*x%d+") or name:match("^(.-)%s*%(") or name
                end

                if eggName then
                    local qty = tonumber(name:match("x(%d+)") or tool:GetAttribute("Amount") or tool:GetAttribute("Count")) or 1
                    eggCounts[eggName] = (eggCounts[eggName] or 0) + qty
                    totalEggs = totalEggs + qty
                end
            end
        end
    end

    return totalEggs, eggCounts
end

-- Helper to clean pet name by removing [KG], [Age], etc.
local function cleanPetName(str)
    if not str or type(str) ~= "string" then return "" end
    local clean = str:gsub("%s*%[[^%]]+%]%s*", "")
    clean = clean:match("^%s*(.-)%s*$") or clean
    return clean
end

-- Helper 3: Get detailed garden placed eggs summary using exact ESP egg resolver
local function getGardenEggsSummary()
    local localName = (LocalPlayer or Players.LocalPlayer).Name
    local eggsList = {}

    local petRegistry = nil
    pcall(function()
        if ReplicatedStorage:FindFirstChild("Data") and ReplicatedStorage.Data:FindFirstChild("PetRegistry") then
            petRegistry = require(ReplicatedStorage.Data.PetRegistry)
        end
    end)

    local petUtils = nil
    pcall(function()
        petUtils = (ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("PetServices") and ReplicatedStorage.Modules.PetServices:FindFirstChild("PetUtilities") and require(ReplicatedStorage.Modules.PetServices.PetUtilities))
                or (ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("PetUtilities") and require(ReplicatedStorage.Modules.PetUtilities))
    end)

    local playerData = nil
    pcall(function()
        local ds = require(ReplicatedStorage.Modules.DataService)
        if ds and typeof(ds.GetData) == "function" then
            playerData = ds:GetData()
        end
    end)

    local replData = nil
    pcall(function()
        local repClass = require(ReplicatedStorage.Modules.ReplicationClass)
        local rep = repClass.get and repClass.get("ActivePetsService_Replicator")
        if rep and rep.YieldUntilData then
            replData = rep:YieldUntilData()
        end
    end)
    if type(replData) == "table" and replData.Table then
        replData = replData.Table
    end

    local function cleanUUID(raw)
        if not raw then return "" end
        return tostring(raw):gsub("[{}]", ""):gsub("%-", ""):lower()
    end

    local function fetchT4FromConnections()
        local t4Cache = {}
        pcall(function()
            local getUp = debug.getupvalues or getupvalues
            local gameEvents = ReplicatedStorage:FindFirstChild("GameEvents")
            local re = gameEvents and gameEvents:FindFirstChild("EggReadyToHatch_RE")
            if re and getconnections then
                for _, conn in ipairs(getconnections(re.OnClientEvent)) do
                    local fn = conn.Function
                    if fn and getUp then
                        local ups = getUp(fn)
                        if ups then
                            for _, v in pairs(ups) do
                                if type(v) == "table" then
                                    for k, val in pairs(v) do
                                        local sk = tostring(k)
                                        t4Cache[sk] = val
                                        local cKey = cleanUUID(sk)
                                        if cKey ~= "" then t4Cache[cKey] = val end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end)
        return t4Cache
    end
    local t4Data = fetchT4FromConnections()

    local function resolveEggInfo(eggObj, childModel)
        -- 1. Resolve Egg Type Name
        local rawEggName = (eggObj and (eggObj:GetAttribute("EggType") or eggObj:GetAttribute("EggName") or eggObj:GetAttribute("h") or eggObj:GetAttribute("Type")))
                        or (childModel and (childModel:GetAttribute("EggType") or childModel:GetAttribute("EggName") or childModel:GetAttribute("h") or childModel:GetAttribute("Type")))
                        or (eggObj and eggObj.Name)

        if not rawEggName or rawEggName == "PetEgg" or rawEggName == "PetEggServer" or rawEggName == "Model" or rawEggName == "Folder" then
            if childModel and childModel.Name ~= "Model" and childModel.Name ~= "PetEgg" and childModel.Name ~= "Folder" then
                rawEggName = childModel.Name
            end
        end
        if not rawEggName or rawEggName == "PetEgg" or rawEggName == "PetEggServer" or rawEggName == "Model" or rawEggName == "Folder" then
            rawEggName = (eggObj and eggObj:GetAttribute("Egg")) or "Pet Egg"
        end
        local eggName = tostring(rawEggName)

        -- 2. Build Candidate UUIDs
        local candidates = {}
        local function addCand(val)
            if not val or val == "" then return end
            local s = tostring(val)
            table.insert(candidates, s)
            local clean = cleanUUID(s)
            if clean ~= "" and clean ~= s:lower() then
                table.insert(candidates, clean)
            end
        end

        if eggObj then
            addCand(eggObj:GetAttribute("OBJECT_UUID"))
            addCand(eggObj:GetAttribute("CosmeticUUID"))
            addCand(eggObj:GetAttribute("UUID"))
            addCand(eggObj:GetAttribute("EggUUID"))
            addCand(eggObj:GetAttribute("Id") or eggObj:GetAttribute("ID"))
            addCand(eggObj:GetAttribute("d"))
            for attrName, attrVal in pairs(eggObj:GetAttributes()) do
                if type(attrVal) == "string" and (#attrVal > 8 or attrVal:find("%-")) then
                    addCand(attrVal)
                end
            end
        end
        if childModel then
            addCand(childModel:GetAttribute("OBJECT_UUID"))
            addCand(childModel:GetAttribute("CosmeticUUID"))
            addCand(childModel:GetAttribute("UUID"))
            addCand(childModel:GetAttribute("EggUUID"))
            addCand(childModel:GetAttribute("d"))
            for attrName, attrVal in pairs(childModel:GetAttributes()) do
                if type(attrVal) == "string" and (#attrVal > 8 or attrVal:find("%-")) then
                    addCand(attrVal)
                end
            end
        end

        -- 3. Extract Pet Name and Weight
        local petName, petWeight = nil, nil

        if HatchFunctions and type(HatchFunctions.GetEggInsidePetDetails) == "function" then
            pcall(function()
                if eggObj then
                    local n, w = HatchFunctions.GetEggInsidePetDetails(eggObj)
                    if n then petName = n end
                    if w and tonumber(w) then petWeight = tonumber(w) end
                end
            end)
            if (not petName or not petWeight) and childModel then
                pcall(function()
                    local n, w = HatchFunctions.GetEggInsidePetDetails(childModel)
                    if n and not petName then petName = n end
                    if w and not petWeight and tonumber(w) then petWeight = tonumber(w) end
                end)
            end
        end

        local function extractDetails(e)
            if not e then return nil, nil end
            local rawPName, wVal = nil, nil
            if type(e) == "string" then
                rawPName = e
            elseif type(e) == "table" then
                local targetTbl = e
                if type(e.GeneratedPetData) == "table" then targetTbl = e.GeneratedPetData
                elseif type(e.PetData) == "table" then targetTbl = e.PetData
                elseif type(e.Data) == "table" then targetTbl = e.Data end

                rawPName = targetTbl.PetType or targetTbl.Species or targetTbl.PetName or targetTbl.Name or targetTbl.Type or targetTbl.Pet or e.PetType or e.Species or e.PetName or e.Name or e.Type or e.Pet or e.IncubatedEgg

                if petUtils and type(targetTbl) == "table" then
                    pcall(function()
                        local res = (type(petUtils.GetPetWeight) == "function" and (petUtils.GetPetWeight(targetTbl) or petUtils.GetPetWeight(e)))
                                 or (type(petUtils.CalculatePetWeight) == "function" and (petUtils.CalculatePetWeight(targetTbl) or petUtils.CalculatePetWeight(e)))
                                 or (type(petUtils.CalculateWeight) == "function" and (petUtils.CalculateWeight(targetTbl) or petUtils.CalculateWeight(e)))
                                 or (type(petUtils.GetWeight) == "function" and (petUtils.GetWeight(targetTbl) or petUtils.GetWeight(e)))
                        if res and tonumber(res) then wVal = tonumber(res) end
                    end)
                end

                local function scanForWeight(tbl)
                    if type(tbl) ~= "table" then return nil end
                    local explicitW = tbl.PetWeight or tbl.petWeight or tbl.WeightKG or tbl.weightKG or tbl.weight_kg or tbl.RealWeight or tbl.realWeight or tbl.CalculatedWeight or tbl.calculatedWeight or tbl.FinalWeight or tbl.finalWeight or tbl.DisplayWeight or tbl.displayWeight
                    if explicitW and tonumber(explicitW) then return tonumber(explicitW) end

                    local bw = tbl.BaseWeight or tbl.baseWeight or tbl.base_weight
                    local rawW = tbl.Weight or tbl.weight or tbl.KG or tbl.kg or tbl.Kg
                    local baseVal = tonumber(bw) or tonumber(rawW)
                    local wm = tbl.WeightMultiplier or tbl.weightMultiplier or tbl.WeightMult or tbl.weightMult or tbl.WeightScale or tbl.weightScale or tbl.WeightMod or tbl.weightMod or tbl.Multiplier or tbl.multiplier or tbl.Scale or tbl.scale

                    if baseVal and wm and tonumber(wm) and tonumber(wm) ~= 1 then return baseVal * tonumber(wm) end
                    if baseVal then return baseVal end

                    for k, v in pairs(tbl) do
                        local lk = tostring(k):lower()
                        if (lk:find("petweight") or lk:find("realweight") or lk:find("finalweight") or lk:find("weightkg") or lk == "weight" or lk == "kg" or lk == "w") then
                            if tonumber(v) then return tonumber(v) end
                        end
                    end

                    for k, v in pairs(tbl) do
                        local lk = tostring(k):lower()
                        if type(v) == "number" and v > 0.05 and v < 10000 and lk ~= "hatchtime" and lk ~= "timetohatch" and lk ~= "cost" and lk ~= "price" and lk ~= "multiplier" and lk ~= "chance" then
                            return v
                        end
                    end
                    return nil
                end

                if not wVal then
                    wVal = scanForWeight(targetTbl) or scanForWeight(e)
                end

                if wVal and tonumber(wVal) then
                    local wNum = tonumber(wVal)
                    pcall(function()
                        local applied = false
                        if rawPName and petRegistry then
                            local petDef = (petRegistry.Pets and petRegistry.Pets[tostring(rawPName)])
                                        or (petRegistry.PetData and petRegistry.PetData[tostring(rawPName)])
                                        or (type(petRegistry) == "table" and petRegistry[tostring(rawPName)])
                            if petDef then
                                local speciesBaseW = petDef.BaseWeight or petDef.baseWeight or petDef.Weight or petDef.weight or petDef.BaseKG or petDef.baseKG or petDef.WeightMultiplier or petDef.weightMultiplier
                                if speciesBaseW and tonumber(speciesBaseW) and tonumber(speciesBaseW) > 0 then
                                    wNum = wNum * tonumber(speciesBaseW)
                                    applied = true
                                end
                            end
                        end
                        if not applied and not (type(targetTbl) == "table" and (targetTbl.PetWeight or targetTbl.FinalWeight or targetTbl.CalculatedWeight)) then
                            wNum = wNum * 1.10
                        end
                    end)
                    wVal = wNum
                end
            end

            if not rawPName then return nil, wVal and tonumber(wVal) or nil end
            local sName = tostring(rawPName)
            local parsedWeight = sName:match("%[([%d%.]+)%s*[Kk][Gg]%]") or sName:match("%(([%d%.]+)%s*[Kk][Gg]%)") or sName:match("([%d%.]+)%s*[Kk][Gg]")
            if parsedWeight and tonumber(parsedWeight) then
                wVal = tonumber(parsedWeight)
            end

            local cleanPName = cleanPetName(sName)
            local lowerPName = cleanPName:lower()
            if lowerPName:find("egg") or lowerPName == "egg" or lowerPName == "petegg" or lowerPName == cleanPetName(eggName):lower() then
                return nil, wVal and tonumber(wVal) or nil
            end
            return cleanPName ~= "" and cleanPName or nil, wVal and tonumber(wVal) or nil
        end

        if not petName or not petWeight then
            for _, cand in ipairs(candidates) do
                local cleanC = cleanUUID(cand)
                local readyEntry = (_G.GAG_EggReadyToHatchData and (_G.GAG_EggReadyToHatchData[cand] or _G.GAG_EggReadyToHatchData[cleanC])) or t4Data[cand] or t4Data[cleanC]
                if readyEntry then
                    local n, w = extractDetails(readyEntry)
                    if n and not petName then petName = n end
                    if w and not petWeight then petWeight = w end
                end

                if (not petName or not petWeight) and playerData and playerData.PetsData and playerData.PetsData.PetEggIncubatorData and playerData.PetsData.PetEggIncubatorData.IncubatorData then
                    local incData = playerData.PetsData.PetEggIncubatorData.IncubatorData
                    local entry = incData[cand] or incData[cleanC]
                    if not entry then
                        for k, v in pairs(incData) do
                            if cleanUUID(k) == cleanC or tostring(k) == cand then
                                entry = v
                                break
                            end
                        end
                    end
                    if entry then
                        local n, w = extractDetails(entry)
                        if n and not petName then petName = n end
                        if w and not petWeight then petWeight = w end
                    end
                end

                if (not petName or not petWeight) and replData then
                    local entry = replData[cand] or replData[cleanC]
                    if not entry then
                        for k, v in pairs(replData) do
                            if cleanUUID(k) == cleanC or tostring(k) == cand then
                                entry = v
                                break
                            end
                        end
                    end
                    if entry then
                        local n, w = extractDetails(entry)
                        if n and not petName then petName = n end
                        if w and not petWeight then petWeight = w end
                    end
                end

                if petName and petWeight then break end
            end
        end

        -- Direct attribute checks on physical instance as fallback
        if not petName then
            local attrP = (eggObj and (eggObj:GetAttribute("HatchedPet") or eggObj:GetAttribute("PetName") or eggObj:GetAttribute("Species") or eggObj:GetAttribute("PredictedPet") or eggObj:GetAttribute("PetType") or eggObj:GetAttribute("Pet")))
                       or (childModel and (childModel:GetAttribute("HatchedPet") or childModel:GetAttribute("PetName") or childModel:GetAttribute("Species") or childModel:GetAttribute("PredictedPet") or childModel:GetAttribute("PetType") or childModel:GetAttribute("Pet")))
            if attrP then petName = cleanPetName(tostring(attrP)) end
        end
        if not petWeight then
            local attrW = (eggObj and (eggObj:GetAttribute("Weight") or eggObj:GetAttribute("WeightKG") or eggObj:GetAttribute("KG") or eggObj:GetAttribute("PetWeight")))
                       or (childModel and (childModel:GetAttribute("Weight") or childModel:GetAttribute("WeightKG") or childModel:GetAttribute("KG") or childModel:GetAttribute("PetWeight")))
            if attrW and tonumber(attrW) then petWeight = tonumber(attrW) end
        end

        -- Direct child object checks (StringValue) as fallback
        if not petName and eggObj then
            for _, child in ipairs(eggObj:GetChildren()) do
                if child:IsA("StringValue") then
                    local val = cleanPetName(child.Value)
                    if val ~= "" and val:lower() ~= "egg" and val:lower() ~= "petegg" then
                        petName = val
                        break
                    end
                end
            end
        end
        if not petName and childModel then
            for _, child in ipairs(childModel:GetChildren()) do
                if child:IsA("StringValue") then
                    local val = cleanPetName(child.Value)
                    if val ~= "" and val:lower() ~= "egg" and val:lower() ~= "petegg" then
                        petName = val
                        break
                    end
                end
            end
        end

        -- Fallback: If petName is found but petWeight is still nil, check PetRegistry catalog species base weight
        if petName and not petWeight and petRegistry then
            pcall(function()
                local cleanN = cleanPetName(tostring(petName))
                local petDef = (petRegistry.Pets and petRegistry.Pets[cleanN])
                            or (petRegistry.PetData and petRegistry.PetData[cleanN])
                            or (type(petRegistry) == "table" and petRegistry[cleanN])
                if petDef then
                    local speciesBaseW = petDef.BaseWeight or petDef.baseWeight or petDef.Weight or petDef.weight or petDef.BaseKG or petDef.baseKG or petDef.DefaultWeight or petDef.WeightMultiplier
                    if speciesBaseW and tonumber(speciesBaseW) and tonumber(speciesBaseW) > 0 then
                        petWeight = tonumber(speciesBaseW)
                    end
                end
            end)
        end

        local tth = (eggObj and tonumber(eggObj:GetAttribute("TimeToHatch"))) or (childModel and tonumber(childModel:GetAttribute("TimeToHatch")))
        local isReady = (tth and tth <= 0)
                     or (eggObj and (eggObj:GetAttribute("ReadyToHatch") == true or eggObj:GetAttribute("IsReady") == true))
                     or (childModel and (childModel:GetAttribute("ReadyToHatch") == true or childModel:GetAttribute("IsReady") == true))

        if petName then
            local cleanN = cleanPetName(tostring(petName))
            local lowerN = cleanN:lower()
            if lowerN:find("egg") or lowerN == cleanPetName(eggName):lower() then
                petName = nil
            end
        end

        -- Reject generic template/folder objects (Pet Egg, PetEggServer) that have no inside pet details
        local lowerEgg = eggName:lower()
        if not petName and (lowerEgg == "pet egg" or lowerEgg == "petegg" or lowerEgg == "peteggserver" or lowerEgg == "model" or lowerEgg == "folder") then
            return nil
        end

        if petName then
            local wStr = ""
            if petWeight and tonumber(petWeight) then
                local kg = tonumber(petWeight)
                local classStr = HatchFunctions.GetWeightClassification(kg)
                wStr = string.format(" %.2fKG - %s", kg, classStr)
            end
            return string.format("• %s (%s%s)", eggName, petName, wStr)
        else
            return string.format("• %s", eggName)
        end
    end

    local scannedEggs = {}
    local scannedUUIDs = {}
    local function processEgg(eggObj)
        if not eggObj or scannedEggs[eggObj] or (eggObj.Parent and scannedEggs[eggObj.Parent]) then return end

        local owner = eggObj:GetAttribute("OWNER") or eggObj:GetAttribute("Owner") or eggObj:GetAttribute("OwnerUserId")
        if owner and tostring(owner) ~= localName and tostring(owner) ~= tostring(LocalPlayer.UserId) then return end

        local childModel = eggObj:FindFirstChildOfClass("Model") or eggObj:FindFirstChild("Model") or eggObj:FindFirstChild("PetEgg")
        if childModel and scannedEggs[childModel] then return end

        local isEgg = eggObj:GetAttribute("OBJECT_TYPE") == "PetEgg"
                   or eggObj:GetAttribute("EggName") ~= nil
                   or eggObj:GetAttribute("EggType") ~= nil
                   or eggObj.Name:find("Egg")

        if isEgg then
            local uuid = eggObj:GetAttribute("OBJECT_UUID") or eggObj:GetAttribute("UUID") or eggObj:GetAttribute("CosmeticUUID")
                      or (childModel and (childModel:GetAttribute("OBJECT_UUID") or childModel:GetAttribute("UUID")))
            if uuid and uuid ~= "" then
                local cleanU = cleanUUID(uuid)
                if cleanU ~= "" then
                    if scannedUUIDs[cleanU] then return end
                    scannedUUIDs[cleanU] = true
                end
            end

            scannedEggs[eggObj] = true
            if childModel then scannedEggs[childModel] = true end
            if eggObj.Parent and (eggObj.Parent.Name:find("Egg") or eggObj.Parent:GetAttribute("OBJECT_TYPE") == "PetEgg") then
                scannedEggs[eggObj.Parent] = true
            end

            local formattedLine = resolveEggInfo(eggObj, childModel)
            if formattedLine then
                table.insert(eggsList, formattedLine)
            end
        end
    end

    -- Scan Farm Objects_Physical
    local playerFarm = nil
    pcall(function()
        local getFarm = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("GetFarm"))
        playerFarm = getFarm(LocalPlayer)
    end)
    if not playerFarm then playerFarm = workspace:FindFirstChild("Farm") or workspace end

    local phys = playerFarm and (playerFarm:FindFirstChild("Important", true) and playerFarm:FindFirstChild("Important", true):FindFirstChild("Objects_Physical") or playerFarm:FindFirstChild("Objects_Physical", true))
    if phys then
        for _, child in ipairs(phys:GetChildren()) do
            processEgg(child)
        end
    end

    -- Scan CollectionService PetEggServer
    pcall(function()
        local cs = game:GetService("CollectionService")
        for _, serverEgg in ipairs(cs:GetTagged("PetEggServer")) do
            processEgg(serverEgg)
        end
    end)

    if #eggsList == 0 then
        return "No eggs in garden"
    end

    return table.concat(eggsList, "\n")
end

-- Helper 4: Format configured Pet Teams with quantity grouping
local function getTeamPetsSummary(teams)
    teams = teams or {}
    local lines = {}

    local reduceTeam = teams.Reduce or {}
    local hatchTeam  = teams.Hatch or {}
    local brontoTeam = teams.Bronto or {}
    local sellTeam   = teams.Sell or {}

    local function formatTeamList(list)
        if not list or type(list) ~= "table" or #list == 0 then
            return "(Empty)"
        end
        local counts = {}
        local order = {}
        for _, item in ipairs(list) do
            local name = cleanPetName(tostring(item))
            if name ~= "" then
                if not counts[name] then
                    counts[name] = 0
                    table.insert(order, name)
                end
                counts[name] = counts[name] + 1
            end
        end

        if #order == 0 then return "(Empty)" end

        local formatted = {}
        for _, name in ipairs(order) do
            local qty = counts[name]
            if qty > 1 then
                table.insert(formatted, string.format("%s (%d)", name, qty))
            else
                table.insert(formatted, name)
            end
        end

        return table.concat(formatted, ", ")
    end

    table.insert(lines, "📉 **Reduce Team**: " .. formatTeamList(reduceTeam))
    table.insert(lines, "🐣 **Hatch Team**: " .. formatTeamList(hatchTeam))
    table.insert(lines, "🦕 **Bronto Team**: " .. formatTeamList(brontoTeam))
    table.insert(lines, "💰 **Sell Team**: " .. formatTeamList(sellTeam))

    return table.concat(lines, "\n")
end

-- Helper 6: Retrieve total calculated state percentage for specified pet species (e.g. Koi, Seal, Bronto)
local function getPetSpeciesStatePercentage(keywords, defaultFallback)
    local totalVal = 0
    local found = false

    local petList = nil
    local passReg = nil
    pcall(function()
        if ReplicatedStorage:FindFirstChild("Data") and ReplicatedStorage.Data:FindFirstChild("PetRegistry") then
            local pr = ReplicatedStorage.Data.PetRegistry
            if pr:FindFirstChild("PetList") then petList = require(pr.PetList) end
            if pr:FindFirstChild("PassiveRegistry") then passReg = require(pr.PassiveRegistry) end
        end
    end)

    local function inspectCandidate(petName, petWeight, petMutation, petLevel)
        if not petName or petName == "" then return end
        local pLower = tostring(petName):lower()

        local matched = false
        for _, kw in ipairs(keywords) do
            if pLower:find(kw:lower(), 1, true) then
                matched = true
                break
            end
        end
        if not matched then return end

        local petDef = petList and (petList[tostring(petName)] or petList[cleanPetName(petName)])
        local passives = {}
        if petDef and petDef.Passives then
            for _, p in pairs(petDef.Passives) do
                if type(p) == "string" then table.insert(passives, p) end
            end
        end
        if #passives == 0 and petName then
            table.insert(passives, petName)
        end

        local wVal = tonumber(petWeight) or 1
        local lVal = tonumber(petLevel) or 1
        local pb = 0
        pcall(function()
            if typeof(PetMutationsData) == "table" and typeof(PetMutationsData.GetPassiveBoost) == "function" then
                pb = PetMutationsData.GetPassiveBoost(petMutation)
            end
            if (not pb or pb == 0) and typeof(MiscFunctions) == "table" and typeof(MiscFunctions.GetPassiveBoostForMutation) == "function" then
                pb = MiscFunctions.GetPassiveBoostForMutation(petMutation)
            end
        end)

        if passReg then
            for _, pName in ipairs(passives) do
                local pDef = passReg[tostring(pName)]
                if not pDef then
                    for rK, rV in pairs(passReg) do
                        if tostring(rK):lower() == tostring(pName):lower() then
                            pDef = rV
                            break
                        end
                    end
                end

                if pDef and pDef.States and type(pDef.States) == "table" then
                    for sKey, sDef in pairs(pDef.States) do
                        if type(sDef) == "table" then
                            local base = tonumber(sDef.Base) or 0
                            local scale = tonumber(sDef.Scale) or 0
                            local rawV = (base * (1 + pb)) + (wVal * scale)

                            if sDef.Max ~= nil and tonumber(sDef.Max) then
                                rawV = math.min(rawV, tonumber(sDef.Max))
                            end
                            if sDef.Min ~= nil and tonumber(sDef.Min) then
                                rawV = math.max(rawV, tonumber(sDef.Min))
                            end

                            totalVal = totalVal + rawV
                            found = true
                        elseif type(sDef) == "number" then
                            totalVal = totalVal + sDef
                            found = true
                        end
                    end
                end
            end
        end
    end

    local player = LocalPlayer or Players.LocalPlayer
    if player then
        local char = player.Character
        local bp = player:FindFirstChildOfClass("Backpack") or player:FindFirstChild("Backpack")

        for _, container in ipairs({char, bp}) do
            if container then
                for _, tool in ipairs(container:GetChildren()) do
                    if tool:IsA("Tool") then
                        local pName = tool:GetAttribute("PetType") or tool:GetAttribute("Species") or tool.Name
                        local pWeight = tool:GetAttribute("Weight") or tool:GetAttribute("KG")
                        local pMutation = tool:GetAttribute("Mutation") or tool:GetAttribute("PetMutation")
                        local pLevel = tool:GetAttribute("Age") or tool:GetAttribute("Level")
                        inspectCandidate(pName, pWeight, pMutation, pLevel)
                    end
                end
            end
        end
    end

    pcall(function()
        local ds = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("DataService") and require(ReplicatedStorage.Modules.DataService)
        if ds and typeof(ds.GetData) == "function" then
            local data = ds:GetData()
            if data and data.PetsData and type(data.PetsData.Pets) == "table" then
                for _, petData in ipairs(data.PetsData.Pets) do
                    if petData.Equipped or petData.IsEquipped then
                        inspectCandidate(petData.PetType or petData.Species or petData.Name, petData.Weight or petData.KG, petData.Mutation, petData.Age or petData.Level)
                    end
                end
            end
        end
    end)

    if found and totalVal > 0 then
        -- Apply Bronto Max Cap Rule (Cap at 30% if > 30%, keep actual if < 30%)
        local isBronto = false
        for _, kw in ipairs(keywords) do
            if tostring(kw):lower():find("bronto") then
                isBronto = true
                break
            end
        end

        if isBronto then
            totalVal = math.min(30, totalVal)
        end

        if math.abs(totalVal - math.floor(totalVal)) < 0.001 then
            return string.format("%d%%", math.floor(totalVal))
        else
            return string.format("%.2f%%", totalVal)
        end
    end

    return defaultFallback or ""
end

-- Helper: Format seconds into human readable duration (e.g. 45s, 1m 24s, 1h 05m 12s)
local function formatDuration(seconds)
    seconds = math.floor(tonumber(seconds) or 0)
    if seconds < 60 then
        return string.format("%ds", seconds)
    elseif seconds < 3600 then
        local mins = math.floor(seconds / 60)
        local secs = seconds % 60
        return string.format("%dm %02ds", mins, secs)
    else
        local hours = math.floor(seconds / 3600)
        local mins = math.floor((seconds % 3600) / 60)
        local secs = seconds % 60
        return string.format("%dh %02dm %02ds", hours, mins, secs)
    end
end

-- Helper 5: Send Master Hatch Webhook Embed Report
local function sendCycleWebhookReport(automation, cycleNum, hatchCashback, sellCashback, gardenSummaryOverride, cycleHatchCount, cycleSoldCount, cycleDurationSec, totalElapsedSec, customTitle, customDescription)
    local settings = automation.Settings or {}
    local url = settings.WebhookUrl
    local enabled = settings.WebhookEnabled

    if not enabled or not url or url == "" or not url:find("http") then return end

    local totalPets, maxSlots = getPetInventorySlotInfo()
    local petsInventoryValueStr = string.format("**%d Pets**", totalPets)
    if maxSlots and maxSlots > 0 then
        petsInventoryValueStr = string.format("**%d/%d**", totalPets, maxSlots)
    end
    local totalBackpackEggs, eggCounts = getBackpackEggsSummary()
    local gardenSummary = gardenSummaryOverride or getGardenEggsSummary()
    local teamSummary = getTeamPetsSummary(settings.Teams)

    local selectedEggName = settings.SelectedEgg or settings.PlaceEggName
    local selectedEggCount = 0
    if selectedEggName and eggCounts then
        local sClean = selectedEggName:gsub("%s*%[[^%]]+%]%s*", ""):gsub("%s*%((.-)%)", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
        for name, qty in pairs(eggCounts) do
            local nClean = name:gsub("%s*%[[^%]]+%]%s*", ""):gsub("%s*%((.-)%)", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
            if nClean == sClean or nClean:find(sClean, 1, true) or sClean:find(nClean, 1, true) then
                selectedEggCount = selectedEggCount + qty
            end
        end
    end

    local eggsValueStr = string.format("**%d Eggs**", totalBackpackEggs)
    if selectedEggName and selectedEggName ~= "" then
        eggsValueStr = string.format("**%d %s**", selectedEggCount, selectedEggName)
    end

    local brontoSummary = (HatchFunctions and typeof(HatchFunctions.GetBrontoHatchedSummary) == "function" and HatchFunctions.GetBrontoHatchedSummary()) or "No pets hatched with Bronto Mode yet"
    local totalHatches = (HatchFunctions and HatchFunctions.Stats and HatchFunctions.Stats.TotalHatches) or 0

    local koiStateStr   = getPetSpeciesStatePercentage({"koi", "fish of fortune"}, "50%")
    local sealStateStr  = getPetSpeciesStatePercentage({"seal", "seal the deal"}, "51.09%")
    local brontoStateStr = getPetSpeciesStatePercentage({"bronto", "brontosaurus", "giant incubator"}, "31%")

    local brontoFieldName = string.format("🦕 Bronto Hatched Pets (%s)", brontoStateStr)
    local luckyRewardsValue = string.format(
        "• **Lucky Hatch Recovered**: +%d Eggs (%s)\n  └ 🐣 **Opened this Event**: %d Eggs\n• **Lucky Sell Rewards**: +%d Eggs (%s)\n  └ 💰 **Pets Sold this Event**: %d Pets",
        hatchCashback, koiStateStr, cycleHatchCount or 0,
        sellCashback, sealStateStr, cycleSoldCount or 0
    )

    local cycleDurationStr = formatDuration(cycleDurationSec)
    local totalRuntimeStr  = formatDuration(totalElapsedSec)
    local cycleLabel = type(cycleNum) == "number" and ("Cycle #" .. tostring(cycleNum)) or tostring(cycleNum)

    local fields = {
        { name = "🐾 Total Pets in Inventory", value = petsInventoryValueStr, inline = true },
        { name = "🥚 Total Eggs in Backpack", value = eggsValueStr, inline = true },
        { name = "🐣 Total Eggs Opened", value = string.format("**%d Eggs**", totalHatches), inline = true },
        { name = "⏱️ Duration", value = string.format("**%s**", cycleDurationStr), inline = true },
        { name = "⏳ Total Runtime", value = string.format("**%s**", totalRuntimeStr), inline = true },
        { name = "📋 Configured Pet Teams", value = teamSummary, inline = false },
        { name = "🌱 Garden Placed Eggs", value = gardenSummary, inline = false },
        { name = brontoFieldName, value = brontoSummary, inline = false },
        { name = "🍀 Lucky Rewards (" .. cycleLabel .. ")", value = luckyRewardsValue, inline = false }
    }

    local sendWebhook = (typeof(MiscFunctions) == "table" and typeof(MiscFunctions.SendWebhook) == "function" and MiscFunctions.SendWebhook)
                     or _G.GAG_SendWebhook

    if typeof(sendWebhook) == "function" then
        local embedTitle = customTitle or "✨ **Real-time Automated Garden Cycle Execution Report**"
        local embedDesc  = customDescription or string.format("🔮 **Krexel Hub • Auto Hatch Cycle #%d Finished**", type(cycleNum) == "number" and cycleNum or 1)

        pcall(function()
            sendWebhook(
                url,
                embedTitle,
                embedDesc,
                11032055, -- Krexel Signature Dark Violet (#A855F7)
                fields
            )
        end)
    end
end

--------------------------------------------------------------------------------
-- MASTER AUTO HATCH LOOP WORKFLOW
--------------------------------------------------------------------------------

function HatchFunctions.RunMasterAutoHatchLoop(automation, eggsPetsData)
    local currentCycles = 0
    local currentEquippedTeam = nil
    automation.States.CurrentActionStatus = "Idle"

    -- Helper: update UI status
    local function setStatus(msg)
        automation.States.CurrentActionStatus = msg
        if typeof(HatchFunctions.UIUpdateCallback) == "function" then
            pcall(HatchFunctions.UIUpdateCallback)
        end
    end

    -- Helper: responsive wait that exits immediately if AutoHatch state is turned off
    local function safeWait(sec)
        local start = tick()
        while tick() - start < sec do
            if not automation.States["AutoHatch"] then return false end
            task.wait(0.2)
        end
        return automation.States["AutoHatch"]
    end

    local teamsData = {}

    local function areTeamsEqual(teamA, teamB)
        if teamA == teamB then return true end
        if not teamA or not teamB then return false end
        if type(teamA) ~= "table" or type(teamB) ~= "table" then return false end
        if #teamA ~= #teamB then return false end
        for i = 1, #teamA do
            if teamA[i] ~= teamB[i] then return false end
        end
        return true
    end

    local isHandlingEmergencySell = false

    local function isInventoryFullOrCritical(customEggAmt)
        local settings = automation.Settings or {}
        local placeAmt = tonumber(customEggAmt or settings.PlaceEggAmount or settings.EggPlaceAmount) or 13
        placeAmt = math.max(1, placeAmt)

        local totalPets, maxSlots = getPetInventorySlotInfo()
        maxSlots = maxSlots or 200
        local remaining = maxSlots - totalPets
        local threshold = math.max(0, maxSlots - placeAmt)
        local isCritical = (totalPets >= threshold) or (remaining <= placeAmt)
        return isCritical, totalPets, maxSlots, remaining, threshold, placeAmt
    end

    local function handleEmergencyInventorySell(sellTeamRef, returnTeamRef, soldCounterTable)
        local settings = automation.Settings or {}
        local teams = (settings and settings.Teams) or {}
        local sTeam = sellTeamRef or teams.Sell or {}
        local rTeam = returnTeamRef or teams.Reduce or {}

        local isCritical, totalPets, maxSlots, remaining, threshold, placeAmt = isInventoryFullOrCritical()
        if not isCritical then return false end

        setStatus(string.format("⚠️ Pet Inventory Capacity Critical (%d/%d Pets)! Equip Sell Team...", totalPets, maxSlots))

        -- FORCE EQUIP SELL TEAM
        if type(sTeam) == "table" and #sTeam > 0 then
            setStatus(string.format("Equipping Sell Team (%d Pets)...", #sTeam))
            HatchFunctions.EquipTeam(sTeam)
            currentEquippedTeam = "Sell"
            teamsData["Sell"] = sTeam
            task.wait(0.5)
        else
            warn("[GAG 1 Hub] Sell Team is empty or not configured in settings! Will attempt selling inventory pets directly.")
        end

        local totalSoldInEmergency = 0
        local emergStart = tick()
        setStatus("Sell Team Equipped - Waiting 4s before selling pets...")
        local eggsBeforeSell, _ = getBackpackEggsSummary()
        if safeWait(4) then
            local targets = settings.SellTargetPets
            local wVal   = tonumber(settings.SellWeightValue) or 6.0
            local wCond  = settings.SellWeightCondition or "Below"
            local aVal   = tonumber(settings.SellAgeValue) or 3
            local aCond  = settings.SellAgeCondition or "Below"

            repeat
                if not automation.States["AutoHatch"] then break end
                setStatus(string.format("Selling Pets (Inventory Capacity %d/%d)...", totalPets, maxSlots))

                local sold = HatchFunctions.SellPetByWeight(targets, wVal, wCond, aVal, aCond, "Emergency Full Inventory Sell", 1)
                if not sold or sold == 0 then break end

                local numSold = tonumber(sold) or 0
                totalSoldInEmergency = totalSoldInEmergency + numSold
                if soldCounterTable then
                    soldCounterTable.count = (soldCounterTable.count or 0) + numSold
                end
                task.wait(1)
            until not automation.States["AutoHatch"]

            if automation.States["AutoHatch"] then
                setStatus("Selling Pets Complete - Waiting 1s before switching team...")
                safeWait(1)
            end
        end

        local eggsAfterSell, _ = getBackpackEggsSummary()
        local sellCashback = math.max(0, eggsAfterSell - eggsBeforeSell)
        if soldCounterTable then
            soldCounterTable.sellCashback = (soldCounterTable.sellCashback or 0) + sellCashback
        end

        -- Trigger Webhook notification immediately after Emergency Sell completes
        pcall(function()
            local sCount = totalSoldInEmergency
            local emergDuration = math.max(0, tick() - emergStart)
            local totalElapsed  = math.max(0, tick() - (masterHatchStartTime or tick()))

            sendCycleWebhookReport(
                automation,
                "Emergency Sell",
                0,
                sellCashback,
                nil,
                0,
                sCount,
                emergDuration,
                totalElapsed,
                "🚨 **Emergency Inventory Sell Execution Report**",
                string.format("🔮 **Krexel Hub • Emergency Pet Sell Executed (%d Pets Sold)**", sCount)
            )
        end)

        -- Re-check inventory capacity AFTER Emergency Sell attempts to sell pets:
        local isStillCrit, tStillPets, mStillSlots = isInventoryFullOrCritical()
        if isStillCrit then
            local warnMsg = string.format("⛔ Pet Inventory Full (%d/%d Pets)! All remaining pets are favorited/locked. Cannot sell pets - Auto Hatch Automatically Stopped!", tStillPets, mStillSlots)
            setStatus(warnMsg)
            warn("[GAG 1 Hub] " .. warnMsg)

            -- 1. UI Toast Notification
            pcall(function()
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({
                        Title = "⛔ Auto Hatch Stopped!",
                        Content = string.format("Inventory Full (%d/%d Pets). All remaining pets are favorited/protected!", tStillPets, mStillSlots),
                        Duration = 8
                    })
                end
            end)

            -- 2. Discord Webhook Report
            pcall(function()
                sendCycleWebhookReport(
                    automation,
                    "Inventory Full - Auto Hatch Stopped",
                    0, 0, nil, 0, 0,
                    math.max(0, tick() - emergStart),
                    math.max(0, tick() - (masterHatchStartTime or tick())),
                    "⛔ **Auto Hatch Stopped - Inventory Full Warning**",
                    string.format("⚠️ **Krexel Hub • Auto Hatch Stopped!** Inventory Full (%d/%d Pets). All pets in inventory are favorited/protected.", tStillPets, mStillSlots)
                )
            end)

            -- 3. Automatically turn OFF Master Auto Hatch Loop
            automation.States["AutoHatch"] = false
            if typeof(automation.StopTask) == "function" then
                automation.StopTask("AutoHatch")
            end
            return false
        end

        -- Re-equip target return team after Emergency Sell completes
        if automation.States["AutoHatch"] and type(rTeam) == "table" and #rTeam > 0 then
            HatchFunctions.EquipTeam(rTeam)
            currentEquippedTeam = nil
            task.wait(0.3)
        end

        return true
    end

    -- Helper: switch to a team with live pet inventory re-count and safety interception on EVERY switch
    local function switchToTeam(teamType, teamList, label)
        if not teamList or type(teamList) ~= "table" or #teamList == 0 then return end

        -- Live re-count pets in inventory on every single team switch
        local curPets, curMax = getPetInventorySlotInfo()

        -- Safety Interception: If team is NOT Sell and inventory capacity is critical (sisa <= 8 slots), perform emergency sell FIRST
        if teamType ~= "Sell" and not isHandlingEmergencySell then
            local isCrit, tPets, mSlots, rem = isInventoryFullOrCritical()
            if isCrit then
                isHandlingEmergencySell = true
                setStatus(string.format("⚠️ Inventory Critical before equipping %s (%d/%d Pets)! Performing Sell first...", teamType, tPets, mSlots))
                local settings = automation.Settings or {}
                local teams = settings.Teams or {}
                handleEmergencyInventorySell(teams.Sell, teamList, nil)
                isHandlingEmergencySell = false

                -- Re-check capacity after sell: BLOCK equipping non-Sell teams if inventory remains critical!
                local isStillCrit, tStillPets, mStillSlots = isInventoryFullOrCritical()
                if isStillCrit then
                    setStatus(string.format("⚠️ Inventory Capacity Critical (%d/%d Pets)! Blocked equipping %s team...", tStillPets, mStillSlots, teamType))
                    warn(string.format("[GAG 1 Hub] Inventory still critical (%d/%d Pets) after sell attempt! Blocked equipping %s team.", tStillPets, mStillSlots, teamType))
                    return -- BLOCK SWITCHING TO NON-SELL TEAM!
                end
            end
        end

        if currentEquippedTeam == teamType then
            if label then setStatus(label) end
            return
        end

        local currentList = teamsData[currentEquippedTeam]
        if currentList and areTeamsEqual(currentList, teamList) then
            currentEquippedTeam = teamType
            teamsData[teamType] = teamList
            if label then setStatus(label) end
            return
        end

        if label then setStatus(label) end
        HatchFunctions.EquipTeam(teamList)
        currentEquippedTeam = teamType
        teamsData[teamType] = teamList
        task.wait(0.3)
    end

    ------------------------------------------------------------------------
    -- INITIAL CHECK (Runs ONCE when Auto Hatch is first enabled)
    ------------------------------------------------------------------------
    if automation.States["AutoHatch"] then
        local settings = automation.Settings or {}
        local teams = settings.Teams or {}
        local isBrontoOn = settings.BrontoModeEnabled ~= false or automation.States.BrontoMode
        local brontoTeam = teams.Bronto or {}
        local hatchTeam = teams.Hatch or {}
        local sellTeam = teams.Sell or {}
        local reduceTeam = teams.Reduce or {}

        -- 0. Wait 1.5s on initial startup to allow Backpack tools to finish replicating into LocalPlayer
        task.wait(1.5)

        -- Check inventory safety immediately upon startup (Force Emergency Sell if full)
        handleEmergencyInventorySell(sellTeam, reduceTeam, nil)

        -- 1. Check if Bronto eggs are already ready in garden
        if isBrontoOn and typeof(HatchFunctions.GetReadyBrontoEggs) == "function" then
            local readyBronto = HatchFunctions.GetReadyBrontoEggs(automation)
            if readyBronto and #readyBronto > 0 then
                local initialStart = tick()
                local initialHatchesBefore = (HatchFunctions and HatchFunctions.Stats and HatchFunctions.Stats.TotalHatches) or 0

                handleEmergencyInventorySell(sellTeam, brontoTeam, nil)

                local isCritBronto, tBronto, mBronto = isInventoryFullOrCritical()
                if isCritBronto then
                    setStatus(string.format("⚠️ Inventory Critical on Startup (%d/%d Pets)! Initial Bronto Hatch Blocked...", tBronto, mBronto))
                    safeWait(4)
                else
                    switchToTeam("Bronto", brontoTeam, string.format("Equip Bronto Team (Initial - %d Bronto Eggs)", #readyBronto))

                    -- 4s delay after equipping Bronto team before sending remote
                    setStatus(string.format("Bronto Team Equipped - Waiting 4s before remote hatch...", #readyBronto))
                    if safeWait(4) then
                        repeat
                            if not automation.States["AutoHatch"] then break end
                            local curBronto = HatchFunctions.GetReadyBrontoEggs(automation)
                            if not curBronto or #curBronto == 0 then break end

                            setStatus(string.format("Bronto Hatching (Initial) - %d eggs", #curBronto))
                            HatchFunctions.HatchBrontoEggStep(nil, 99, eggsPetsData, automation)
                            task.wait(1)
                        until not automation.States["AutoHatch"]

                        -- 1s delay after remote Bronto completed
                        if automation.States["AutoHatch"] then
                            setStatus("Initial Bronto Hatching Complete - Waiting 1s...")
                            safeWait(1)
                        end
                    end
                end
            end
        end

        -- 2. Check if normal eggs are already ready in garden
        local hatchFilter = settings.HatchTargetPets
        local useFilter = hatchFilter and type(hatchFilter) == "table" and #hatchFilter > 0
        local readyList = HatchFunctions.GetReadyPlacedEggs(automation, useFilter)

        if #readyList > 0 then

            handleEmergencyInventorySell(sellTeam, hatchTeam, nil)

            local isCritHatch, tHatch, mHatch = isInventoryFullOrCritical()
            if isCritHatch then
                setStatus(string.format("⚠️ Inventory Critical on Startup (%d/%d Pets)! Initial Garden Hatch Blocked...", tHatch, mHatch))
                safeWait(4)
            else
                switchToTeam("Hatch", hatchTeam, string.format("Garden: %d Eggs Ready to Hatch! Hatching first...", #readyList))

                -- 4s delay after equipping Hatch team before sending remote
                setStatus(string.format("Hatch Team Equipped - Waiting 4s before remote hatch...", #readyList))
                if safeWait(4) then
                    repeat
                        if not automation.States["AutoHatch"] then break end
                        local currentReady = HatchFunctions.GetReadyPlacedEggs(automation, useFilter)
                        if #currentReady == 0 then break end

                        setStatus(string.format("Initial Hatching - %d eggs", #currentReady))
                        HatchFunctions.HatchEggStep(nil, 99, eggsPetsData, automation, useFilter)
                        task.wait(1)
                    until not automation.States["AutoHatch"]

                    -- 1s delay after remote Hatch completed
                    if automation.States["AutoHatch"] then
                        setStatus("Initial Hatching Complete - Waiting 1s...")
                        safeWait(1)
                    end
                end
            end
        end
    end

    ------------------------------------------------------------------------
    -- MAIN LOOP
    ------------------------------------------------------------------------
    local masterHatchStartTime = tick()

    while automation.States["AutoHatch"] do
        local cycleStartTime = tick()
        local settings = automation.Settings or {}
        local teams = settings.Teams or {}

        local reduceTeam = teams.Reduce or {}
        local hatchTeam  = teams.Hatch or {}
        local brontoTeam = teams.Bronto or {}
        local sellTeam   = teams.Sell or {}

        local eggName = settings.PlaceEggName or settings.SelectedEgg
        local placeAmt = tonumber(settings.PlaceEggAmount or settings.EggPlaceAmount) or 13

        -- Track Lucky Cashback & Action Counts per Cycle (Resets every cycle)
        local cycleHatchCashback = 0
        local cycleSellCashback = 0
        local cycleHatchCount = 0
        local cycleSoldCount = 0

        ------------------------------------------------------------------------
        -- STEP 1: INVENTORY CHECK & REDUCE PHASE
        ------------------------------------------------------------------------
        -- Check if pet inventory is full or capacity remaining <= 8 -> Equip Sell Team -> Then switch to Reduce Team
        -- Note: Emergency Sell dispatches its own independent Webhook report when executed
        handleEmergencyInventorySell(sellTeam, reduceTeam, nil)

        switchToTeam("Reduce", reduceTeam, "Equip Reduce Team")

        -- Auto-detect egg name from backpack if not selected
        if not eggName or eggName == "" or eggName == "No Eggs in Backpack" then
            local player = LocalPlayer or Players.LocalPlayer
            local backpack = player and (player:FindFirstChildOfClass("Backpack") or player:FindFirstChild("Backpack"))
            if backpack then
                for _, tool in ipairs(backpack:GetChildren()) do
                    if tool:IsA("Tool") then
                        local attrH = tool:GetAttribute("h")
                        if attrH and type(attrH) == "string" and attrH:find("Egg") then
                            eggName = attrH
                            break
                        elseif tool.Name:find("Egg") then
                            eggName = tool.Name:match("^(.-)%s*x%d+") or tool.Name:match("^(.-)%s*%(") or tool.Name
                            break
                        end
                    end
                end
            end
        end

        -- Place egg into garden up to target amount
        local currentInGarden = HatchFunctions.GetCurrentPlacedEggCount()
        local targetPlace = placeAmt

        if currentInGarden < targetPlace then
            local needed = targetPlace - currentInGarden
            if eggName and eggName ~= "" and eggName ~= "No Eggs in Backpack" then
                setStatus(string.format("Placing Eggs (%d/%d in Garden, Need %d)...", currentInGarden, targetPlace, needed))
                local success, stopReason = HatchFunctions.PlaceEgg(eggName, targetPlace, automation)
                if stopReason == "NoEggTool" then
                    setStatus(string.format("Backpack eggs out! Garden has %d/%d. Proceeding to reduce/hatch phase...", HatchFunctions.GetCurrentPlacedEggCount(), targetPlace))
                end
                task.wait(1.5) -- Give time for egg instance to replicate in garden
            end
        else
            setStatus(string.format("Garden has %d/%d Eggs. Proceeding to reduce phase...", currentInGarden, targetPlace))
            task.wait(0.5)
        end

        -- Check total egg exhaustion: If 0 eggs in Garden AND 0 eggs in Backpack -> Complete & Stop!
        local totalInGardenNow = HatchFunctions.GetCurrentPlacedEggCount()
        local totalInBackpackNow, _ = getBackpackEggsSummary()

        if totalInGardenNow == 0 and totalInBackpackNow == 0 then
            local stopMsg = "⛔ All Eggs Hatched (0 in Backpack & 0 in Garden)! Auto Hatch Stopped."
            setStatus(stopMsg)
            warn("[GAG 1 Hub] " .. stopMsg)

            pcall(function()
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({
                        Title = "🏁 Auto Hatch Completed!",
                        Content = "All eggs in Backpack & Garden have been successfully hatched!",
                        Duration = 8
                    })
                end
            end)

            pcall(function()
                local totalElapsed = math.max(0, tick() - (masterHatchStartTime or tick()))
                sendCycleWebhookReport(
                    automation,
                    "Out of Eggs - Completed",
                    0, 0, nil, 0, 0,
                    0,
                    totalElapsed,
                    "🏁 **Auto Hatch Completed - All Eggs Hatched**",
                    "🔮 **Krexel Hub • Auto Hatch Finished!** All eggs in Backpack and Garden have been successfully hatched."
                )
            end)

            automation.States["AutoHatch"] = false
            if typeof(automation.StopTask) == "function" then
                automation.StopTask("AutoHatch")
            end
            if HatchFunctions.AutoHatchToggle and typeof(HatchFunctions.AutoHatchToggle.SetValue) == "function" then
                pcall(function() HatchFunctions.AutoHatchToggle:SetValue(false, false) end)
            end
            break
        end

        -- Record exact backpack egg baseline immediately after place egg phase for Lucky Sell calculation
        local cycleEggBaselineAfterPlace, _ = getBackpackEggsSummary()

        -- Poll: Wait for ALL eggs in garden to finish growth cooldown (Reduce Team STAYS EQUIPPED)
        local emptyWaitTimer = 0
        local readyGardenSummary = nil
        repeat
            if not automation.States["AutoHatch"] then break end

            local totalPlaced = HatchFunctions.GetTotalPlacedEggsCount()
            local readyList = HatchFunctions.GetReadyPlacedEggs(automation, false)
            local readyCount = #readyList

            if totalPlaced > 0 then
                setStatus(string.format("Reduce Team Working... (%d/%d Eggs Ready)", readyCount, totalPlaced))
            else
                setStatus("Waiting for Eggs in Garden...")
            end

            -- If no eggs in garden and no ready eggs after 4 seconds, check if eggs are completely empty
            if totalPlaced == 0 and readyCount == 0 then
                emptyWaitTimer = emptyWaitTimer + 1
                if emptyWaitTimer >= 4 then
                    local curBackpack, _ = getBackpackEggsSummary()
                    if curBackpack == 0 then
                        local stopMsg = "⛔ All Eggs Hatched (0 in Backpack & 0 in Garden)! Auto Hatch Stopped."
                        setStatus(stopMsg)
                        warn("[GAG 1 Hub] " .. stopMsg)

                        pcall(function()
                            if UILibrary and typeof(UILibrary.Notify) == "function" then
                                UILibrary:Notify({
                                    Title = "🏁 Auto Hatch Completed!",
                                    Content = "All eggs in Backpack & Garden have been successfully hatched!",
                                    Duration = 8
                                })
                            end
                        end)

                        pcall(function()
                            local totalElapsed = math.max(0, tick() - (masterHatchStartTime or tick()))
                            sendCycleWebhookReport(
                                automation,
                                "Out of Eggs - Completed",
                                0, 0, nil, 0, 0,
                                0,
                                totalElapsed,
                                "🏁 **Auto Hatch Completed - All Eggs Hatched**",
                                "🔮 **Krexel Hub • Auto Hatch Finished!** All eggs in Backpack and Garden have been successfully hatched."
                            )
                        end)

                        automation.States["AutoHatch"] = false
                        if typeof(automation.StopTask) == "function" then
                            automation.StopTask("AutoHatch")
                        end
                        if HatchFunctions.AutoHatchToggle and typeof(HatchFunctions.AutoHatchToggle.SetValue) == "function" then
                            pcall(function() HatchFunctions.AutoHatchToggle:SetValue(false, false) end)
                        end
                        break
                    else
                        task.wait(3)
                        emptyWaitTimer = 0
                        break
                    end
                end
            else
                emptyWaitTimer = 0
            end

            -- ALL eggs placed in garden are now READY TO HATCH!
            if (totalPlaced > 0 and readyCount >= totalPlaced) or (totalPlaced == 0 and readyCount > 0) then
                setStatus(string.format("All Eggs Ready! (%d/%d) - Waiting 4s before team switch...", readyCount, math.max(totalPlaced, readyCount)))
                if not safeWait(4) then break end
                readyGardenSummary = getGardenEggsSummary()
                break
            end

            task.wait(1)
        until not automation.States["AutoHatch"]

        if not automation.States["AutoHatch"] then break end

        ------------------------------------------------------------------------
        -- STEP 2: HATCH PHASE (Equip Hatch Team -> Remote Hatch All Ready Eggs)
        ------------------------------------------------------------------------
        local isBrontoOn = settings.BrontoModeEnabled ~= false or automation.States.BrontoMode
        local eggsBeforeHatchPhase, _ = getBackpackEggsSummary()
        local hatchesBeforeHatchPhase = (HatchFunctions and HatchFunctions.Stats and HatchFunctions.Stats.TotalHatches) or 0

        -- 1) Bronto Hatching Phase (if active & Bronto matching eggs exist)
        if isBrontoOn and typeof(HatchFunctions.GetReadyBrontoEggs) == "function" then
            local readyBronto = HatchFunctions.GetReadyBrontoEggs(automation)
            if readyBronto and #readyBronto > 0 then
                local bSoldTracker = { count = 0 }
                handleEmergencyInventorySell(sellTeam, brontoTeam, bSoldTracker)
                if bSoldTracker.count > 0 then
                    cycleSoldCount = cycleSoldCount + bSoldTracker.count
                end

                switchToTeam("Bronto", brontoTeam, string.format("Equip Bronto Team (%d Bronto Eggs Matching)", #readyBronto))

                -- 4s delay after equipping Bronto team before sending remote
                setStatus(string.format("Bronto Team Equipped - Waiting 4s before remote hatch...", #readyBronto))
                if safeWait(4) then
                    repeat
                        if not automation.States["AutoHatch"] then break end
                        local curBronto = HatchFunctions.GetReadyBrontoEggs(automation)
                        if not curBronto or #curBronto == 0 then break end

                        setStatus(string.format("Bronto Hatching - %d eggs remaining", #curBronto))
                        HatchFunctions.HatchBrontoEggStep(eggName, placeAmt, eggsPetsData, automation)
                        task.wait(1)
                    until not automation.States["AutoHatch"]

                    -- 1s delay after remote Bronto completed
                    if automation.States["AutoHatch"] then
                        setStatus("Bronto Hatching Complete - Waiting 1s before team switch...")
                        safeWait(1)
                    end
                end
            end
        end

        if not automation.States["AutoHatch"] then break end

        -- 2) Normal Hatch Phase (Switch to Hatch Team and hatch remaining eggs)
        local hatchFilter = settings.HatchTargetPets
        local useFilter = hatchFilter and type(hatchFilter) == "table" and #hatchFilter > 0

        local readyList = HatchFunctions.GetReadyPlacedEggs(automation, useFilter)
        if #readyList > 0 then
            -- Force Emergency Inventory Sell check before equipping Hatch Team
            handleEmergencyInventorySell(sellTeam, hatchTeam, nil)

            -- Re-check inventory capacity: If STILL critical after Emergency Sell attempt, block Hatch Team equipping to prevent overflow!
            local isCritNow, tPetsNow, mSlotsNow = isInventoryFullOrCritical()
            if isCritNow then
                setStatus(string.format("⚠️ Inventory Capacity Critical (%d/%d Pets)! Hatching Blocked - Please free up pet inventory space...", tPetsNow, mSlotsNow))
                safeWait(1)
            else
                switchToTeam("Hatch", hatchTeam, string.format("Equip Hatch Team (%d Eggs Ready)", #readyList))

                -- 4s delay after equipping Hatch team before sending remote
                setStatus(string.format("Hatch Team Equipped - Waiting 4s before remote hatch (%d Eggs)...", #readyList))
                if safeWait(4) then
                    repeat
                        if not automation.States["AutoHatch"] then break end

                        local readyNow = HatchFunctions.GetReadyPlacedEggs(automation, useFilter)
                        local countNow = #readyNow
                        if countNow == 0 then break end

                        -- Safety check inside hatch loop: If capacity becomes critical mid-hatching, pause hatching & trigger Emergency Sell!
                        local isMidCrit, tMid, mMid = isInventoryFullOrCritical()
                        if isMidCrit then
                            setStatus(string.format("⚠️ Inventory Capacity Critical mid-hatch (%d/%d Pets)! Triggering Emergency Sell...", tMid, mMid))
                            handleEmergencyInventorySell(sellTeam, hatchTeam, nil)
                            local isMidStillCrit = isInventoryFullOrCritical()
                            if isMidStillCrit then
                                setStatus(string.format("⚠️ Inventory still full (%d/%d Pets)! Pausing hatch loop...", tMid, mMid))
                                break
                            end
                        end

                        setStatus(string.format("Hatching - %d eggs remaining", countNow))
                        HatchFunctions.HatchEggStep(eggName, placeAmt, eggsPetsData, automation, useFilter)
                        task.wait(1)
                    until not automation.States["AutoHatch"]

                    -- 1s delay after remote Hatch completed
                    if automation.States["AutoHatch"] then
                        setStatus("Hatching Complete - Waiting 1s before team switch...")
                        safeWait(1)
                    end
                end
            end
        end

        local hatchesAfterHatchPhase = (HatchFunctions and HatchFunctions.Stats and HatchFunctions.Stats.TotalHatches) or 0
        cycleHatchCount = math.max(0, hatchesAfterHatchPhase - hatchesBeforeHatchPhase)

        local eggsAfterHatchPhase, _ = getBackpackEggsSummary()
        local gardenRecoveredCount = 0
        pcall(function()
            local readyListNow = HatchFunctions.GetReadyPlacedEggs(automation, false)
            local totalPlacedNow = HatchFunctions.GetTotalPlacedEggsCount()
            local readyCountNow = #readyListNow
            gardenRecoveredCount = math.max(0, totalPlacedNow - readyCountNow)
        end)

        local backpackRecoveredCount = math.max(0, eggsAfterHatchPhase - eggsBeforeHatchPhase)
        cycleHatchCashback = gardenRecoveredCount + backpackRecoveredCount

        if not automation.States["AutoHatch"] then break end

        currentCycles = currentCycles + 1
        HatchFunctions.Stats.CurrentCycles = currentCycles
        HatchFunctions.Stats.TotalCycles = (HatchFunctions.Stats.TotalCycles or 0) + 1
        local thisCycleNum = HatchFunctions.Stats.TotalCycles

        ------------------------------------------------------------------------
        -- STEP 3: SELL PHASE (Equip Sell Team -> Sell Pets if Cycle Threshold Reached)
        ------------------------------------------------------------------------
        local cycleThreshold = tonumber(settings.SellModeThreshold) or 5
        if currentCycles >= cycleThreshold then
            local targets = settings.SellTargetPets
            local wVal   = tonumber(settings.SellWeightValue) or 6.0
            local wCond  = settings.SellWeightCondition or "Below"
            local aVal   = tonumber(settings.SellAgeValue) or 3
            local aCond  = settings.SellAgeCondition or "Below"

            local eggsBeforeSellPhase, _ = getBackpackEggsSummary()

            switchToTeam(
                "Sell",
                sellTeam,
                string.format("Equip Sell Team (Cycle %d/%d)", currentCycles, cycleThreshold)
            )

            -- 4s delay after equipping Sell team before sending remote
            setStatus(string.format("Sell Team Equipped - Waiting 4s before selling pets...", currentCycles, cycleThreshold))
            if safeWait(4) then
                repeat
                    if not automation.States["AutoHatch"] then break end

                    setStatus(string.format("Selling Pets... (Cycle %d/%d)", currentCycles, cycleThreshold))

                    local sold = HatchFunctions.SellPetByWeight(targets, wVal, wCond, aVal, aCond, "Based on Cycle", cycleThreshold)
                    if not sold or sold == 0 then break end
                    cycleSoldCount = cycleSoldCount + (tonumber(sold) or 0)
                    task.wait(1)
                until not automation.States["AutoHatch"]

                -- 1s delay after remote completed
                if automation.States["AutoHatch"] then
                    setStatus("Selling Pets Complete - Waiting 1s before team switch...")
                    safeWait(1)
                end
            end

            local eggsAfterSellPhase, _ = getBackpackEggsSummary()
            cycleSellCashback = cycleSellCashback + math.max(0, eggsAfterSellPhase - eggsBeforeSellPhase)

            if not automation.States["AutoHatch"] then break end

            currentCycles = 0
            HatchFunctions.Stats.CurrentCycles = 0
        end

        ------------------------------------------------------------------------
        -- STEP 4: SEND DISCORD WEBHOOK REPORT PER CYCLE
        ------------------------------------------------------------------------
        local cycleDurationSec = math.max(0, tick() - cycleStartTime)
        local totalElapsedSec  = math.max(0, tick() - masterHatchStartTime)

        sendCycleWebhookReport(
            automation,
            thisCycleNum,
            cycleHatchCashback,
            cycleSellCashback,
            readyGardenSummary,
            cycleHatchCount,
            cycleSoldCount,
            cycleDurationSec,
            totalElapsedSec
        )

        task.wait(1)
    end

    HatchFunctions.UnequipAllPets()
    currentEquippedTeam = nil
    setStatus("Idle")
end

--[[
    GAG 1 Hub - Hatch Functions: Egg Placement & Slot Limits
--]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- Resolve PetEggService Remote Event
local function getPetEggService()
    local gameEvents = ReplicatedStorage:FindFirstChild("GameEvents")
    if gameEvents and gameEvents:FindFirstChild("PetEggService") then
        return gameEvents.PetEggService
    end
    return ReplicatedStorage:FindFirstChild("PetEggService", true)
end

-- Helper function to calculate random Vector3 position on player's farm (Plant_Locations)
local function getEggPlacementPosition()
    local playerFarm = getPlayerFarm()
    local plantLocations = playerFarm and playerFarm:FindFirstChild("Plant_Locations", true)

    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    
    if plantLocations then
        local parts = {}
        for _, child in ipairs(plantLocations:GetDescendants()) do
            if child:IsA("BasePart") then
                table.insert(parts, child)
            end
        end
        if #parts > 0 then
            local chosenBox = parts[math.random(1, #parts)]
            local sz = chosenBox.Size
            local rx = (math.random() - 0.5) * math.max(1, sz.X - 2)
            local rz = (math.random() - 0.5) * math.max(1, sz.Z - 2)
            return chosenBox.Position + Vector3.new(rx, sz.Y / 2 + 0.15, rz)
        end
    end

    local origin = root and root.Position or Vector3.new(-38.89, 0.136, -133.66)
    return origin + Vector3.new(math.random(-10, 10), 0, math.random(-10, 10))
end

-- Helper function to find and equip an egg tool from Backpack
local function equipEggTool(eggName)
    local char = LocalPlayer.Character
    if not char then return nil end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    
    local cleanName = tostring(eggName or ""):match("^(.-)%s*%(") or tostring(eggName or "")
    cleanName = cleanName:match("^(.-)%s*x%d+") or cleanName
    cleanName = cleanName:gsub("^%s*(.-)%s*$", "%1"):lower()

    local function isMatchingEggTool(tool)
        if not tool or not tool:IsA("Tool") or not tool.Parent then return false end
        local tName = tool.Name:lower()
        local attrH = tool:GetAttribute("h") and tostring(tool:GetAttribute("h")):lower()
        local attrName = tool:GetAttribute("EggName") and tostring(tool:GetAttribute("EggName")):lower()
        local uses = tool:GetAttribute("LocalUses") or tool:GetAttribute("e") or tool:GetAttribute("Uses")
        if uses ~= nil and tonumber(uses) and tonumber(uses) <= 0 then
            return false
        end

        if cleanName ~= "" and cleanName ~= "no eggs in backpack" then
            if tName:find(cleanName, 1, true) or (attrH and attrH:find(cleanName, 1, true)) or (attrName and attrName:find(cleanName, 1, true)) then
                return true
            end
        elseif tName:find("egg") or (attrH and attrH:find("egg")) or (attrName and attrName:find("egg")) then
            return true
        end
        return false
    end

    -- 1. Check if tool is already equipped in Character
    for _, child in ipairs(char:GetChildren()) do
        if isMatchingEggTool(child) then
            return child
        end
    end

    -- 2. Search in Backpack
    local backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if isMatchingEggTool(tool) then
                if humanoid then
                    pcall(function() humanoid:EquipTool(tool) end)
                    task.wait(0.2)
                end
                return tool
            end
        end
    end

    -- 3. Short retry in case inventory replication is in progress
    task.wait(0.25)
    backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if isMatchingEggTool(tool) then
                if humanoid then
                    pcall(function() humanoid:EquipTool(tool) end)
                    task.wait(0.2)
                end
                return tool
            end
        end
    end

    return nil
end

-- Helper function to count currently placed eggs on player's farm (Unified with GetTotalPlacedEggsCount)
function HatchFunctions.GetCurrentPlacedEggCount()
    if typeof(HatchFunctions.GetTotalPlacedEggsCount) == "function" then
        return HatchFunctions.GetTotalPlacedEggsCount()
    end
    return 0
end

-- State listener cache for real-time slot signal connections
HatchFunctions._SlotSignalsConnected = false

local function setupDataServiceSlotListeners()
    if HatchFunctions._SlotSignalsConnected then return end
    pcall(function()
        local ds = require(ReplicatedStorage.Modules.DataService)
        if ds and type(ds.GetPathSignal) == "function" then
            HatchFunctions._SlotSignalsConnected = true
            
            local triggerUpdate = function()
                if typeof(HatchFunctions.UIUpdateCallback) == "function" then
                    pcall(HatchFunctions.UIUpdateCallback)
                end
            end

            -- Listen to PetsData path changes in real-time
            local pDataSignal = ds:GetPathSignal("PetsData/@") or ds:GetPathSignal("PetsData")
            if pDataSignal and type(pDataSignal.Connect) == "function" then pDataSignal:Connect(triggerUpdate) end

            local eggSignal = ds:GetPathSignal("PetsData/PurchasedEggSlots")
            if eggSignal and type(eggSignal.Connect) == "function" then eggSignal:Connect(triggerUpdate) end

            local equipSignal = ds:GetPathSignal("PetsData/PurchasedEquipSlots")
            if equipSignal and type(equipSignal.Connect) == "function" then equipSignal:Connect(triggerUpdate) end

            -- Listen to GardenCoinShopStats for Garden Coin upgrades
            local gcSignal = ds:GetPathSignal("GardenCoinShopStats/@") or ds:GetPathSignal("GardenCoinShopStats/LifetimePurchases/@")
            if gcSignal and type(gcSignal.Connect) == "function" then gcSignal:Connect(triggerUpdate) end
        end
    end)
end

-- Helper function to resolve max egg slot limit for the player
function HatchFunctions.GetMaxEggSlots(automation)
    return 13
end

-- Helper function to resolve max equipped pet slot limit
function HatchFunctions.GetMaxPetEquipSlots()
    return 8
end

-- Place Egg Function (Verifies garden egg count continuously until target amount is reached)
function HatchFunctions.PlaceEgg(eggName, targetAmount, automation)
    targetAmount = tonumber(targetAmount) or 13
    local petEggService = getPetEggService()

    local initialPlaced = HatchFunctions.GetCurrentPlacedEggCount()
    if initialPlaced >= targetAmount then
        return true, "TargetAlreadyReached"
    end

    local maxAttempts = math.max(25, targetAmount * 2)
    local attempts = 0
    local placedCount = 0
    local stopReason = nil
    local consecutiveFailures = 0

    while attempts < maxAttempts do
        local currentPlaced = HatchFunctions.GetCurrentPlacedEggCount()
        if currentPlaced >= targetAmount then
            stopReason = "TargetReached"
            break
        end

        attempts = attempts + 1

        local eggTool = equipEggTool(eggName)
        if not eggTool then
            eggTool = equipEggTool(nil)
        end

        if not eggTool then
            consecutiveFailures = consecutiveFailures + 1
            if consecutiveFailures >= 3 then
                stopReason = "NoEggTool"
                break
            else
                task.wait(0.35)
            end
        else
            consecutiveFailures = 0
            local placePos = getEggPlacementPosition()
            local placeCF = CFrame.new(placePos)

            if petEggService then
                pcall(function()
                    if petEggService:IsA("RemoteFunction") then
                        petEggService:InvokeServer("CreateEgg", placePos)
                    else
                        petEggService:FireServer("CreateEgg", placePos)
                        petEggService:FireServer("CreateEgg", placePos, placeCF)
                        petEggService:FireServer("PlaceEgg", placePos)
                        petEggService:FireServer("PlaceEgg", placePos, placeCF)
                    end
                end)
            end

            -- Fallback Tool Activation & Sub-remote Call
            pcall(function()
                if eggTool and eggTool.Parent then
                    if typeof(eggTool.Activate) == "function" then
                        eggTool:Activate()
                    end
                    for _, child in ipairs(eggTool:GetChildren()) do
                        if child:IsA("RemoteEvent") then
                            pcall(function() child:FireServer("CreateEgg", placePos) end)
                            pcall(function() child:FireServer(placePos) end)
                        elseif child:IsA("RemoteFunction") then
                            pcall(function() child:InvokeServer("CreateEgg", placePos) end)
                            pcall(function() child:InvokeServer(placePos) end)
                        end
                    end
                end
            end)

            placedCount = placedCount + 1
            task.wait(0.35)
        end
    end

    -- Brief pause for final placed egg to replicate into garden
    task.wait(0.8)

    pcall(function()
        local char = LocalPlayer.Character
        if char then
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            if humanoid then
                humanoid:UnequipTools()
            end
        end
    end)

    local finalPlaced = HatchFunctions.GetCurrentPlacedEggCount()
    return (finalPlaced > 0 or placedCount > 0), stopReason
end

--[[
    GAG 1 Hub - Hatch Functions: Selling & Pet Management Engine
    Auto-favorites non-matching pets to protect them, then calls SellAllPets_RE to sell unfavorited target pets.
--]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

local GameEvents = ReplicatedStorage:WaitForChild("GameEvents")
local Favorite_Item = GameEvents:WaitForChild("Favorite_Item")
local Favorite_Item_BE = GameEvents:WaitForChild("Favorite_Item_BE")
local SellAllPets_RE = GameEvents:WaitForChild("SellAllPets_RE")

-- Helper to check if pet is favorited (Attribute 'd')
local function isPetFavorited(petObj)
    if not petObj then return false end
    return (petObj:GetAttribute("d") == true)
end

-- Helper to strictly identify Pet Tools (excluding seeds, sprinklers, eggs, tools)
local function isPetTool(tool)
    if HatchFunctions and typeof(HatchFunctions.IsPetTool) == "function" then
        return HatchFunctions.IsPetTool(tool)
    end
    if not tool or not tool:IsA("Tool") then return false end
    local itemType = tool:GetAttribute("ItemType")
    local petType  = tool:GetAttribute("PetType")
    local petUuid  = tool:GetAttribute("PET_UUID")
    local hasKg    = tool.Name:find("%[[%d%.]+%s*[Kk][Gg]%]") ~= nil
    return (itemType == "Pet" or petType == "Pet" or (petUuid ~= nil and type(petUuid) == "string" and petUuid ~= "") or hasKg)
end

-- Helper to auto-favorite pet (protect non-matching pets)
local function autoFavoritePet(petObj)
    if not petObj or not isPetTool(petObj) then return end
    pcall(function()
        petObj:SetAttribute("d", true)
        Favorite_Item:FireServer(petObj)
        task.delay(0.25, function()
            if Favorite_Item_BE and petObj and petObj.Parent then
                Favorite_Item_BE:Fire(petObj)
            end
        end)
    end)
end

-- Helper to clean pet species name (strips brackets, parens, percentages, rarities, etc.)
local function cleanPetSpecies(str)
    if not str or type(str) ~= "string" then return "" end
    local clean = str:gsub("%s*%[[^%]]+%]%s*", "")
                     :gsub("%s*%([^%)]+%)%s*", "")
                     :gsub("%s*#%d+$", "")
                     :gsub("^%s*(.-)%s*$", "%1")
                     :lower()
    return clean
end

-- Sell Pet by Rules with Auto-Favorite Protection & SellAllPets_RE
function HatchFunctions.SellPetByWeight(targetPets, weightVal, weightCond, ageVal, ageCond, mode, threshold)
    weightVal = tonumber(weightVal) or 6.0
    weightCond = weightCond or "Below"
    ageVal = tonumber(ageVal) or 3
    ageCond = ageCond or "Below"
    mode = mode or "Based on Cycle"
    threshold = tonumber(threshold) or 1

    local settings = (Automation and Automation.Settings) or (getgenv and getgenv().Automation and getgenv().Automation.Settings) or {}

    -- Build set of pets assigned in ANY configured Pet Team (NEVER SELL TEAM PETS)
    local teamProtectedNames = {}
    local teamProtectedUUIDs = {}
    if settings.Teams then
        for _, teamList in pairs(settings.Teams) do
            if type(teamList) == "table" then
                for _, petName in ipairs(teamList) do
                    if type(petName) == "string" and petName ~= "" then
                        teamProtectedNames[cleanPetSpecies(petName)] = true
                        local rawClean = petName:match("^(.-)%s*#%d+$") or petName
                        teamProtectedNames[cleanPetSpecies(rawClean)] = true
                    end
                end
            end
        end
    end

    -- Scan player pets from Backpack and Character
    local allPets = {}
    local searchedInstances = {}

    local function scanContainer(container)
        if not container then return end
        for _, child in ipairs(container:GetChildren()) do
            if isPetTool(child) and not searchedInstances[child] then
                searchedInstances[child] = true
                local kgStr = child.Name:match("%[([%d%.]+)%s*[Kk][Gg]%]") or child.Name:match("([%d%.]+)%s*[Kk][Gg]")
                local kg = tonumber(kgStr) or 1.0
                local age = tonumber(child:GetAttribute("b")) or 1
                local rawName = child:GetAttribute("f") or child.Name
                local petUuid = child:GetAttribute("PET_UUID")

                table.insert(allPets, {
                    Instance = child,
                    Name = tostring(rawName),
                    FullSpecies = child.Name,
                    ToolName = child.Name,
                    Weight = kg,
                    Age = age,
                    UUID = petUuid or child.Name,
                    IsFavorite = isPetFavorited(child)
                })
            end
        end
    end

    local backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    scanContainer(backpack)
    scanContainer(LocalPlayer.Character)
    scanContainer(LocalPlayer:FindFirstChild("Pets"))

    if #allPets == 0 then return 0 end

    -- 1. Evaluate Standard Sell Filter Targets
    local selectedStandardTargets = {}
    local hasStandardFilter = false

    local function addStandardTarget(tName)
        if not tName or tName == "" then return end
        local clean = cleanPetSpecies(tName)
        if clean ~= "" and clean ~= "all pets" and clean ~= "all" then
            selectedStandardTargets[clean] = true
            hasStandardFilter = true
        end
    end

    local activeTargets = targetPets or settings.SellTargetPets
    if type(activeTargets) == "string" then
        addStandardTarget(activeTargets)
    elseif type(activeTargets) == "table" then
        for k, v in pairs(activeTargets) do
            if type(v) == "boolean" and v == true then
                addStandardTarget(tostring(k))
            elseif (type(k) == "number" or type(v) == "string") and tostring(v) ~= "true" and tostring(v) ~= "false" then
                addStandardTarget(tostring(v))
            end
        end
    end

    -- 2. Evaluate Advanced Sell Filter Targets
    local advMinKG = tonumber(settings.AdvSellMinKG or settings.AdvMinKG) or 0
    local advTargetPets = settings.AdvSellTargetPets or settings.AdvTargetPets
    local selectedAdvTargets = {}
    local hasAdvFilter = false

    local function addAdvTarget(tName)
        if not tName or tName == "" then return end
        local clean = cleanPetSpecies(tName)
        if clean ~= "" and clean ~= "all pets" and clean ~= "all" then
            selectedAdvTargets[clean] = true
            hasAdvFilter = true
        end
    end

    if type(advTargetPets) == "string" then
        addAdvTarget(advTargetPets)
    elseif type(advTargetPets) == "table" then
        for k, v in pairs(advTargetPets) do
            if type(v) == "boolean" and v == true then
                addAdvTarget(tostring(k))
            elseif (type(k) == "number" or type(v) == "string") and tostring(v) ~= "true" and tostring(v) ~= "false" then
                addAdvTarget(tostring(v))
            end
        end
    end

    -- If advMinKG <= 0, Advanced Sell filter is inactive
    if advMinKG <= 0 or not hasAdvFilter then
        hasAdvFilter = false
        table.clear(selectedAdvTargets)
    end

    -- Matcher helpers
    local function isTargetPet(petData)
        if not hasStandardFilter then return false end
        local pName = cleanPetSpecies(petData.Name)
        local pFull = cleanPetSpecies(petData.FullSpecies)
        local pTool = cleanPetSpecies(petData.ToolName)

        for targetName, _ in pairs(selectedStandardTargets) do
            if pName == targetName or pFull == targetName or pTool == targetName
               or pName:find(targetName, 1, true) or pFull:find(targetName, 1, true) or pTool:find(targetName, 1, true)
               or targetName:find(pName, 1, true) or targetName:find(pFull, 1, true) then
                return true
            end
        end
        return false
    end

    local function isAdvancedMatch(petData)
        if not hasAdvFilter then return false end
        local kg = tonumber(petData.Weight) or 1.0
        local age = tonumber(petData.Age) or 1

        if age > 1 or kg > advMinKG then
            return false
        end

        local pName = cleanPetSpecies(petData.Name)
        local pFull = cleanPetSpecies(petData.FullSpecies)
        local pTool = cleanPetSpecies(petData.ToolName)

        for targetName, _ in pairs(selectedAdvTargets) do
            if pName == targetName or pFull == targetName or pTool == targetName
               or pName:find(targetName, 1, true) or pFull:find(targetName, 1, true) or pTool:find(targetName, 1, true)
               or targetName:find(pName, 1, true) or targetName:find(pFull, 1, true) then
                return true
            end
        end
        return false
    end

    local function isTeamProtected(petData)
        local uuid = petData.UUID or (petData.Instance and petData.Instance:GetAttribute("PET_UUID"))
        if uuid and teamProtectedUUIDs[tostring(uuid)] then return true end

        local tClean = cleanPetSpecies(petData.ToolName)
        local fClean = cleanPetSpecies(petData.FullSpecies)
        if (tClean ~= "" and teamProtectedNames[tClean]) or (fClean ~= "" and teamProtectedNames[fClean]) then
            return true
        end
        return false
    end

    -- Collect pets to sell vs pets to favorite & protect
    local petsToSell = {}
    local petsToFavorite = {}

    for _, petData in ipairs(allPets) do
        local petObj = petData.Instance
        if petObj and petObj.Parent then
            local isFav = isPetFavorited(petObj)
            local isProtected = isTeamProtected(petData)

            if isProtected then
                -- Team pets: if not favorited, favorite them for safety
                if not isFav then
                    table.insert(petsToFavorite, petData)
                end
            else
                local isTarget = isTargetPet(petData)
                local kg = tonumber(petData.Weight) or 1.0
                local age = tonumber(petData.Age) or 1

                local weightMatch = true
                if weightVal and tonumber(weightVal) and tonumber(weightVal) > 0 then
                    local wNum = tonumber(weightVal)
                    if weightCond == "Below" then
                        weightMatch = (kg <= wNum)
                    else
                        weightMatch = (kg >= wNum)
                    end
                end

                local ageMatch = true
                if ageVal and tonumber(ageVal) and tonumber(ageVal) > 0 then
                    local aNum = tonumber(ageVal)
                    if ageCond == "Below" then
                        ageMatch = (age <= aNum)
                    else
                        ageMatch = (age >= aNum)
                    end
                end

                local isStandardMatch = hasStandardFilter and isTarget and weightMatch and ageMatch
                local isAdvMatch = hasAdvFilter and isAdvancedMatch(petData)

                local isEligible = isStandardMatch or isAdvMatch or (mode == "Emergency Full Inventory Sell")

                if isEligible then
                    if not isFav then
                        table.insert(petsToSell, petData)
                    end
                else
                    -- Pet does NOT match sell criteria -> Auto-favorite to protect!
                    if not isFav then
                        table.insert(petsToFavorite, petData)
                    end
                end
            end
        end
    end

    -- Step 1: Auto-favorite all non-matching pets to protect them
    if #petsToFavorite > 0 then
        for _, petData in ipairs(petsToFavorite) do
            if petData.Instance and petData.Instance.Parent then
                autoFavoritePet(petData.Instance)
                task.wait(0.02)
            end
        end
        task.wait(0.3)
    end

    -- If no pets match sell criteria, return 0
    if #petsToSell == 0 then return 0 end

    -- Check Inventory Mode threshold
    if mode == "Based on Inventory" then
        if #petsToSell < threshold then
            return 0
        end
    end

    -- Step 2: Unequip held pets from character before firing SellAllPets_RE
    if LocalPlayer.Character then
        for _, petData in ipairs(petsToSell) do
            local petObj = petData.Instance
            if petObj and petObj.Parent == LocalPlayer.Character then
                pcall(function()
                    local bpk = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
                    if bpk then petObj.Parent = bpk end
                end)
            end
        end
    end

    -- Step 3: Fire SellAllPets_RE to instantly sell all unfavorited matching pets
    local countToSell = #petsToSell
    pcall(function()
        SellAllPets_RE:FireServer()
    end)

    return countToSell
end

--[[
    GAG 1 Hub - Hatch Functions: Analytics & Stats Tracker
--]]

 

HatchFunctions.Stats = HatchFunctions.Stats or {
    TotalHatches = 0,
    LastHatchedPet = "None",
    BrontoHatchedLog = {},
    BrontoHatchedOrder = {}
}
HatchFunctions.UIUpdateCallback = HatchFunctions.UIUpdateCallback or nil

-- Record a pet hatched via Bronto Mode
function HatchFunctions.RecordBrontoHatch(petName, weightStr)
    if not petName or petName == "" then petName = "Pet" end
    HatchFunctions.Stats.BrontoHatchedLog = HatchFunctions.Stats.BrontoHatchedLog or {}
    HatchFunctions.Stats.BrontoHatchedOrder = HatchFunctions.Stats.BrontoHatchedOrder or {}

    if not HatchFunctions.Stats.BrontoHatchedLog[petName] then
        HatchFunctions.Stats.BrontoHatchedLog[petName] = {}
        table.insert(HatchFunctions.Stats.BrontoHatchedOrder, petName)
    end
    table.insert(HatchFunctions.Stats.BrontoHatchedLog[petName], weightStr or "Unknown KG")
end

-- Helper: Get Weight Classification based on Hatch Weight (in KG)
function HatchFunctions.GetWeightClassification(weightKg)
    local kg = tonumber(weightKg) or 0
    if kg < 1.0 then
        return "Small"
    elseif kg < 2.0 then
        return "Normal"
    elseif kg < 3.0 then
        return "Large"
    elseif kg < 5.0 then
        return "Semi Huge"
    elseif kg < 7.0 then
        return "Huge"
    elseif kg < 8.0 then
        return "Semi Titanic"
    elseif kg < 9.0 then
        return "Titanic"
    elseif kg < 10.0 then
        return "Godly"
    else
        return "Colossal"
    end
end

-- Get formatted summary string of Bronto Hatched Pets for Webhook (Sorted from Heaviest to Smallest KG with Classification)
function HatchFunctions.GetBrontoHatchedSummary()
    local log = HatchFunctions.Stats and HatchFunctions.Stats.BrontoHatchedLog
    local order = HatchFunctions.Stats and HatchFunctions.Stats.BrontoHatchedOrder
    if not log or not order or #order == 0 then
        return "No pets hatched with Bronto Mode yet"
    end

    local function parseKG(wStr)
        if not wStr then return 0 end
        local num = tonumber(tostring(wStr):match("([%d%.]+)"))
        return num or 0
    end

    local entries = {}
    for petName, weights in pairs(log) do
        if weights and #weights > 0 then
            local sortedWeights = {}
            for _, w in ipairs(weights) do
                table.insert(sortedWeights, tostring(w))
            end

            table.sort(sortedWeights, function(a, b)
                return parseKG(a) > parseKG(b)
            end)

            local maxW = parseKG(sortedWeights[1])

            table.insert(entries, {
                Name = petName,
                Weights = sortedWeights,
                MaxWeight = maxW
            })
        end
    end

    if #entries == 0 then
        return "No pets hatched with Bronto Mode yet"
    end

    table.sort(entries, function(a, b)
        if a.MaxWeight ~= b.MaxWeight then
            return a.MaxWeight > b.MaxWeight
        end
        return a.Name < b.Name
    end)

    local lines = {}
    for _, entry in ipairs(entries) do
        table.insert(lines, string.format("• **%s**: %s", entry.Name, table.concat(entry.Weights, ", ")))
    end

    return table.concat(lines, "\n")
end

-- Reset Stats Counter
function HatchFunctions.ResetStats()
    HatchFunctions.Stats.TotalHatches = 0
    HatchFunctions.Stats.LastHatchedPet = "None"
    HatchFunctions.Stats.BrontoHatchedLog = {}
    HatchFunctions.Stats.BrontoHatchedOrder = {}

    if typeof(HatchFunctions.UIUpdateCallback) == "function" then
        pcall(HatchFunctions.UIUpdateCallback)
    end
end

-- Compact Formatted Stats Text for UI (Clean wrapping with Teams & Live Status)
function HatchFunctions.GetFormattedStats(automationRef)
    local s = HatchFunctions.Stats or { TotalHatches = 0, LastHatchedPet = "None" }

    -- Determine Selected Pet Teams with Count and Grouped Species
    local teams = (automationRef and automationRef.Settings and automationRef.Settings.Teams) or {}
    local formatTeam = function(list)
        if not list or #list == 0 then return "(0) None" end
        
        local counts = {}
        local order = {}
        for _, rawName in ipairs(list) do
            local cleanName = tostring(rawName):gsub(" #%d+$", ""):gsub("%s*%[[^%]]+%]",""):gsub("^%s*(.-)%s*$", "%1")
            if not counts[cleanName] then
                counts[cleanName] = 0
                table.insert(order, cleanName)
            end
            counts[cleanName] = counts[cleanName] + 1
        end

        local speciesParts = {}
        for _, name in ipairs(order) do
            local qty = counts[name]
            if qty > 1 then
                table.insert(speciesParts, string.format("%s (%d)", name, qty))
            else
                table.insert(speciesParts, name)
            end
        end

        return string.format("(%d) %s", #list, table.concat(speciesParts, ", "))
    end

    local reduceStr = formatTeam(teams.Reduce)
    local hatchStr  = formatTeam(teams.Hatch)
    local sellStr   = formatTeam(teams.Sell)
    local brontoStr = formatTeam(teams.Bronto)

    -- Determine Current Active Action Status (Detailed Auto Hatch Workflow)
    local status = "Idle"
    if automationRef and automationRef.States then
        local st = automationRef.States
        if st.AutoHatch then
            if st.BrontoMode then
                status = "Bronto Mode Active"
            elseif st.CurrentActionStatus then
                status = tostring(st.CurrentActionStatus)
            else
                status = "Auto Hatch Running"
            end
        elseif st.BrontoMode then
            status = "Bronto Mode Standby"
        elseif st.AutoSellPet then
            status = "Selling Pets"
        elseif st.AutoPlaceEgg or st.AutoBuyEgg or st.AutoSellEgg then
            status = "Reducing Egg Hatch Time"
        end
    end

    local currentCycles = (HatchFunctions.Stats and HatchFunctions.Stats.CurrentCycles) or 0
    local cycleThreshold = (automationRef and automationRef.Settings and automationRef.Settings.SellModeThreshold) or 5

    local curPets, maxSlots = 0, 200
    if HatchFunctions and typeof(HatchFunctions.GetPetInventorySlotInfo) == "function" then
        curPets, maxSlots = HatchFunctions.GetPetInventorySlotInfo()
    end
    maxSlots = maxSlots or 200
    local invStr = string.format("%d/%d", curPets or 0, maxSlots or 200)

    return string.format(
        "Total Hatches: %d | Current Cycle: %d/%d\n" ..
        "Pet Inventory: %s | Last Hatched: %s\n\n" ..
        "--- Pet Teams Configured ---\n" ..
        "Reduce Team: %s\n" ..
        "Hatch Team: %s\n" ..
        "Sell Team: %s\n" ..
        "Bronto Team: %s\n\n" ..
        "Auto Hatch Status: %s",
        s.TotalHatches or 0,
        currentCycles, cycleThreshold,
        invStr,
        s.LastHatchedPet or "None",
        reduceStr, hatchStr, sellStr, brontoStr,
        status
    )
end
return HatchFunctions
end)()

local InventoryFunctions = (function()
local InventoryFunctions = {}
