--[[
    GAG 1 Hub - Pet Inventory & Favorite Management
    Strictly tailored to actual Roblox Pet Tool properties:
      Tool Name: "Alienated Magpie [11.86 KG]"
      Attributes:
        a        = Username owner (string)
        b        = Level/Age string/number (e.g. 1)
        d        = Favorite Status (boolean: true/false)
        f        = Species Name (string, e.g. "Magpie")
        ItemType = "Pet"
        PetType  = "Pet"
        OWNER    = Username string
        PET_UUID = Unique ID string
--]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

local InventoryFunctions = InventoryFunctions or {}

-- Remotes & Events
local GameEvents = ReplicatedStorage:WaitForChild("GameEvents")
local Favorite_Item = GameEvents:WaitForChild("Favorite_Item")
local Favorite_Item_BE = GameEvents:WaitForChild("Favorite_Item_BE")

-- Helper to resolve EnumId or Mutation string
local MUTATION_ENUM_MAP = {
    ["a"] = "Shocked", ["b"] = "Golden", ["c"] = "Rainbow", ["d"] = "Shiny",
    ["e"] = "Windy", ["f"] = "Frozen", ["g"] = "Inverted", ["h"] = "Normal",
    ["i"] = "Mega", ["j"] = "Tiny", ["k"] = "IronSkin", ["l"] = "Radiant",
    ["m"] = "Normal", ["n"] = "Ascended", ["o"] = "Tranquil", ["p"] = "Corrupted",
    ["q"] = "Fried", ["r"] = "Aromatic", ["s"] = "Silver", ["t"] = "GiantBean",
    ["u"] = "Glimmering", ["v"] = "Luminous", ["w"] = "Nutty", ["x"] = "Dreadbound",
    ["y"] = "Soulflame", ["z"] = "Spectral", ["A"] = "Nightmare", ["B"] = "Tethered",
    ["H"] = "Aurora", ["I"] = "JUMBO", ["J"] = "Oxpecker", ["K"] = "Giraffe",
    ["L"] = "Rhino", ["M"] = "Crocodile", ["N"] = "Lion", ["O"] = "Forger",
    ["P"] = "HyperHunger", ["Q"] = "Nocturnal", ["R"] = "Peppermint", ["SS"] = "SpiritSparkle",
    ["S"] = "ChristmasRally", ["T"] = "MerryNursery", ["U"] = "JollyDecorator",
    ["V"] = "GiantGolem", ["W"] = "Fiery", ["X"] = "Venom", ["Y"] = "UFO",
    ["Z"] = "Alienated", ["@"] = "Blossoming", ["EV"] = "Everchanted", ["RJ"] = "RoyalJelly",
    ["EM"] = "Ember", ["EX"] = "Exalted", ["IR"] = "Iridescent", ["GG"] = "Gigantic",
    ["TS"] = "Transcendent", ["IN"] = "Inferno"
}

local function resolveMutationName(rawMut)
    if not rawMut or rawMut == "" then return nil end
    local str = tostring(rawMut)
    if str:lower() == "none" or str:lower() == "normal" then return nil end
    if MUTATION_ENUM_MAP[str] then
        local mapped = MUTATION_ENUM_MAP[str]
        if mapped ~= "Normal" then return mapped end
    end
    return str
end

-- Helper to parse species, KG, and Age from Tool Name pattern
-- Example Tool Name: "Alienated Magpie [11.86 KG]" or "Kirin [0.93 KG] [Age 1]"
local function parseNameData(toolName)
    local rawClean = toolName:match("^([^%[]+)") or toolName
    rawClean = rawClean:match("^%s*(.-)%s*$") or rawClean

    local kgStr = toolName:match("%[([%d%.]+)%s*[Kk][Gg]%]") or toolName:match("([%d%.]+)%s*[Kk][Gg]")
    local kg = tonumber(kgStr)

    local ageStr = toolName:match("%[[Aa]ge%s*(%d+)%]") or toolName:match("[Aa]ge%s*(%d+)")
    local age = tonumber(ageStr)

    return rawClean, kg, age
end

local function isPetTool(tool)
    if HatchFunctions and typeof(HatchFunctions.IsPetTool) == "function" then
        return HatchFunctions.IsPetTool(tool)
    end
    if not tool or not tool:IsA("Tool") then return false end
    local itemType = tool:GetAttribute("ItemType")
    local petType  = tool:GetAttribute("PetType")
    local petUuid  = tool:GetAttribute("PET_UUID")
    return (itemType == "Pet" or petType == "Pet") and (petUuid ~= nil and type(petUuid) == "string" and petUuid ~= "")
end

-- Resolve single pet tool data completely using exact GAG 1 Attributes & Tool Name
local function resolveToolPetData(tool)
    if not isPetTool(tool) then return nil end

    local speciesFromAttr = tool:GetAttribute("f")
    local petUuid         = tool:GetAttribute("PET_UUID")
    local rawLevel        = tool:GetAttribute("b")
    local isFav           = (tool:GetAttribute("d") == true)

    local parsedName, parsedKG, parsedAge = parseNameData(tool.Name)

    local species = (speciesFromAttr and tostring(speciesFromAttr) ~= "" and tostring(speciesFromAttr):lower() ~= "pet") and tostring(speciesFromAttr) or parsedName
    local weight  = parsedKG or 1.0
    local level   = tonumber(rawLevel) or parsedAge or 1

    local mutation = nil
    if parsedName then
        for _, mutName in pairs(MUTATION_ENUM_MAP) do
            if mutName ~= "Normal" and parsedName:lower():find("^" .. mutName:lower() .. "%s+") then
                mutation = mutName
                break
            end
        end
    end

    if mutation then
        if mutation:lower() == "ufo" then
            mutation = "Ufo"
        else
            mutation = mutation:sub(1,1):upper() .. mutation:sub(2):lower()
        end
    end

    -- Clean species name
    local cleanSpecies = species:gsub("%s*%[[^%]]+%]%s*", ""):gsub("%s*%([^%)]+%)%s*", ""):gsub("[\r\n\t\0\160]", " "):gsub("%s+", " ")
    if mutation and mutation ~= "" then
        cleanSpecies = cleanSpecies:gsub("^" .. mutation .. "%s*", ""):gsub("^" .. mutation:lower() .. "%s*", ""):gsub("^" .. mutation:upper() .. "%s*", "")
    end
    cleanSpecies = cleanSpecies:match("^%s*(.-)%s*$") or cleanSpecies
    if cleanSpecies == "" then cleanSpecies = "Pet" end

    local cleanAttrF = speciesFromAttr and tostring(speciesFromAttr):gsub("[\r\n\t\0\160]", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
    local finalSpeciesName = (cleanAttrF and cleanAttrF ~= "" and cleanAttrF:lower() ~= "pet") and cleanAttrF or cleanSpecies

    -- Build full species name (e.g., "Alienated Magpie")
    local fullSpecies = cleanSpecies
    if mutation and mutation ~= "" and mutation ~= "Normal" and mutation ~= "None" then
        fullSpecies = mutation .. " " .. cleanSpecies
    end

    return {
        Instance = tool,
        Name = finalSpeciesName,
        FullSpecies = fullSpecies,   -- e.g. "Alienated Magpie"
        ToolName = tool.Name,        -- e.g. "Alienated Magpie [11.64 KG]"
        Weight = weight,
        Age = level,
        Mutation = mutation,
        UUID = petUuid,
        IsFavorite = isFav
    }
end

-- Get Player's Current Pet Inventory from Backpack, Character, Pets folder
function InventoryFunctions.GetPlayerPets()
    local petList = {}
    local searchedFolders = {}

    local function scanFolder(folder)
        if not folder or searchedFolders[folder] then return end
        searchedFolders[folder] = true
        for _, child in ipairs(folder:GetChildren()) do
            local petData = resolveToolPetData(child)
            if petData then
                table.insert(petList, petData)
            end
        end
    end

    scanFolder(LocalPlayer:FindFirstChild("Backpack"))
    if LocalPlayer.Character then
        scanFolder(LocalPlayer.Character)
    end
    scanFolder(LocalPlayer:FindFirstChild("Pets"))
    if LocalPlayer:FindFirstChild("PlayerData") then
        scanFolder(LocalPlayer.PlayerData:FindFirstChild("Pets"))
        scanFolder(LocalPlayer.PlayerData:FindFirstChild("Inventory"))
    end

    return petList
end

-- Get unique pet species names for dropdown (Strictly attribute 'f', e.g. "Magpie", "Mimic Octopus")
function InventoryFunctions.GetInventoryPetNames()
    local pets = InventoryFunctions.GetPlayerPets()
    local nameMap = {}
    local result = {}
    
    for _, p in ipairs(pets) do
        local cleanName = p.Name
        if cleanName and cleanName ~= "" and cleanName:lower() ~= "pet" and not nameMap[cleanName] then
            nameMap[cleanName] = true
            table.insert(result, cleanName)
        end
    end

    table.sort(result)
    return result
end

-- Check if a pet is favorited (Strict GAG 1 Attribute 'd')
function InventoryFunctions.IsPetFavorited(petObj)
    if not petObj then return false end
    return (petObj:GetAttribute("d") == true)
end

-- Set Pet Favorite status (targetState: true = favorite, false = unfavorite)
function InventoryFunctions.SetPetFavorite(targetPetNames, minKG, weightCond, minAge, ageCond, targetState)
    minKG = tonumber(minKG) or 0
    weightCond = weightCond or "Above"
    minAge = tonumber(minAge) or 0
    ageCond = ageCond or "Above"

    local isSelectAll = false
    local targetSet = {}

    if type(targetPetNames) == "string" then
        if targetPetNames == "All Pets" or targetPetNames == "All" or targetPetNames == "" then
            isSelectAll = true
        else
            targetSet[targetPetNames:lower()] = true
        end
    elseif type(targetPetNames) == "table" then
        local count = 0
        for k, v in pairs(targetPetNames) do
            if v == true then
                targetSet[tostring(k):lower()] = true
                count = count + 1
            elseif type(v) == "string" and v ~= "" then
                targetSet[v:lower()] = true
                count = count + 1
            end
        end
        if count == 0 then
            isSelectAll = true
        end
    else
        isSelectAll = true
    end

    local pets = InventoryFunctions.GetPlayerPets()
    local processedCount = 0

    for _, petData in ipairs(pets) do
        local petObj = petData.Instance
        local nameMatch = isSelectAll
            or targetSet[petData.Name:lower()]
            or targetSet[petData.FullSpecies:lower()]
            or targetSet[petData.ToolName:lower()]
        
        if nameMatch then
            local kg = petData.Weight
            local age = petData.Age

            local weightMatch
            if weightCond == "Below" then
                weightMatch = (kg <= minKG)
            else
                weightMatch = (kg >= minKG)
            end

            local ageMatch
            if ageCond == "Below" then
                ageMatch = (age <= minAge)
            else
                ageMatch = (age >= minAge)
            end

            if weightMatch and ageMatch then
                local isFav = petData.IsFavorite
                if (targetState and not isFav) or (not targetState and isFav) then
                    pcall(function()
                        petObj:SetAttribute("d", targetState)
                        Favorite_Item:FireServer(petObj)
                        task.delay(0.25, function()
                            if Favorite_Item_BE and petObj and petObj.Parent then
                                Favorite_Item_BE:Fire(petObj)
                            end
                        end)
                    end)
                    processedCount = processedCount + 1
                end
            end
        end
    end

    return processedCount
end

--[[
    GAG 1 Hub - Trade Ticket Engine
    Full Trade Lifecycle Automation for both Sender and Receiver:
      - Sender: Equip Tool -> SendRequest -> Wait Acceptance -> AddItems (max 12) -> Loop Accept & Confirm
      - Receiver: RespondRequest (Accept incoming ticket) -> Wait Session -> Loop Accept & Confirm
--]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

local InventoryFunctions = InventoryFunctions or {}

-- TradeEvents Remotes & Request Tracking
local GameEvents = ReplicatedStorage:WaitForChild("GameEvents")
local TradeEvents = GameEvents:WaitForChild("TradeEvents")
local SendRequest = TradeEvents:WaitForChild("SendRequest")
local RespondRequest = TradeEvents:WaitForChild("RespondRequest")
local AddItem = TradeEvents:WaitForChild("AddItem")
local Accept = TradeEvents:WaitForChild("Accept")
local Confirm = TradeEvents:WaitForChild("Confirm")

local pendingTradeRequests = {}
local isTradeSessionBeingHandled = false

-- Auto-listen to incoming trade requests directly on SendRequest.OnClientEvent
pcall(function()
    SendRequest.OnClientEvent:Connect(function(requestId, senderPlayer, timeout)
        if requestId and type(requestId) == "string" and requestId ~= "" then
            table.insert(pendingTradeRequests, requestId)

            local autoAccept = (Automation and Automation.States and Automation.States.AutoAcceptTradeTicket)
            if autoAccept then
                task.spawn(function()
                    task.wait(0.05)
                    RespondRequest:FireServer(requestId, true)

                    -- Wait until trade session window becomes active
                    local waitStart = os.clock()
                    while os.clock() - waitStart < 15 do
                        if InventoryFunctions.IsTradeSessionActive() then
                            break
                        end
                        task.wait(0.25)
                    end

                    -- Auto-loop Accept & Confirm on receiver side
                    if InventoryFunctions.IsTradeSessionActive() then
                        task.wait(1.2) -- Give sender time to place items
                        local tradeLoopStart = os.clock()
                        while InventoryFunctions.IsTradeSessionActive() and (os.clock() - tradeLoopStart < 45) and (Automation and Automation.States and Automation.States.AutoAcceptTradeTicket) do
                            InventoryFunctions.AcceptActiveTrade()
                            task.wait(0.5)
                            InventoryFunctions.ConfirmActiveTrade()
                            task.wait(0.5)
                        end
                    end
                end)
            end
        end
    end)
end)

-- Helper to check if a trade session is currently active
function InventoryFunctions.IsTradeSessionActive()
    local active = false
    
    -- 1. Check TradingController
    pcall(function()
        local tc = require(ReplicatedStorage.Modules.TradeControllers.TradingController)
        if tc and tc.CurrentTradeReplicator ~= nil then
            active = true
        end
    end)
    if active then return true end

    -- 2. Check PlayerGui for trade windows
    pcall(function()
        local pGui = LocalPlayer:FindFirstChild("PlayerGui")
        if pGui then
            local tradeGuis = {"TradingUI", "TradeUI", "Trade", "Trading", "TradeWindow", "TradeFrame"}
            for _, gName in ipairs(tradeGuis) do
                local gui = pGui:FindFirstChild(gName)
                if gui and (gui.Enabled == true or (gui:IsA("GuiObject") and gui.Visible == true)) then
                    active = true
                    return
                end
            end
        end
    end)

    return active
end

-- Helper to find and equip Trade Ticket tool into player's hand
function InventoryFunctions.EquipTradeTicketTool()
    local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local hum = char:FindFirstChildOfClass("Humanoid")
    local backpack = LocalPlayer:FindFirstChild("Backpack")

    -- Check if character is already holding Trade Ticket
    for _, tool in ipairs(char:GetChildren()) do
        if tool:IsA("Tool") then
            local tName = tool.Name:lower()
            local itemType = tostring(tool:GetAttribute("ItemType") or ""):lower()
            local petType = tostring(tool:GetAttribute("PetType") or ""):lower()
            if (tName:find("ticket") or itemType:find("ticket") or petType:find("ticket")) and not tool:GetAttribute("PET_UUID") then
                return tool
            end
        end
    end

    -- Search Backpack for Trade Ticket tool
    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA("Tool") then
                local tName = tool.Name:lower()
                local itemType = tostring(tool:GetAttribute("ItemType") or ""):lower()
                local petType = tostring(tool:GetAttribute("PetType") or ""):lower()
                if (tName:find("ticket") or itemType:find("ticket") or petType:find("ticket")) and not tool:GetAttribute("PET_UUID") then
                    pcall(function()
                        if hum then
                            hum:UnequipTools()
                            task.wait(0.05)
                            hum:EquipTool(tool)
                        else
                            tool.Parent = char
                        end
                    end)
                    task.wait(0.2)
                    return tool
                end
            end
        end
    end

    return nil
end

-- Helper to perform Accept trade remote
function InventoryFunctions.AcceptActiveTrade()
    pcall(function()
        Accept:FireServer()
    end)
    pcall(function()
        local tc = require(ReplicatedStorage.Modules.TradeControllers.TradingController)
        if tc and typeof(tc.Accept) == "function" then
            tc:Accept()
        end
    end)
end

-- Helper to perform Confirm trade remote
function InventoryFunctions.ConfirmActiveTrade()
    pcall(function()
        Confirm:FireServer()
    end)
    pcall(function()
        local tc = require(ReplicatedStorage.Modules.TradeControllers.TradingController)
        if tc and typeof(tc.Confirm) == "function" then
            tc:Confirm()
        end
    end)
end

-- Helper to get list of online server player names (excluding LocalPlayer)
function InventoryFunctions.GetServerPlayerList()
    local list = {}
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer then
            table.insert(list, player.Name)
        end
    end
    table.sort(list)
    return list
end

-- Helper to find Player object by name or display name
function InventoryFunctions.FindPlayerByName(nameStr)
    if not nameStr or nameStr == "" then return nil end
    local cleanName = tostring(nameStr):lower()
    for _, p in ipairs(Players:GetPlayers()) do
        if p.Name:lower() == cleanName or p.DisplayName:lower() == cleanName then
            return p
        end
    end
    return nil
end

-- Helper to get pet names formatted with total count in inventory (e.g., "Mimic Octopus x7")
function InventoryFunctions.GetTicketInventoryPetNamesWithCount()
    local pets = (InventoryFunctions.GetPlayerPets and InventoryFunctions.GetPlayerPets()) or {}
    local countMap = {}
    local order = {}

    for _, p in ipairs(pets) do
        local raw = tostring(p.Name or p.FullSpecies or "")
        -- Remove brackets, parens, existing x count, hashtag numbers, and clean non-printable characters
        local clean = raw:gsub("%s*%[[^%]]+%]%s*", "")
                         :gsub("%s*%([^%)]+%)%s*", "")
                         :gsub("%s*x%d+$", "")
                         :gsub("%s*#%d+$", "")
                         :gsub("[\r\n\t\0\160]", " ")
                         :gsub("%s+", " ")
                         :match("^%s*(.-)%s*$")

        if clean and clean ~= "" and clean:lower() ~= "pet" then
            if not countMap[clean] then
                countMap[clean] = 0
                table.insert(order, clean)
            end
            countMap[clean] = countMap[clean] + 1
        end
    end

    table.sort(order)

    local result = {}
    for _, name in ipairs(order) do
        local count = countMap[name] or 1
        local cleanName = name:gsub("[\r\n\t\0\160]", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
        table.insert(result, cleanName .. " x" .. tostring(count))
    end

    return result
end

-- Helper to filter matching pets up to maximum limit (Default: 12 pets)
function InventoryFunctions.GetMatchingTradePets(targetPetNames, minKG, weightCond, minAge, ageCond, maxLimit)
    maxLimit = tonumber(maxLimit) or 12
    minKG = tonumber(minKG) or 0
    weightCond = weightCond or "Below"
    minAge = tonumber(minAge) or 0
    ageCond = ageCond or "Below"

    local isSelectAll = false
    local targetSet = {}

    local function cleanSpecies(str)
        if not str then return "" end
        local raw = tostring(str):match("^(.-)%s+x%d+$") or tostring(str)
        return raw:gsub("%s*%[[^%]]+%]%s*", "")
                  :gsub("%s*%([^%)]+%)%s*", "")
                  :gsub("%s*x%d+$", "")
                  :gsub("%s*#%d+$", "")
                  :gsub("[\r\n\t\0\160]", " ")
                  :gsub("%s+", " ")
                  :match("^%s*(.-)%s*$"):lower()
    end

    if type(targetPetNames) == "string" then
        if targetPetNames == "All Pets" or targetPetNames == "All" then
            isSelectAll = true
        elseif targetPetNames ~= "" then
            local sp = cleanSpecies(targetPetNames)
            if sp ~= "" then
                targetSet[sp] = true
            end
        else
            return {} -- Never select all if empty
        end
    elseif type(targetPetNames) == "table" then
        local count = 0
        for k, v in pairs(targetPetNames) do
            if v == true then
                local sp = cleanSpecies(k)
                if sp ~= "" and sp ~= "all" and sp ~= "all pets" then
                    targetSet[sp] = true
                    count = count + 1
                elseif sp == "all" or sp == "all pets" then
                    isSelectAll = true
                    count = count + 1
                end
            elseif type(v) == "string" and v ~= "" then
                local sp = cleanSpecies(v)
                if sp ~= "" and sp ~= "all" and sp ~= "all pets" then
                    targetSet[sp] = true
                    count = count + 1
                elseif sp == "all" or sp == "all pets" then
                    isSelectAll = true
                    count = count + 1
                end
            end
        end
        if count == 0 and not isSelectAll then
            return {} -- Return empty! Never select random pets if selection is empty!
        end
    else
        return {} -- Return empty!
    end

    local pets = (InventoryFunctions.GetPlayerPets and InventoryFunctions.GetPlayerPets()) or {}
    local matchingPets = {}

    for _, petData in ipairs(pets) do
        if #matchingPets >= maxLimit then
            break
        end

        local petObj = petData.Instance
        if petObj and petObj.Parent then
            local pNameClean = cleanSpecies(petData.Name)
            local pFullClean = cleanSpecies(petData.FullSpecies)
            local pToolClean = cleanSpecies(petData.ToolName)

            local nameMatch = isSelectAll
                or (pNameClean ~= "" and targetSet[pNameClean])
                or (pFullClean ~= "" and targetSet[pFullClean])
                or (pToolClean ~= "" and targetSet[pToolClean])
            
            if nameMatch then
                local kg = petData.Weight or 0
                local age = petData.Age or 1

                -- Robust Weight Match: Ignore if minKG <= 0
                local weightMatch = true
                if minKG > 0 then
                    if weightCond == "Below" then
                        weightMatch = (kg <= minKG)
                    else
                        weightMatch = (kg >= minKG)
                    end
                end

                -- Robust Age Match: Ignore if default / 0 / 1-below
                local ageMatch = true
                if minAge > 1 or (minAge == 1 and ageCond == "Above") then
                    if ageCond == "Below" then
                        ageMatch = (age <= minAge)
                    else
                        ageMatch = (age >= minAge)
                    end
                end

                if weightMatch and ageMatch then
                    table.insert(matchingPets, petData)
                end
            end
        end
    end

    return matchingPets
end

-- Add matching pets into the active trade ticket (Up to 12 pets maximum)
function InventoryFunctions.AddPetsToActiveTrade(targetPetNames, minKG, weightCond, minAge, ageCond)
    local matchingPets = InventoryFunctions.GetMatchingTradePets(targetPetNames, minKG, weightCond, minAge, ageCond, 12)
    if #matchingPets == 0 then
        return 0, "Tidak ada pet yang sesuai dengan kriteria filter!"
    end

    local addedCount = 0

    for _, petData in ipairs(matchingPets) do
        local petObj = petData.Instance
        if petObj and petObj.Parent then
            local petUuid = petData.UUID 
                or (petObj:GetAttribute("PET_UUID")) 
                or (petObj:GetAttribute("ITEM_UUID")) 
                or (petObj:GetAttribute("UUID"))

            if petUuid and tostring(petUuid) ~= "" then
                local cleanUUID = tostring(petUuid):gsub("[{}]", "")
                local bracedUUID = "{" .. cleanUUID .. "}"

                pcall(function()
                    AddItem:FireServer("Pet", bracedUUID)
                end)
            end

            pcall(function()
                local tc = require(ReplicatedStorage.Modules.TradeControllers.TradingController)
                if tc and typeof(tc.AddFromTool) == "function" then
                    tc:AddFromTool(petObj)
                end
            end)

            addedCount = addedCount + 1
            task.wait(0.12)
        end
    end

    return addedCount, string.format("Berhasil menambahkan %d pet (maks 12) ke dalam tiket trade!", addedCount)
end

-- Handle complete trade execution once trade session is open (Sender side)
function InventoryFunctions.HandleActiveTradeSession(targetPetNames, minKG, weightCond, minAge, ageCond)
    if isTradeSessionBeingHandled then return end
    isTradeSessionBeingHandled = true

    task.spawn(function()
        -- 1. Wait for trade UI & slots to initialize
        task.wait(1.0)

        -- 2. Add matching pets (up to 12 max)
        local addedCount = InventoryFunctions.AddPetsToActiveTrade(targetPetNames, minKG, weightCond, minAge, ageCond)
        
        -- 3. Wait for all items to be confirmed by server before accepting
        task.wait(1.2)

        -- 4. Execute Accept & Confirm loop until trade concludes
        local tradeLoopStart = os.clock()
        while InventoryFunctions.IsTradeSessionActive() and (os.clock() - tradeLoopStart < 45) do
            InventoryFunctions.AcceptActiveTrade()
            task.wait(0.5)
            InventoryFunctions.ConfirmActiveTrade()
            task.wait(0.5)
        end

        isTradeSessionBeingHandled = false
    end)
end

-- Send Trade Ticket to target player, wait for acceptance, populate pets, accept & confirm
function InventoryFunctions.SendTradeTicket(targetPlayerName, targetPetNames, minKG, weightCond, minAge, ageCond)
    local targetPlayer = InventoryFunctions.FindPlayerByName(targetPlayerName)
    if not targetPlayer then
        return 0, "Target player tidak ditemukan di server!"
    end

    -- Check if any matching pets exist before starting
    local matchingCheck = InventoryFunctions.GetMatchingTradePets(targetPetNames, minKG, weightCond, minAge, ageCond, 1)
    if #matchingCheck == 0 then
        return 0, "NoPetsRemaining"
    end

    -- 1. Equip Trade Ticket tool in hand first
    local ticketTool = InventoryFunctions.EquipTradeTicketTool()
    if not ticketTool then
        pcall(function()
            local bp = LocalPlayer:FindFirstChild("Backpack")
            if bp then
                for _, t in ipairs(bp:GetChildren()) do
                    if t:IsA("Tool") and t.Name:lower():find("ticket") then
                        t.Parent = LocalPlayer.Character
                        task.wait(0.2)
                        break
                    end
                end
            end
        end)
    end
    task.wait(0.2)

    -- 2. Fire SendRequest with target player instance
    local ok = pcall(function()
        SendRequest:FireServer(targetPlayer)
    end)

    if not ok then
        return 0, "Gagal mengirim request trade ke " .. targetPlayer.Name
    end

    -- 3. Full lifecycle sequence: Wait for acceptance -> Delegate to HandleActiveTradeSession
    task.spawn(function()
        local startTime = os.clock()
        local sessionStarted = false

        while os.clock() - startTime < 35 do
            if InventoryFunctions.IsTradeSessionActive() then
                sessionStarted = true
                break
            end
            task.wait(0.25)
        end

        if sessionStarted then
            InventoryFunctions.HandleActiveTradeSession(targetPetNames, minKG, weightCond, minAge, ageCond)
        end
    end)

    return 1, string.format("Tiket trade berhasil dikirim ke %s (menunggu diterima)!", targetPlayer.Name)
end

-- Accept incoming Trade Ticket using TradeEvents.RespondRequest & loop Accept/Confirm
function InventoryFunctions.AcceptTradeTicket()
    local acceptedCount = 0

    -- 1. Respond to all captured pending request IDs
    if #pendingTradeRequests > 0 then
        for _, reqId in ipairs(pendingTradeRequests) do
            pcall(function()
                RespondRequest:FireServer(reqId, true)
                acceptedCount = acceptedCount + 1
            end)
        end
        table.clear(pendingTradeRequests)
    end

    -- 2. Check TradingController replicator or active request
    pcall(function()
        local tc = require(ReplicatedStorage.Modules.TradeControllers.TradingController)
        if tc then
            if typeof(tc.AcceptTrade) == "function" then
                tc:AcceptTrade()
                acceptedCount = acceptedCount + 1
            end
            if tc.CurrentTradeReplicator and tc.CurrentTradeReplicator.TradeId then
                RespondRequest:FireServer(tc.CurrentTradeReplicator.TradeId, true)
                acceptedCount = acceptedCount + 1
            end
        end
    end)

    -- 3. Check PlayerGui for trade request elements
    pcall(function()
        if LocalPlayer:FindFirstChild("PlayerGui") then
            for _, gui in ipairs(LocalPlayer.PlayerGui:GetDescendants()) do
                local reqId = gui:GetAttribute("TradeId") or gui:GetAttribute("RequestId") or gui:GetAttribute("TradeUUID")
                if reqId then
                    RespondRequest:FireServer(tostring(reqId), true)
                    acceptedCount = acceptedCount + 1
                end
            end
        end
    end)

    -- 4. If in active trade, loop Accept and Confirm
    if InventoryFunctions.IsTradeSessionActive() then
        InventoryFunctions.AcceptActiveTrade()
        InventoryFunctions.ConfirmActiveTrade()
    end

    return acceptedCount > 0
end

-- Global Trade Session Observer: Automatically handles pet insertion, accept, and confirm
local lastTradeObserved = false
task.spawn(function()
    while true do
        task.wait(0.4)
        local isTradeActive = InventoryFunctions.IsTradeSessionActive()
        if isTradeActive and not lastTradeObserved then
            lastTradeObserved = true
            -- Trade has just opened!
            if (Automation and Automation.States and Automation.States.AutoSendTradeTicket) then
                local st = Automation and Automation.Settings
                local pets = (st and (st.TicketTargetSpecies or st.TicketTargetPets)) or {}
                local wVal = (st and st.TicketWeight) or "0"
                local wCond = (st and st.TicketWeightCond) or "Below"
                local aVal = (st and st.TicketAge) or "1"
                local aCond = (st and st.TicketAgeCond) or "Below"

                InventoryFunctions.HandleActiveTradeSession(pets, wVal, wCond, aVal, aCond)
            elseif (Automation and Automation.States and Automation.States.AutoAcceptTradeTicket) then
                -- Receiver side: wait for sender to insert items, then loop Accept and Confirm
                task.spawn(function()
                    task.wait(1.2)
                    local loopStart = os.clock()
                    while InventoryFunctions.IsTradeSessionActive() and (os.clock() - loopStart < 45) and (Automation and Automation.States and Automation.States.AutoAcceptTradeTicket) do
                        InventoryFunctions.AcceptActiveTrade()
                        task.wait(0.5)
                        InventoryFunctions.ConfirmActiveTrade()
                        task.wait(0.5)
                    end
                end)
            end
        elseif not isTradeActive then
            lastTradeObserved = false
            isTradeSessionBeingHandled = false
        end
    end
end)
return InventoryFunctions
end)()

local MiscFunctions = (function()
local MiscFunctions = {}
--[[
    GAG 1 Hub - Miscellaneous Functions: Garden Egg ESP
--]]

local RS          = game:GetService("ReplicatedStorage")
local Players     = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

local activeEggEsp = {}
local resolvedEggCache = {}

function MiscFunctions.ClearEggESP()
    for _, gui in pairs(activeEggEsp) do
        if gui and gui.Parent then
            pcall(function() gui:Destroy() end)
        end
    end
    table.clear(activeEggEsp)
    if resolvedEggCache then table.clear(resolvedEggCache) end
end

local function formatTimer(sec)
    if not sec or sec <= 0 then return "READY!" end
    local m = math.floor(sec / 60)
    local s = math.floor(sec % 60)
    return string.format("%02d:%02d", m, s)
end

function MiscFunctions.UpdateEggESP()
    local farmFolder = workspace:FindFirstChild("Farm")
    if not farmFolder then return end
    
    local innerFarm = farmFolder:FindFirstChild("Farm") or farmFolder
    local important = innerFarm:FindFirstChild("Important")
    if not important then return end
    
    local objectsPhys = important:FindFirstChild("Objects_Physical")
    if not objectsPhys then return end

    local guiContainer = (gethui and gethui()) or pcall(function() return game:GetService("CoreGui") end) or (LocalPlayer and LocalPlayer:FindFirstChildOfClass("PlayerGui"))
    if typeof(guiContainer) ~= "Instance" and LocalPlayer then
        guiContainer = LocalPlayer:FindFirstChildOfClass("PlayerGui")
    end

    local currentFound = {}

    for _, eggObj in ipairs(objectsPhys:GetChildren()) do
        local childEggModel = eggObj:FindFirstChildWhichIsA("Model")
        local isEgg = eggObj.Name:lower():find("egg") or eggObj:GetAttribute("EggName") or eggObj:GetAttribute("OBJECT_UUID") or eggObj:FindFirstChild("PetEgg") or (childEggModel and childEggModel.Name:lower():find("egg"))
        if isEgg then
            local actualBasePart = eggObj:IsA("BasePart") and eggObj or eggObj:FindFirstChildWhichIsA("BasePart", true)

            if actualBasePart then
                currentFound[eggObj] = true

                local eggName = eggObj:GetAttribute("EggName") or (childEggModel and childEggModel:GetAttribute("EggName")) or (childEggModel and childEggModel.Name ~= "PetEgg" and childEggModel.Name) or eggObj.Name
                local timeToHatch = eggObj:GetAttribute("TimeToHatch") or (childEggModel and childEggModel:GetAttribute("TimeToHatch"))

                local dsPetName, dsPetWeight = nil, nil
                local cachedDetail = resolvedEggCache[eggObj]
                if cachedDetail and cachedDetail.name and cachedDetail.weight then
                    dsPetName = cachedDetail.name
                    dsPetWeight = cachedDetail.weight
                elseif HatchFunctions and typeof(HatchFunctions.GetEggInsidePetDetails) == "function" then
                    dsPetName, dsPetWeight = HatchFunctions.GetEggInsidePetDetails(eggObj)
                    if dsPetName or dsPetWeight then
                        resolvedEggCache[eggObj] = { name = dsPetName, weight = dsPetWeight }
                    end
                end

                local petName = dsPetName or eggObj:GetAttribute("PetName") or eggObj:GetAttribute("Species")
                local petWeight = dsPetWeight or eggObj:GetAttribute("Weight") or eggObj:GetAttribute("KG") or eggObj:GetAttribute("w")

                if not petName or petName == "" or petName:lower() == "petegg" then
                    petName = eggName
                end

                local weightStr = "?"
                if tonumber(petWeight) then
                    weightStr = string.format("%.2f", tonumber(petWeight))
                elseif petWeight and tostring(petWeight) ~= "" then
                    weightStr = tostring(petWeight)
                end

                local timerStr = ""
                if tonumber(timeToHatch) then
                    timerStr = "\n" .. formatTimer(tonumber(timeToHatch))
                end

                local espGui = activeEggEsp[eggObj]
                if not espGui or not espGui.Parent then
                    espGui = Instance.new("BillboardGui")
                    espGui.Name = "GAG_EggESP_" .. tostring(eggObj:GetDebugId())
                    espGui.AlwaysOnTop = true
                    espGui.Size = UDim2.new(0, 240, 0, 65)
                    espGui.StudsOffset = Vector3.new(0, 3.5, 0)
                    
                    local textLabel = Instance.new("TextLabel")
                    textLabel.Name = "ESPLabel"
                    textLabel.Size = UDim2.new(1, 0, 1, 0)
                    textLabel.BackgroundTransparency = 1
                    textLabel.TextColor3 = Color3.fromRGB(255, 230, 60)
                    textLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                    textLabel.TextStrokeTransparency = 0
                    textLabel.Font = Enum.Font.FredokaOne
                    textLabel.TextSize = 13
                    textLabel.TextYAlignment = Enum.TextYAlignment.Center
                    textLabel.Parent = espGui

                    espGui.Adornee = actualBasePart
                    espGui.Parent = guiContainer
                    activeEggEsp[eggObj] = espGui
                else
                    espGui.Adornee = actualBasePart
                end

                local label = espGui:FindFirstChild("ESPLabel")
                if label then
                    local displayPet = dsPetName or petName
                    local hasRevealedPet = displayPet and displayPet ~= "" and displayPet ~= eggName and displayPet:lower() ~= "petegg"

                    local weightVal = tonumber(weightStr) or tonumber(dsPetWeight) or tonumber(petWeight) or 0
                    local classStr = (HatchFunctions and typeof(HatchFunctions.GetWeightClassification) == "function" and HatchFunctions.GetWeightClassification(weightVal)) or "Normal"

                    if hasRevealedPet then
                        if weightStr ~= "?" then
                            label.Text = string.format("%s\n%s (%s KG - %s)%s", eggName, displayPet, weightStr, classStr, timerStr)
                        else
                            label.Text = string.format("%s\n%s%s", eggName, displayPet, timerStr)
                        end
                    else
                        if weightStr ~= "?" then
                            label.Text = string.format("%s\n%s KG - %s%s", eggName, weightStr, classStr, timerStr)
                        else
                            label.Text = string.format("%s%s", eggName, timerStr)
                        end
                    end
                end
            end
        end
    end

    for obj, gui in pairs(activeEggEsp) do
        if not currentFound[obj] or not obj.Parent then
            if gui and gui.Parent then
                pcall(function() gui:Destroy() end)
            end
            activeEggEsp[obj] = nil
            resolvedEggCache[obj] = nil
        end
    end
end

