local MUTATION_PASSIVE_BOOSTS = {
    ["Silver"] = 0.05,
    ["Golden"] = 0.10,
    ["Gold"] = 0.10,
    ["Rainbow"] = 0.20,
    ["Spectral"] = 0.08,
    ["Nightmare"] = 0.22,
    ["Rhino"] = 0.045,
    ["Oxpecker"] = 0.01,
    ["Lion"] = 0.07,
    ["Giraffe"] = 0.03,
    ["Crocodile"] = 0.06,
    ["Forger"] = 0.07,
    ["HyperHunger"] = 0.30,
    ["Hyper Hunger"] = 0.30,
    ["GiantGolem"] = 0.20,
    ["Giant Golem"] = 0.20,
    ["Venom"] = 0.30,
    ["Alienated"] = 0.30,
    ["UFO"] = 0.30,
    ["Blossoming"] = 0.23,
    ["Everchanted"] = 0.30,
    ["RoyalJelly"] = 0.25,
    ["Royal Jelly"] = 0.25,
    ["Ember"] = 0.32,
    ["Inferno"] = 0.25,
    ["Exalted"] = 0.25,
    ["Transcendent"] = 0.35,
}

local function getPassiveBoostForMutation(mutationName, targetTbl, rawPetData, petObj)
    if not mutationName or mutationName == "" or mutationName == "None" then
        return 0
    end

    local cleanName = tostring(mutationName):gsub("%s+", "")
    for k, v in pairs(MUTATION_PASSIVE_BOOSTS) do
        local cleanK = tostring(k):gsub("%s+", "")
        if cleanK:lower() == cleanName:lower() then
            return v
        end
    end

    for _, tbl in ipairs({targetTbl, rawPetData}) do
        if type(tbl) == "table" then
            if tbl.PassiveBoost and tonumber(tbl.PassiveBoost) then
                return tonumber(tbl.PassiveBoost)
            elseif tbl.PassiveMultiplier and tonumber(tbl.PassiveMultiplier) then
                return math.max(0, tonumber(tbl.PassiveMultiplier) - 1)
            end
        end
    end

    if petObj then
        pcall(function()
            local b = petObj:GetAttribute("PassiveBoost") or petObj:GetAttribute("Boost")
            if b and tonumber(b) then
                return tonumber(b)
            end
            local pm = petObj:GetAttribute("PassiveMultiplier")
            if pm and tonumber(pm) then
                return math.max(0, tonumber(pm) - 1)
            end
        end)
    end

    local boost = 0
    pcall(function()
        local mutReg = getMutationRegistry()
        if mutReg then
            local mutDef = mutReg[tostring(mutationName)]
            if not mutDef then
                for mK, mV in pairs(mutReg) do
                    if type(mV) == "table" and tostring(mK):lower() == tostring(mutationName):lower() then
                        mutDef = mV
                        break
                    end
                end
            end
            if mutDef and type(mutDef) == "table" then
                local pb = mutDef.PassiveBoost or mutDef.PassiveMultiplier or mutDef.Boost or mutDef.Multiplier or mutDef.PassiveBonus
                if pb and tonumber(pb) then
                    local pbNum = tonumber(pb)
                    if pbNum > 1 then
                        boost = pbNum - 1
                    else
                        boost = pbNum
                    end
                end
            end
        end
    end)

    return math.max(0, boost)
end

local function getPetUtils()
    if not petUtilsCache then
        pcall(function()
            petUtilsCache = (RS:FindFirstChild("Modules") and RS.Modules:FindFirstChild("PetServices") and RS.Modules.PetServices:FindFirstChild("PetUtilities") and require(RS.Modules.PetServices.PetUtilities))
                         or (RS:FindFirstChild("Modules") and RS.Modules:FindFirstChild("PetUtilities") and require(RS.Modules.PetUtilities))
        end)
    end
    return petUtilsCache
end

local function getPlayerData()
    local ok, ds = pcall(function()
        if not dataServiceCache then
            dataServiceCache = require(RS.Modules.DataService)
        end
        return dataServiceCache
    end)
    if ok and ds and typeof(ds.GetData) == "function" then
        local okData, data = pcall(function() return ds:GetData() end)
        if okData and data then return data end
    end
    return nil
end

local function getReplicatedPetData()
    local ok, repl = pcall(function()
        local repClass = require(RS.Modules.ReplicationClass)
        local rep = repClass.get and repClass.get("ActivePetsService_Replicator")
        if rep and rep.YieldUntilData then
            return rep:YieldUntilData()
        end
        return nil
    end)
    if ok and repl and type(repl) == "table" then
        return repl.Table or repl
    end
    return nil
end

local function cleanUUID(raw)
    if not raw then return "" end
    return tostring(raw):gsub("[{}]", ""):gsub("%-", ""):lower()
end

local function cleanPetName(str)
    if not str or type(str) ~= "string" then return nil end
    local s = str:gsub("%s*%[[%d%.]+%s*[Kk][Gg]%]", "")
                 :gsub("%s*%(([%d%.]+)%s*[Kk][Gg]%)", "")
                 :gsub("%s*[%d%.]+%s*[Kk][Gg]", "")
                 :gsub("%s*%[Age%s*%d+%]","")
                 :gsub("%s*%[Lvl%s*%d+%]","")
                 :gsub("%s*%[Level%s*%d+%]","")
                 :gsub("%s*%[.-%]", "")
                 :gsub("%s*%((.-)%)", "")
                 :gsub("^%s+", ""):gsub("%s+$", "")
    local l = s:lower()
    if l == "" or l == "egg" or l == "petegg" or l == "model" or l == "petmover" or l:find("proximity") then
        return nil
    end
    return s
end

local MUTATION_ENUM_MAP = {
    ["a"] = "Shocked", ["b"] = "Golden", ["c"] = "Rainbow", ["d"] = "Shiny",
    ["e"] = "Windy", ["f"] = "Frozen", ["g"] = "Inverted", ["h"] = "Normal",
    ["i"] = "Mega", ["j"] = "Tiny", ["k"] = "IronSkin", ["l"] = "Radiant",
    ["m"] = "Normal", ["n"] = "Ascended", ["o"] = "Tranquil", ["p"] = "Corrupted",
    ["q"] = "Fried", ["r"] = "Aromatic", ["s"] = "Silver", ["t"] = "GiantBean",
    ["u"] = "Glimmering", ["v"] = "Luminous", ["w"] = "Nutty", ["x"] = "Dreadbound",
    ["y"] = "Soulflame", ["z"] = "Spectral", ["A"] = "Nightmare", ["B"] = "Tethered",
    ["H"] = "Aurora", ["I"] = "JUMBO", ["J"] = "Oxpecker", ["K"] = "Giraffe",
    ["L"] = "Rhino", ["M"] = "Crocodile", ["N"] = "Lion", ["O"] = "Forger",
    ["P"] = "HyperHunger", ["Q"] = "Nocturnal", ["R"] = "Peppermint", ["SS"] = "SpiritSparkle",
    ["S"] = "ChristmasRally", ["T"] = "MerryNursery", ["U"] = "JollyDecorator",
    ["V"] = "GiantGolem", ["W"] = "Fiery", ["X"] = "Venom", ["Y"] = "UFO",
    ["Z"] = "Alienated", ["@"] = "Blossoming", ["EV"] = "Everchanted", ["RJ"] = "RoyalJelly",
    ["EM"] = "Ember", ["EX"] = "Exalted", ["IR"] = "Iridescent", ["GG"] = "Gigantic",
    ["TS"] = "Transcendent", ["IN"] = "Inferno"
}

local function formatPetMutation(mutValue)
    if not mutValue then return nil end

    local mutReg = getMutationRegistry()
    local enumMap = mutReg and mutReg.EnumToPetMutation
    local nameMap = mutReg and mutReg.PetMutationRegistry

    local function resolveSingle(val)
        if not val or val == true or val == false then return nil end
        local s = tostring(val)

        -- 1. EnumId lookup (e.g. "b" -> "Golden", "Z" -> "Alienated")
        if enumMap and enumMap[s] then
            return enumMap[s]
        end
        if MUTATION_ENUM_MAP[s] then
            local mapped = MUTATION_ENUM_MAP[s]
            if mapped ~= "Normal" then return mapped end
        end

        -- 2. Direct string name lookup
        if nameMap and nameMap[s] then
            return s
        end

        -- Check case-insensitive against server mutation registry
        if nameMap then
            for regName, _ in pairs(nameMap) do
                if regName:lower() == s:lower() then
                    return regName
                end
            end
        end

        local l = s:lower()
        if l == "none" or l == "normal" or s == "" or l == "nil" or l == "false" or l == "true" then
            return nil
        end
        return s
    end

    if type(mutValue) == "table" then
        local names = {}
        for k, v in pairs(mutValue) do
            local res = resolveSingle(v)
            if not res then
                res = resolveSingle(k)
            end
            if res and res ~= "None" and res ~= "Normal" then
                if not table.find(names, res) then
                    table.insert(names, res)
                end
            end
        end
        if #names > 0 then
            return table.concat(names, ", ")
        end
    else
        local res = resolveSingle(mutValue)
        if res and res:lower() ~= "none" and res:lower() ~= "normal" then
            return res
        end
    end

    return nil
end

local calcWeightModuleCache = nil
local function getCalculateWeightModule()
    if not calcWeightModuleCache then
        pcall(function()
            if RS:FindFirstChild("Calculate_Weight") then
                calcWeightModuleCache = require(RS.Calculate_Weight)
            end
        end)
    end
    return calcWeightModuleCache
end

local function inspectPetObject(petObj, playerData, replData, petRegistry, petUtils)
    local candidates = {}
    local function addCandidate(val)
        if not val or val == "" or val == true or val == false then return end
        local s = tostring(val)
        if not table.find(candidates, s) then
            table.insert(candidates, s)
        end
        local clean = cleanUUID(s)
        if clean ~= "" and clean ~= s:lower() and not table.find(candidates, clean) then
            table.insert(candidates, clean)
        end
    end

    if petObj then
        addCandidate(petObj:GetAttribute("UUID"))
        addCandidate(petObj:GetAttribute("PET_UUID"))
        addCandidate(petObj:GetAttribute("OBJECT_UUID"))
        addCandidate(petObj:GetAttribute("CosmeticUUID"))
        addCandidate(petObj:GetAttribute("PetUUID"))
        addCandidate(petObj:GetAttribute("EggUUID"))
        addCandidate(petObj:GetAttribute("Id") or petObj:GetAttribute("ID"))
        addCandidate(petObj.Name)

        for attrName, attrVal in pairs(petObj:GetAttributes()) do
            if type(attrVal) == "string" and (#attrVal >= 6 or attrVal:find("%-") or attrVal:find("{")) then
                addCandidate(attrVal)
            end
        end

        for _, child in ipairs(petObj:GetChildren()) do
            addCandidate(child.Name)
            if child:IsA("ValueBase") then
                addCandidate(child.Value)
            end
            for attrName, attrVal in pairs(child:GetAttributes()) do
                if type(attrVal) == "string" and (#attrVal >= 6 or attrVal:find("%-") or attrVal:find("{")) then
                    addCandidate(attrVal)
                end
            end
        end
    end

    local rawPetData = nil

    -- Match entry helper function
    local function matchEntry(sp)
        if type(sp) ~= "table" then return false end
        for _, cand in ipairs(candidates) do
            if cand ~= "" then
                if (sp.UUID and cleanUUID(sp.UUID) == cand) or
                   (sp.PET_UUID and cleanUUID(sp.PET_UUID) == cand) or
                   (sp.OBJECT_UUID and cleanUUID(sp.OBJECT_UUID) == cand) or
                   (sp.CosmeticUUID and cleanUUID(sp.CosmeticUUID) == cand) or
                   (sp.EggUUID and cleanUUID(sp.EggUUID) == cand) or
                   (sp.Id and cleanUUID(sp.Id) == cand) then
                    return true
                end
            end
        end
        return false
    end

    -- 1. Search in ActivePetsService_Replicator
    if replData then
        if type(replData.ServerPetData) == "table" then
            for k, sp in pairs(replData.ServerPetData) do
                for _, cand in ipairs(candidates) do
                    if cleanUUID(k) == cand or tostring(k) == cand then
                        rawPetData = sp
                        break
                    end
                end
                if not rawPetData and matchEntry(sp) then
                    rawPetData = sp
                end
                if rawPetData then break end
            end
        end

        if not rawPetData and type(replData.PlayerPetData) == "table" then
            for _, pData in pairs(replData.PlayerPetData) do
                if type(pData) == "table" then
                    if type(pData.PetInventory) == "table" and type(pData.PetInventory.Data) == "table" then
                        for k, pItem in pairs(pData.PetInventory.Data) do
                            for _, cand in ipairs(candidates) do
                                if cleanUUID(k) == cand or tostring(k) == cand then
                                    rawPetData = pItem
                                    break
                                end
                            end
                            if not rawPetData and matchEntry(pItem) then
                                rawPetData = pItem
                            end
                            if rawPetData then break end
                        end
                    end
                    if not rawPetData and type(pData.ActivePets) == "table" then
                        for k, pItem in pairs(pData.ActivePets) do
                            for _, cand in ipairs(candidates) do
                                if cleanUUID(k) == cand or tostring(k) == cand then
                                    rawPetData = pItem
                                    break
                                end
                            end
                            if not rawPetData and matchEntry(pItem) then
                                rawPetData = pItem
                            end
                            if rawPetData then break end
                        end
                    end
                end
                if rawPetData then break end
            end
        end
    end

    -- 2. Search in playerData (DataService)
    if not rawPetData and playerData then
        local function searchTable(tbl, depth)
            if depth > 7 or type(tbl) ~= "table" then return end
            for k, v in pairs(tbl) do
                if type(v) == "table" then
                    local kClean = cleanUUID(k)
                    local kStr = tostring(k)
                    local match = false
                    for _, cand in ipairs(candidates) do
                        if cand ~= "" and (kClean == cand or kStr == cand or
                           (v.UUID and cleanUUID(v.UUID) == cand) or
                           (v.PET_UUID and cleanUUID(v.PET_UUID) == cand) or
                           (v.OBJECT_UUID and cleanUUID(v.OBJECT_UUID) == cand) or
                           (v.CosmeticUUID and cleanUUID(v.CosmeticUUID) == cand) or
                           (v.EggUUID and cleanUUID(v.EggUUID) == cand) or
                           (v.Id and cleanUUID(v.Id) == cand)) then
                            match = true
                            break
                        end
                    end
                    if match then
                        rawPetData = v
                        return
                    else
                        searchTable(v, depth + 1)
                        if rawPetData then return end
                    end
                end
            end
        end
        searchTable(playerData, 1)
    end

    -- Target subtable unwrapping as in egg_esp.lua
    local targetTbl = rawPetData
    if type(rawPetData) == "table" then
        if type(rawPetData.GeneratedPetData) == "table" then
            targetTbl = rawPetData.GeneratedPetData
        elseif type(rawPetData.PetData) == "table" then
            targetTbl = rawPetData.PetData
        elseif type(rawPetData.Data) == "table" then
            targetTbl = rawPetData.Data
        end
    end

    -- Extract details
    local petName = nil
    local petMutation = nil
    local petLevel = nil
    local petPassive = nil

    -- A. Extract Raw Pet Name / Species candidate
    -- Prioritize species key 'f', 'Species', 'PetType', 'Type' over nickname 'Name'/'PetName'
    local rawNameStr = nil
    local petReg = petRegistry or getPetRegistry()
    local petRegList = petReg and (petReg.Pets or petReg.PetData or (type(petReg) == "table" and petReg))

    -- Helper to verify if a candidate string matches an actual known Pet species in PetRegistry
    local function isKnownSpecies(str)
        if not str or not petRegList then return false end
        local cleanStr = cleanPetName(tostring(str)) or tostring(str)
        for speciesKey, _ in pairs(petRegList) do
            if tostring(speciesKey):lower() == cleanStr:lower() then
                return tostring(speciesKey)
            end
        end
        return false
    end

    if targetTbl then
        local match = isKnownSpecies(targetTbl.f) or isKnownSpecies(targetTbl.Species) or isKnownSpecies(targetTbl.PetType) or isKnownSpecies(targetTbl.Type) or isKnownSpecies(targetTbl.IncubatedEgg)
        if match then
            rawNameStr = match
        else
            rawNameStr = targetTbl.f or targetTbl.Species or targetTbl.PetType or targetTbl.Type or targetTbl.IncubatedEgg
        end
    end

    if not rawNameStr and rawPetData then
        local match = isKnownSpecies(rawPetData.f) or isKnownSpecies(rawPetData.Species) or isKnownSpecies(rawPetData.PetType) or isKnownSpecies(rawPetData.Type) or isKnownSpecies(rawPetData.IncubatedEgg)
        if match then
            rawNameStr = match
        else
            rawNameStr = rawPetData.f or rawPetData.Species or rawPetData.PetType or rawPetData.Type or rawPetData.IncubatedEgg
        end
    end

    if not rawNameStr and petObj then
        local match = isKnownSpecies(petObj:GetAttribute("f")) or isKnownSpecies(petObj:GetAttribute("Species")) or isKnownSpecies(petObj:GetAttribute("PetType")) or isKnownSpecies(petObj:GetAttribute("Type"))
        if match then
            rawNameStr = match
        else
            rawNameStr = petObj:GetAttribute("f") or petObj:GetAttribute("Species") or petObj:GetAttribute("PetType") or petObj:GetAttribute("Type")
        end
    end

    -- Fallback to Name/PetName only if no valid species field was populated
    if not rawNameStr or isKnownSpecies(rawNameStr) == false then
        if targetTbl and (targetTbl.PetName or targetTbl.Name or targetTbl.Pet) then
            local match = isKnownSpecies(targetTbl.PetName) or isKnownSpecies(targetTbl.Name) or isKnownSpecies(targetTbl.Pet)
            if match then rawNameStr = match end
        end
        if not rawNameStr and rawPetData and (rawPetData.PetName or rawPetData.Name or rawPetData.Pet) then
            local match = isKnownSpecies(rawPetData.PetName) or isKnownSpecies(rawPetData.Name) or isKnownSpecies(rawPetData.Pet)
            if match then rawNameStr = match end
        end
        if not rawNameStr and petObj and (petObj:GetAttribute("PetName") or petObj.Name) then
            local match = isKnownSpecies(petObj:GetAttribute("PetName")) or isKnownSpecies(petObj.Name)
            if match then rawNameStr = match end
        end
    end

    -- B. Extract Mutation with PetMutationRegistry / EnumToPetMutation decoder
    if targetTbl or rawPetData then
        local t = targetTbl or rawPetData
        local m = t.Mutation or t.PetMutation or t.Mutations or t.MutationType or t.PetMutations or t.MutationData or t.Variant or t.Skin or t.Trait or t.m or t.mType
        petMutation = formatPetMutation(m)

        if not petMutation and type(t) == "table" then
            for key, val in pairs(t) do
                if type(key) == "string" then
                    local lk = key:lower()
                    if lk:find("mut") or lk == "m" or lk:find("skin") or lk:find("variant") or lk:find("trait") then
                        local res = formatPetMutation(val)
                        if res then
                            petMutation = res
                            break
                        end
                    end
                end
            end
        end
    end

    if not petMutation and petObj then
        local mAttr = petObj:GetAttribute("m") or petObj:GetAttribute("Mutation") or petObj:GetAttribute("PetMutation") or petObj:GetAttribute("Mutations") or petObj:GetAttribute("PetMutations")
        petMutation = formatPetMutation(mAttr)

        if not petMutation then
            for attrName, attrVal in pairs(petObj:GetAttributes()) do
                local lName = attrName:lower()
                if lName:find("mut") or lName == "m" or lName:find("skin") or lName:find("variant") or lName:find("trait") then
                    local res = formatPetMutation(attrVal)
                    if res then
                        petMutation = res
                        break
                    end
                end
            end
        end
    end

    -- Check if mutation is prefixed in pet name
    local cleanedRawName = cleanPetName(rawNameStr) or rawNameStr or "Pet"
    local mutRegistry = getMutationRegistry()
    local regTable = mutRegistry and mutRegistry.PetMutationRegistry

    if regTable and cleanedRawName then
        for mutName, _ in pairs(regTable) do
            local pattern = "^" .. mutName:lower() .. "%s+"
            if cleanedRawName:lower():find(pattern) or cleanedRawName:lower() == mutName:lower() then
                if not petMutation or petMutation == "None" then
                    petMutation = mutName
                end
                cleanedRawName = cleanedRawName:gsub("^" .. mutName .. "%s*", ""):gsub("^" .. mutName:lower() .. "%s*", "")
                break
            end
        end
    end

    petName = cleanPetName(cleanedRawName) or cleanedRawName
    if not petName or petName == "" then petName = "Pet" end
    if not petMutation or petMutation == "" then petMutation = "None" end

    -- C. Extract Level / Age FIRST so it can be passed to Weight calculation algorithms
    local tLvl = targetTbl or rawPetData
    if tLvl then
        petLevel = tLvl.Level or tLvl.Lvl or tLvl.Age or tLvl.PetLevel or tLvl.PetAge or tLvl.b or tLvl.Stage or tLvl.ExpLevel
        if not petLevel and type(tLvl) == "table" then
            for k, v in pairs(tLvl) do
                local lk = tostring(k):lower()
                if (lk == "b" or lk:find("level") or lk:find("lvl") or lk == "age" or lk == "stage") and tonumber(v) then
                    petLevel = tonumber(v)
                    break
                end
            end
        end
    end

    if not petLevel and petObj then
        petLevel = petObj:GetAttribute("b") or petObj:GetAttribute("Level") or petObj:GetAttribute("Lvl") or petObj:GetAttribute("Age") or petObj:GetAttribute("PetLevel") or petObj:GetAttribute("PetAge")
    end

    if not petLevel and rawNameStr then
        local parsedAge = tostring(rawNameStr):match("%[Age%s*(%d+)%]") or tostring(rawNameStr):match("%[Lvl%s*(%d+)%]") or tostring(rawNameStr):match("%[Level%s*(%d+)%]")
        if parsedAge and tonumber(parsedAge) then
            petLevel = tonumber(parsedAge)
        end
    end

    local levelNum = tonumber(petLevel) or 1

    -- D. Extract & Compute Real Current Weight (with Level/Age scaling)
    -- 1. Scan for raw/base weight fields from tables or petObj attributes
    local function scanForWeight(tbl)
        if type(tbl) ~= "table" then return nil end
        local realW = tbl.RealWeight or tbl.realWeight or tbl.CalculatedWeight or tbl.calculatedWeight or tbl.FinalWeight or tbl.finalWeight or tbl.DisplayWeight or tbl.displayWeight or tbl.CurrentWeight or tbl.currentWeight or tbl.WeightKG or tbl.weightKG or tbl.weight_kg or tbl.PetWeight or tbl.petWeight
        if realW and tonumber(realW) then
            return tonumber(realW)
        end

        local bw = tbl.BaseWeight or tbl.baseWeight or tbl.base_weight
        local rawW = tbl.Weight or tbl.weight or tbl.KG or tbl.kg or tbl.Kg or tbl.w
        local baseVal = tonumber(bw) or tonumber(rawW)
        local wm = tbl.WeightMultiplier or tbl.weightMultiplier or tbl.WeightMult or tbl.weightMult or tbl.WeightScale or tbl.weightScale or tbl.WeightMod or tbl.weightMod or tbl.Multiplier or tbl.multiplier or tbl.Scale or tbl.scale

        if baseVal and wm and tonumber(wm) and tonumber(wm) ~= 1 then
            return baseVal * tonumber(wm)
        end
        if baseVal then return baseVal end

        for k, v in pairs(tbl) do
            local lk = tostring(k):lower()
            if (lk:find("realweight") or lk:find("calculatedweight") or lk:find("finalweight") or lk:find("petweight") or lk:find("weightkg") or lk == "weight" or lk == "kg" or lk == "w") then
                if tonumber(v) then return tonumber(v) end
            end
        end
        return nil
    end

    local rawExtractedW = scanForWeight(targetTbl) or scanForWeight(rawPetData)
    if not rawExtractedW and petObj then
        local wAttr = petObj:GetAttribute("Weight") or petObj:GetAttribute("WeightKG") or petObj:GetAttribute("KG") or petObj:GetAttribute("w") or petObj:GetAttribute("PetWeight") or petObj:GetAttribute("RealWeight")
        if wAttr and tonumber(wAttr) then rawExtractedW = tonumber(wAttr) end
    end
    if not rawExtractedW and rawNameStr then
        local parsedKG = tostring(rawNameStr):match("%[([%d%.]+)%s*[Kk][Gg]%]") or tostring(rawNameStr):match("%(([%d%.]+)%s*[Kk][Gg]%)") or tostring(rawNameStr):match("([%d%.]+)%s*[Kk][Gg]")
        if parsedKG and tonumber(parsedKG) then
            rawExtractedW = tonumber(parsedKG)
        end
    end

    -- 2. Construct unified pet data evaluation table with Level/Age AND Weight populated
    local evalTable = {}
    if type(rawPetData) == "table" then
        for k, v in pairs(rawPetData) do evalTable[k] = v end
    end
    if type(targetTbl) == "table" then
        for k, v in pairs(targetTbl) do evalTable[k] = v end
    end

    evalTable.Age = levelNum
    evalTable.Level = levelNum
    evalTable.Lvl = levelNum
    evalTable.b = levelNum
    evalTable.PetType = petName
    evalTable.Species = petName
    evalTable.f = petName
    evalTable.Mutation = petMutation
    evalTable.m = petMutation
    if rawExtractedW then
        evalTable.Weight = rawExtractedW
        evalTable.w = rawExtractedW
        evalTable.BaseWeight = rawExtractedW
        evalTable.PetWeight = rawExtractedW
        evalTable.WeightKG = rawExtractedW
    end

    -- 3. Calculate current real weight via Calculate_Weight module, petUtils, or scaling
    local petWeight = nil
    local calcMod = getCalculateWeightModule()
    if calcMod then
        pcall(function()
            local calcFn = (type(calcMod) == "function" and calcMod) or (type(calcMod) == "table" and (calcMod.Calculate_Weight or calcMod.CalculateWeight or calcMod.getWeight or calcMod.GetWeight))
            if type(calcFn) == "function" then
                -- Try passing pet UUID/seed (a0) and pet ID/type (a1), or evalTable
                local petSeed = targetTbl and (targetTbl.Seed or targetTbl.seed or targetTbl.UUID or targetTbl.uuid or targetTbl.b or targetTbl.a)
                local petTypeId = targetTbl and (targetTbl.PetType or targetTbl.Type or targetTbl.Id or targetTbl.id or targetTbl.f or petName)
                if petSeed and petTypeId then
                    local w, scale = calcFn(petSeed, petTypeId)
                    if w and tonumber(w) then petWeight = tonumber(w) end
                end
                if not petWeight then
                    local w, scale = calcFn(evalTable)
                    if w and tonumber(w) then petWeight = tonumber(w) end
                end
            end
        end)
    end

    if not petWeight and petUtils then
        pcall(function()
            local res = nil
            if type(petUtils.GetPetWeight) == "function" then
                res = petUtils:GetPetWeight(evalTable) or petUtils.GetPetWeight(evalTable) or petUtils.GetPetWeight(evalTable, levelNum)
            end
            if not res and type(petUtils.CalculatePetWeight) == "function" then
                res = petUtils:CalculatePetWeight(evalTable) or petUtils.CalculatePetWeight(evalTable) or petUtils.CalculatePetWeight(evalTable, levelNum)
            end
            if not res and type(petUtils.CalculateWeight) == "function" then
                res = petUtils:CalculateWeight(evalTable) or petUtils.CalculateWeight(evalTable) or petUtils.CalculateWeight(evalTable, levelNum)
            end
            if not res and type(petUtils.GetWeight) == "function" then
                res = petUtils:GetWeight(evalTable) or petUtils.GetWeight(evalTable) or petUtils.GetWeight(evalTable, levelNum)
            end
            if res and tonumber(res) then
                petWeight = tonumber(res)
            end
        end)
    end

    if not petWeight then
        petWeight = rawExtractedW
    end

    -- 4. Scale weight with PetRegistry species base weight and current Level/Age
    if petWeight and tonumber(petWeight) then
        local wNum = tonumber(petWeight)
        local baseScaled = false

        pcall(function()
            if petName and petRegistry then
                local petDef = (petRegistry.Pets and petRegistry.Pets[tostring(petName)])
                            or (petRegistry.PetData and petRegistry.PetData[tostring(petName)])
                            or (type(petRegistry) == "table" and petRegistry[tostring(petName)])
                if petDef then
                    local speciesBaseW = petDef.BaseWeight or petDef.baseWeight or petDef.Weight or petDef.weight or petDef.BaseKG or petDef.baseKG or petDef.WeightMultiplier or petDef.weightMultiplier
                    if speciesBaseW and tonumber(speciesBaseW) and tonumber(speciesBaseW) > 0 and wNum < tonumber(speciesBaseW) then
                        wNum = wNum * tonumber(speciesBaseW)
                        baseScaled = true
                    end
                end
            end
        end)

        -- Apply level/age growth scaling formula: BaseWeight * (1 + Level * 0.1)
        if levelNum and levelNum > 0 then
            pcall(function()
                if petUtils and type(petUtils.CalculateWeightForLevel) == "function" then
                    local calcW = petUtils.CalculateWeightForLevel(wNum, levelNum) or petUtils.CalculateWeightForLevel(evalTable, levelNum)
                    if calcW and tonumber(calcW) then wNum = tonumber(calcW) end
                elseif petUtils and type(petUtils.GetWeightAtLevel) == "function" then
                    local calcW = petUtils.GetWeightAtLevel(evalTable, levelNum) or petUtils.GetWeightAtLevel(wNum, levelNum)
                    if calcW and tonumber(calcW) then wNum = tonumber(calcW) end
                else
                    -- Exact game growth scaling formula: W = W_base * (1 + Level * 0.1)
                    wNum = wNum * (1 + levelNum * 0.1)
                end
            end)
        end

        petWeight = wNum
    end

    local weightStr = "?"
    if petWeight and tonumber(petWeight) then
        weightStr = string.format("%.2f", tonumber(petWeight))
    end

    -- D. Extract Level / Age
    local tLvl = targetTbl or rawPetData
    if tLvl then
        petLevel = tLvl.Level or tLvl.Lvl or tLvl.Age or tLvl.PetLevel or tLvl.PetAge or tLvl.b or tLvl.Stage or tLvl.ExpLevel
        if not petLevel and type(tLvl) == "table" then
            for k, v in pairs(tLvl) do
                local lk = tostring(k):lower()
                if (lk == "b" or lk:find("level") or lk:find("lvl") or lk == "age" or lk == "stage") and tonumber(v) then
                    petLevel = tonumber(v)
                    break
                end
            end
        end
    end

    if not petLevel and petObj then
        petLevel = petObj:GetAttribute("b") or petObj:GetAttribute("Level") or petObj:GetAttribute("Lvl") or petObj:GetAttribute("Age") or petObj:GetAttribute("PetLevel") or petObj:GetAttribute("PetAge")
    end

    if not petLevel and rawNameStr then
        local parsedAge = tostring(rawNameStr):match("%[Age%s*(%d+)%]") or tostring(rawNameStr):match("%[Lvl%s*(%d+)%]") or tostring(rawNameStr):match("%[Level%s*(%d+)%]")
        if parsedAge and tonumber(parsedAge) then
            petLevel = tonumber(parsedAge)
        end
    end

    local levelNum = tonumber(petLevel) or 1

    -- E. Extract Passive / Skill Name from Server Data & PetList
    local detectedPassives = {}

    local function addPassive(val)
        if not val or val == "" or val == true or val == false then return end
        if type(val) == "string" then
            local cleanV = val:gsub("^%s*(.-)%s*$", "%1")
            if cleanV:lower() ~= "none" and cleanV:lower() ~= "movement variation" and not table.find(detectedPassives, cleanV) then
                table.insert(detectedPassives, cleanV)
            end
        elseif type(val) == "table" then
            if val.Name and type(val.Name) == "string" then
                addPassive(val.Name)
            elseif val.Skill and type(val.Skill) == "string" then
                addPassive(val.Skill)
            elseif val.Passive and type(val.Passive) == "string" then
                addPassive(val.Passive)
            else
                for _, sub in pairs(val) do
                    addPassive(sub)
                end
            end
        end
    end

    -- 1. Check data tables (targetTbl & rawPetData)
    for _, tbl in ipairs({targetTbl, rawPetData}) do
        if type(tbl) == "table" then
            addPassive(tbl.Passives or tbl.Passive or tbl.Skill or tbl.SkillName or tbl.Ability or tbl.PetPassive or tbl.Skills or tbl.p)
            for k, v in pairs(tbl) do
                local lk = tostring(k):lower()
                if lk:find("passiv") or lk:find("skill") or lk:find("ability") or lk == "p" then
                    addPassive(v)
                end
            end
        end
    end

    -- 2. Check Instance attributes (petObj)
    if petObj then
        addPassive(petObj:GetAttribute("Passives") or petObj:GetAttribute("Passive") or petObj:GetAttribute("Skill") or petObj:GetAttribute("Ability") or petObj:GetAttribute("PetSkill") or petObj:GetAttribute("p"))
        for attrName, attrVal in pairs(petObj:GetAttributes()) do
            local lName = attrName:lower()
            if lName:find("passiv") or lName:find("skill") or lName:find("ability") or lName == "p" then
                addPassive(attrVal)
            end
        end
    end

    -- 3. Check Server PetList (RS.Data.PetRegistry.PetList) and PetRegistry definitions
    local petList = getPetList()
    local petDef = nil
    if petList and petName then
        petDef = petList[tostring(petName)]
              or petList[cleanPetName(petName)]
              or (petRegistry and ((petRegistry.Pets and petRegistry.Pets[tostring(petName)]) or (petRegistry.PetData and petRegistry.PetData[tostring(petName)])))
        if petDef then
            addPassive(petDef.Passives or petDef.Passive or petDef.Skill or petDef.SkillName or petDef.Ability or petDef.Skills)
        end
    end

    -- Also search case-insensitive in petList if not found yet
    if #detectedPassives == 0 and petList and petName then
        for pKey, pVal in pairs(petList) do
            local cleanK = tostring(pKey):lower()
            if cleanK == tostring(petName):lower() or cleanK == cleanPetName(petName):lower() then
                petDef = pVal
                if petDef then
                    addPassive(petDef.Passives or petDef.Passive or petDef.Skill or petDef.SkillName or petDef.Ability or petDef.Skills)
                end
                break
            end
        end
    end

    if #detectedPassives > 0 then
        petPassive = table.concat(detectedPassives, ", ")
    else
        petPassive = "None"
    end

    -- F. Extract & Evaluate Real-Time Server States & Passive Details directly from Server Data
    local formattedStatesStr = ""
    local serverDesc = nil
    local serverStates = nil
    local liveCooldownStr = nil

    -- 1. Scan for raw States table and active status from server replicator or petObj
    for _, tbl in ipairs({targetTbl, rawPetData}) do
        if type(tbl) == "table" then
            if not serverDesc and (tbl.Description or tbl.PassiveDescription or tbl.SkillDescription) then
                serverDesc = tbl.Description or tbl.PassiveDescription or tbl.SkillDescription
            end
            if not serverStates and tbl.States and type(tbl.States) == "table" then
                serverStates = tbl.States
            end
            if tbl.CooldownRemaining or tbl.NextAbilityTime or tbl.LastAbilityTime or tbl.CooldownExpiry or tbl.AbilityCooldown then
                local now = os.time()
                local expiry = tonumber(tbl.CooldownExpiry or tbl.NextAbilityTime)
                if expiry and expiry > now then
                    liveCooldownStr = string.format("%ds", math.ceil(expiry - now))
                elseif tbl.CooldownRemaining and tonumber(tbl.CooldownRemaining) > 0 then
                    liveCooldownStr = string.format("%ds", math.ceil(tonumber(tbl.CooldownRemaining)))
                end
            end
        end
    end

    if petObj then
        if not serverDesc then
            pcall(function()
                serverDesc = petObj:GetAttribute("Description") 
                          or petObj:GetAttribute("PassiveDescription") 
                          or petObj:GetAttribute("SkillDescription")
                          or petObj:GetAttribute("StatesDescription")
            end)
        end
        if not serverStates then
            pcall(function()
                local stAttr = petObj:GetAttribute("States")
                if type(stAttr) == "table" then
                    serverStates = stAttr
                end
            end)
        end
        if not liveCooldownStr then
            pcall(function()
                local cdAttr = petObj:GetAttribute("CooldownRemaining") or petObj:GetAttribute("Cooldown") or petObj:GetAttribute("NextAbilityTime")
                if cdAttr and tonumber(cdAttr) and tonumber(cdAttr) > 0 then
                    liveCooldownStr = string.format("%ds", math.ceil(tonumber(cdAttr)))
                end
            end)
        end
    end

    if petDef and petDef.Description and not serverDesc then
        serverDesc = petDef.Description
    end

    -- 2. Fetch server PetPassiveRegistry (ReplicatedStorage) definitions for all detected passives
    local passReg = getPetPassiveRegistry()
    local combinedStates = {}

    if petDef and petDef.States and type(petDef.States) == "table" then
        for k, v in pairs(petDef.States) do combinedStates[k] = v end
    end
    if targetTbl and targetTbl.States and type(targetTbl.States) == "table" then
        for k, v in pairs(targetTbl.States) do combinedStates[k] = v end
    end
    if rawPetData and rawPetData.States and type(rawPetData.States) == "table" then
        for k, v in pairs(rawPetData.States) do combinedStates[k] = v end
    end

    if passReg and #detectedPassives > 0 then
        for _, passName in ipairs(detectedPassives) do
            local passDef = passReg[tostring(passName)]
            if not passDef then
                for regKey, regVal in pairs(passReg) do
                    if type(regVal) == "table" and tostring(regKey):lower() == tostring(passName):lower() then
                        passDef = regVal
                        break
                    end
                end
            end

            if passDef and type(passDef) == "table" then
                if not serverDesc and passDef.Description then
                    serverDesc = passDef.Description
                end
                if passDef.States and type(passDef.States) == "table" then
                    for k, v in pairs(passDef.States) do
                        if not combinedStates[k] then
                            combinedStates[k] = v
                        end
                    end
                end
            end
        end
    end

    if next(combinedStates) ~= nil then
        serverStates = combinedStates
    end

    -- 3. Try server PetUtilities (ReplicatedStorage) calculation if available
    local serverUtilsCalc = nil
    if petUtils and petPassive and petPassive ~= "None" then
        pcall(function()
            if type(petUtils.GetPassiveStates) == "function" then
                serverUtilsCalc = petUtils:GetPassiveStates(evalTable) or petUtils.GetPassiveStates(evalTable)
            end
        end)
    end

    if serverUtilsCalc and type(serverUtilsCalc) == "table" then
        for k, v in pairs(serverUtilsCalc) do
            serverStates = serverStates or {}
            serverStates[k] = v
        end
    end

    -- 4. Evaluate & format live serverStates using formula: val = math.min(Base * (1 + PassiveBoost) + Weight * Scale, Max)
    if serverStates and type(serverStates) == "table" then
        local stateParts = {}
        local weightVal = tonumber(petWeight) or tonumber(levelNum) or 1
        local passiveBoost = getPassiveBoostForMutation(petMutation, targetTbl, rawPetData, petObj)

        for stateKey, stateDef in pairs(serverStates) do
            local val = nil
            local formatter = nil

            if type(stateDef) == "number" then
                val = stateDef
            elseif type(stateDef) == "table" then
                formatter = stateDef.Formatter

                -- Try server PetUtilities calculate method if available
                if petUtils then
                    pcall(function()
                        if type(petUtils.CalculateState) == "function" then
                            val = petUtils:CalculateState(stateDef, weightVal, levelNum, petMutation) or petUtils.CalculateState(stateDef, weightVal, levelNum, petMutation)
                        elseif type(petUtils.EvaluateState) == "function" then
                            val = petUtils:EvaluateState(stateDef, weightVal, levelNum, petMutation) or petUtils.EvaluateState(stateDef, weightVal, levelNum, petMutation)
                        end
                    end)
                end

                if not val then
                    local base = tonumber(stateDef.Base) or 0
                    local scale = tonumber(stateDef.Scale) or 0
                    local rawVal = (base * (1 + passiveBoost)) + (weightVal * scale)

                    if stateDef.Max ~= nil and tonumber(stateDef.Max) then
                        rawVal = math.min(rawVal, tonumber(stateDef.Max))
                    end
                    if stateDef.Min ~= nil and tonumber(stateDef.Min) then
                        rawVal = math.max(rawVal, tonumber(stateDef.Min))
                    end

                    val = rawVal
                end
            elseif type(stateDef) == "string" then
                table.insert(stateParts, string.format("%s: %s", tostring(stateKey), stateDef))
            end

            if val and type(val) == "number" then
                local formattedVal = nil
                local lKey = tostring(stateKey):lower()
                if formatter == "ColonTime" or lKey:find("cooldown") then
                    local totalSecs = math.max(0, math.floor(val))
                    local mins = math.floor(totalSecs / 60)
                    local secs = totalSecs % 60
                    formattedVal = mins > 0 and string.format("%dm %ds", mins, secs) or string.format("%ds", secs)
                elseif formatter == "Percentage" or lKey:find("chance") then
                    formattedVal = (math.abs(val - math.floor(val)) < 0.001) and string.format("%d%%", val) or string.format("%.2f%%", val)
                elseif lKey:find("multiplier") or lKey:find("mult") then
                    formattedVal = (math.abs(val - math.floor(val)) < 0.001) and string.format("%dx", val) or string.format("%.2fx", val)
                elseif math.abs(val - math.floor(val)) < 0.001 then
                    formattedVal = string.format("%d", math.floor(val))
                else
                    formattedVal = string.format("%.2f", val)
                end
                table.insert(stateParts, string.format("%s: %s", tostring(stateKey), formattedVal))
            end
        end

        if #stateParts > 0 then
            table.sort(stateParts)
            formattedStatesStr = table.concat(stateParts, " | ")
        end
    end

    if not formattedStatesStr or formattedStatesStr == "" then
        formattedStatesStr = "N/A"
    end

    local isComplete = (rawPetData ~= nil) and (weightStr ~= "?") and (petMutation ~= "None")

    return {
        Name = petName,
        Mutation = petMutation,
        WeightStr = weightStr,
        Level = levelNum,
        Passive = petPassive,
        ServerDesc = serverDesc,
        ServerStates = serverStates,
        FormattedStates = formattedStatesStr,
        LiveCooldown = liveCooldownStr,
        IsComplete = isComplete
    }
end



function MiscFunctions.UpdatePetESP()
    local guiContainer = getGuiContainer()
    if not guiContainer then return end

    local petsPhysical = workspace:FindFirstChild("PetsPhysical")
    if not petsPhysical then return end

    local playerData = getPlayerData()
    local replData = getReplicatedPetData()
    local petRegistry = getPetRegistry()
    local petUtils = getPetUtils()

    local currentFound = {}
    local myPlayerName = LocalPlayer.Name:lower()

    for _, petObj in ipairs(petsPhysical:GetChildren()) do
        local owner = petObj:GetAttribute("OWNER") or petObj:GetAttribute("Owner") or petObj:GetAttribute("OwnerName")
        local ownerStr = owner and tostring(owner):lower() or ""

        if ownerStr == "" or ownerStr == myPlayerName then
            local actualBasePart = petObj:IsA("BasePart") and petObj or petObj.PrimaryPart or petObj:FindFirstChildWhichIsA("BasePart", true)

            if actualBasePart then
                currentFound[petObj] = true

                -- Always inspect live details from server on every frame/cycle for real-time ESP updates
                local details = inspectPetObject(petObj, playerData, replData, petRegistry, petUtils)
                resolvedPetCache[petObj] = details

                local espGui = activePetEsp[petObj]
                if not espGui or not espGui.Parent then
                    espGui = Instance.new("BillboardGui")
                    espGui.Name = "GAG_PetESP_" .. tostring(petObj:GetDebugId())
                    espGui.AlwaysOnTop = true
                    espGui.Size = UDim2.new(0, 270, 0, 92)
                    espGui.StudsOffset = Vector3.new(0, 3.8, 0)
                    espGui.MaxDistance = 500

                    local bgFrame = Instance.new("Frame")
                    bgFrame.Name = "BG"
                    bgFrame.Size = UDim2.new(1, 0, 1, 0)
                    bgFrame.BackgroundColor3 = Color3.fromRGB(15, 18, 28)
                    bgFrame.BackgroundTransparency = 0.25
                    bgFrame.BorderSizePixel = 0
                    bgFrame.Parent = espGui

                    local corner = Instance.new("UICorner")
                    corner.CornerRadius = UDim.new(0, 8)
                    corner.Parent = bgFrame

                    local stroke = Instance.new("UIStroke")
                    stroke.Color = Color3.fromRGB(0, 220, 255)
                    stroke.Thickness = 1.5
                    stroke.Transparency = 0.2
                    stroke.Parent = bgFrame

                    local textLabel = Instance.new("TextLabel")
                    textLabel.Name = "ESPLabel"
                    textLabel.Size = UDim2.new(1, -12, 1, -10)
                    textLabel.Position = UDim2.new(0, 6, 0, 5)
                    textLabel.BackgroundTransparency = 1
                    textLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
                    textLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                    textLabel.TextStrokeTransparency = 0.3
                    textLabel.Font = Enum.Font.FredokaOne
                    textLabel.TextSize = 12
                    textLabel.TextYAlignment = Enum.TextYAlignment.Center
                    textLabel.Parent = bgFrame

                    espGui.Adornee = actualBasePart
                    espGui.Parent = guiContainer
                    activePetEsp[petObj] = espGui
                else
                    espGui.Adornee = actualBasePart
                    if espGui.Parent ~= guiContainer then
                        espGui.Parent = guiContainer
                    end
                end

                local label = espGui:FindFirstChild("ESPLabel", true)
                if label then
                    local statesLine = "✨ States: " .. tostring(details.FormattedStates or "N/A")
                    if details.LiveCooldown then
                        statesLine = statesLine .. string.format(" [%s]", details.LiveCooldown)
                    end

                    label.Text = string.format(
                        "🐾 %s\nMutasi: %s | %s KG | Lvl: %d\nSkill: %s\n%s",
                        tostring(details.Name),
                        tostring(details.Mutation),
                        tostring(details.WeightStr),
                        tonumber(details.Level) or 1,
                        tostring(details.Passive),
                        statesLine
                    )
                end
            end
        end
    end

    for obj, gui in pairs(activePetEsp) do
        if not currentFound[obj] or not obj.Parent then
            if gui and gui.Parent then
                pcall(function() gui:Destroy() end)
            end
            activePetEsp[obj] = nil
            resolvedPetCache[obj] = nil
        end
    end
end

--[[
    GAG 1 Hub - Miscellaneous Functions: Server Management
--]]

local TeleportService = game:GetService("TeleportService")
local HttpService     = game:GetService("HttpService")
local Players         = game:GetService("Players")
local LocalPlayer     = Players.LocalPlayer

 

-- Server Hop (Joins a server with available slots)
function MiscFunctions.ServerHop()
    local placeId = game.PlaceId
    local currentJobId = game.JobId

    local success, result = pcall(function()
        local raw = game:HttpGet(string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100", placeId))
        return HttpService:JSONDecode(raw)
    end)

    if success and result and result.data then
        for _, server in ipairs(result.data) do
            if server.id ~= currentJobId and server.playing < server.maxPlayers then
                TeleportService:TeleportToPlaceInstance(placeId, server.id, LocalPlayer)
                return true
            end
        end
    end

    TeleportService:Teleport(placeId, LocalPlayer)
    return true
end

-- Rejoin Current Server
function MiscFunctions.RejoinServer()
    if #Players:GetPlayers() <= 1 then
        LocalPlayer:Kick("\n[GAG 1 Hub] Rejoining server...")
        task.wait(0.5)
        TeleportService:Teleport(game.PlaceId, LocalPlayer)
    else
        TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
    end
end

--[[
    GAG 1 Hub - Discord Webhook Manager (Krexel Signature Violet Edition)
--]]

local HttpService = game:GetService("HttpService")

local httpRequest = (syn and syn.request)
                 or (http and http.request)
                 or request
                 or http_request

local KREXEL_VIOLET_DECIMAL = 11032055 -- #A855F7 (Krexel Signature Dark Violet)
local KREXEL_LOGO_URL = "https://i.imgur.com/8Q9Z4Qe.png"

function MiscFunctions.SendWebhook(url, content, title, color, fields, customPayload)
    if not url or url == "" then return false, "Empty Webhook URL" end
    if not httpRequest then return false, "Executor does not support HTTP requests" end

    local embedColor = color or KREXEL_VIOLET_DECIMAL
    if embedColor == 3447003 or embedColor == 65280 then
        embedColor = KREXEL_VIOLET_DECIMAL
    end

    local embed = {
        title = title or "🔮 Krexel Hub Notification",
        description = content or "",
        color = embedColor,
        fields = fields or {},
        author = {
            name = "GAG 1 Hub • Krexel Edition 🔮"
        },
        footer = {
            text = "Krexel Dark Violet Interface • Grow a Garden 1 Script"
        },
        timestamp = DateTime.now():ToIsoDate()
    }

    local payload = customPayload or {
        username = "Krexel Hub • Auto Hatch 🔮",
        embeds = { embed }
    }

    local success, response = pcall(function()
        return httpRequest({
            Url = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json"
            },
            Body = HttpService:JSONEncode(payload)
        })
    end)

    if success and response then
        local statusCode = response.StatusCode or response.Status
        if statusCode and (statusCode < 200 or statusCode >= 300) then
            return false, "HTTP " .. tostring(statusCode) .. " " .. tostring(response.Body or "")
        end
        return true, nil
    end

    return false, tostring(response or "Request failed")
end

function MiscFunctions.TestWebhook(url)
    return MiscFunctions.SendWebhook(
        url,
        "✨ **Krexel Hub Webhook Connection Successful!**\nGrow a Garden 1 Auto Hatch script is connected and ready.",
        "🔮 Krexel Hub • Webhook Test Success",
        KREXEL_VIOLET_DECIMAL,
        {
            { name = "⚡ Status", value = "**Connected**", inline = true },
            { name = "🔮 Theme", value = "**Krexel Signature Violet (#A855F7)**", inline = true }
        }
    )
end

_G.GAG_SendWebhook = MiscFunctions.SendWebhook
_G.GAG_MiscFunctions = MiscFunctions
return MiscFunctions
end)()

