pcall(function() local _hatchTab = (function()
--[[
    GAG 1 Hub - Hatching Tab Layout (Custom Layout Edition)
    Structure:
    1. Live Hatch Status (Paling Atas)
    2. Egg Configuration (Select Egg from Backpack, Position, Place Amount, Place Egg Now)
    3. Hatch & Keep Filter Configuration (Select Egg Type -> Dynamic Target Pet List based on full data & Keep Weight)
    4. Sell Pet Configuration (Select Egg Type -> Dynamic Pet List to Sell, Min/Max KG, Cycle vs Inventory)
    5. Bronto Mode Configuration (Target Pet & Min KG Bronto Mode)
--]]

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

return function(HatchTab, Automation, EggsPetsData, MainFunctions, HatchFunctions, InventoryFunctions, MiscFunctions, Fluent)



    ----------------------------------------------------------------------------
    -- 1. LIVE HATCH STATISTICS & TRACKER (PALING ATAS)
    ----------------------------------------------------------------------------
    HatchTab:AddParagraph({
        Title = "ℹ️ Live Hatch Tracker Info",
        Content = "Displays real-time automated garden cycle status, active Pet Inventory capacity (X/210), total eggs opened, elapsed runtime, equipped teams, and placed garden eggs summary."
    })

    local masterToggle = HatchTab:AddToggle("AutoHatchMasterToggle", {
        Title = "Enable Master Auto Hatch Loop",
        Description = "Master toggle for automatic hatching & team cycling workflow",
        Default = Automation.States.AutoHatch or false,
        Callback = function(state)
            Automation.ToggleTask("AutoHatch", state, function()
                HatchFunctions.RunMasterAutoHatchLoop(Automation, EggsPetsData)
            end)
        end
    })
    HatchFunctions.AutoHatchToggle = masterToggle

    local StatsParagraph = HatchTab:AddParagraph({
        Title = "Hatch Tracker Analytics",
        Content = HatchFunctions.GetFormattedStats(Automation)
    })

    -- Connect UI update callback
    HatchFunctions.UIUpdateCallback = function()
        if StatsParagraph and typeof(StatsParagraph.SetDesc) == "function" then
            pcall(function()
                StatsParagraph:SetDesc(HatchFunctions.GetFormattedStats(Automation))
            end)
        end
    end

    -- Periodically update status text (team selection & live auto hatch status)
    task.spawn(function()
        while task.wait(1) do
            if StatsParagraph and typeof(StatsParagraph.SetDesc) == "function" then
                pcall(function()
                    StatsParagraph:SetDesc(HatchFunctions.GetFormattedStats(Automation))
                end)
            end
        end
    end)

    HatchTab:AddButton({
        Title = "Reset Hatch Statistics Counter",
        Description = "Clears hatch count and rarity tracker back to zero",
        Callback = function()
            HatchFunctions.ResetStats()
            if Fluent and typeof(Fluent.Notify) == "function" then
                Fluent:Notify({ Title = "Stats Reset", Content = "Hatch counter reset to zero!", Duration = 3 })
            end
        end
    })

    ----------------------------------------------------------------------------
    -- 2. EGG CONFIGURATION (KONFIGURASI EGG)
    ----------------------------------------------------------------------------
    HatchTab:AddSection("Egg Configuration")

    HatchTab:AddParagraph({
        Title = "ℹ️ Egg Placement Info",
        Content = "Select which egg type to deploy from your Backpack. Choosing an egg automatically applies recommended Hatch, Sell, and Bronto presets."
    })

    -- Forward references for Dynamic Presets & Dropdown sync
    local EggDropdown = nil
    local HatchFilterEggDropdown = nil
    local HatchTargetPetDropdown = nil
    local SellFilterEggDropdown = nil
    local SellTargetPetDropdown = nil
    local SellWeightValueInput = nil
    local SellWeightConditionDropdown = nil
    local SellAgeValueInput = nil
    local SellAgeConditionDropdown = nil
    local AdvSellFilterEggDropdown = nil
    local AdvSellTargetPetDropdown = nil
    local AdvSellMinKGInput = nil
    local BrontoModeTypeDropdown = nil
    local BrontoFilterEggDropdown = nil
    local BrontoPetDropdown = nil
    local BrontoMinKGInput = nil
    local BrontoWeightConditionDropdown = nil

    local function getBackpackEggs()
        local player = LocalPlayer or Players.LocalPlayer
        if not player then return {}, {} end

        local backpack = player:FindFirstChildOfClass("Backpack") or player:FindFirstChild("Backpack")
        local character = player.Character

        local eggMap = {}

        local function scanContainer(container)
            if not container then return end
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") then
                    local attrH = tool:GetAttribute("h")
                    local attrUses = tool:GetAttribute("LocalUses") or tool:GetAttribute("e")
                    local name = tool.Name

                    local baseName = nil
                    local count = 0

                    if attrH and type(attrH) == "string" and attrH ~= "" then
                        baseName = attrH
                        count = tonumber(attrUses) or 1
                    else
                        local parsedName, parsedCount = name:match("^(.-)%s*x(%d+)$")
                        if parsedName and parsedCount then
                            baseName = parsedName
                            count = tonumber(parsedCount) or 1
                        elseif name:find("Egg") then
                            baseName = name
                            count = 1
                        end
                    end

                    if baseName and (baseName:find("Egg") or (attrH and tostring(attrH):find("Egg"))) then
                        eggMap[baseName] = (eggMap[baseName] or 0) + count
                    end
                end
            end
        end

        scanContainer(backpack)
        scanContainer(character)

        local options = {}
        for eggName, count in pairs(eggMap) do
            table.insert(options, string.format("%s (x%d)", eggName, count))
        end

        -- Sort options A-Z
        table.sort(options)
        return options, eggMap
    end

    local function arrayToDict(arr)
        local dict = {}
        if type(arr) == "table" then
            for _, v in ipairs(arr) do
                dict[v] = true
            end
        end
        return dict
    end

    ----------------------------------------------------------------------------
    -- COMMON EGG & PET REPOSITORY DATA & HELPERS
    ----------------------------------------------------------------------------
    local registeredEggNames = {}
    if EggsPetsData and EggsPetsData.Eggs then
        for _, egg in ipairs(EggsPetsData.Eggs) do
            table.insert(registeredEggNames, egg.Name)
        end
    end
    if #registeredEggNames == 0 then
        registeredEggNames = { "Common Egg", "Uncommon Egg", "Rare Egg", "Legendary Egg", "Mythical Egg", "Bug Egg", "Jungle Egg", "Night Egg", "Common Summer Egg", "Rare Summer Egg", "Paradise Egg", "Fall Egg", "Gem Egg", "Zen Egg", "Hive Egg", "Coastal Egg" }
    end

    table.sort(registeredEggNames)

    local function getPetsForEgg(eggFilterName)
        local petsList = {}
        local petNameSet = {}
        if not EggsPetsData or not EggsPetsData.Pets then return petsList end
        if not eggFilterName or eggFilterName == "" then return petsList end

        local cleanFilterName = tostring(eggFilterName):match("^(.-)%s*%(") or tostring(eggFilterName)
        cleanFilterName = cleanFilterName:gsub("^%s*(.-)%s*$", "%1")

        if cleanFilterName == "" then
            return petsList
        else
            local targetLower = cleanFilterName:lower()
            local targetBase = targetLower:gsub("%s*egg$", "")
            
            for _, pet in ipairs(EggsPetsData.Pets) do
                local petEggLower = pet.Egg:lower()
                local petEggBase = petEggLower:gsub("%s*egg$", "")

                if petEggLower == targetLower or petEggBase == targetBase then
                    if not petNameSet[pet.Name] then
                        petNameSet[pet.Name] = true
                        table.insert(petsList, pet.Name)
                    end
                end
            end
        end

        table.sort(petsList)
        return petsList
    end

    local filterEggOptions = {}
    for _, name in ipairs(registeredEggNames) do
        table.insert(filterEggOptions, name)
    end

    local RarityRank = {
        Common = 1,
        Uncommon = 2,
        Rare = 3,
        Legendary = 4,
        Mythical = 5,
        Divine = 6,
        Prismatic = 7,
        Secret = 7
    }

    local function getPetRarityRank(petName)
        local r = (EggsPetsData and typeof(EggsPetsData.GetPetRarity) == "function" and EggsPetsData.GetPetRarity(petName)) or "Common"
        return RarityRank[r] or 1, r
    end

    local function applyEggPreset(eggNameInput, notifyUser)
        if not eggNameInput or eggNameInput == "" or eggNameInput == "No Eggs in Backpack" then return end

        local cleanName = tostring(eggNameInput):match("^(.-)%s*%(") or tostring(eggNameInput):match("^(.-)%s*x%d+") or tostring(eggNameInput)
        cleanName = cleanName:gsub("^%s*(.-)%s*$", "%1")
        if cleanName == "" then return end

        -- Match registered egg name
        local matchedEggName = nil
        for _, regName in ipairs(registeredEggNames) do
            if regName:lower() == cleanName:lower() then
                matchedEggName = regName
                break
            end
        end
        if not matchedEggName then
            for _, regName in ipairs(registeredEggNames) do
                if regName:lower():find(cleanName:lower(), 1, true) or cleanName:lower():find(regName:lower(), 1, true) then
                    matchedEggName = regName
                    break
                end
            end
        end
        matchedEggName = matchedEggName or cleanName

        -- Retrieve all pets in this egg
        local eggPets = getPetsForEgg(matchedEggName)
        if #eggPets == 0 then
            eggPets = getPetsForEgg(cleanName)
        end

        -- Calculate pet rarities & top rarity tier
        local petRarityData = {}
        local maxRank = -1
        local minRank = 999
        for _, petName in ipairs(eggPets) do
            local rank, rarityName = getPetRarityRank(petName)
            local petObj = (EggsPetsData and typeof(EggsPetsData.GetPetByName) == "function" and EggsPetsData.GetPetByName(petName)) or nil
            local mult = (petObj and tonumber(petObj.Multiplier)) or 1.0
            table.insert(petRarityData, {
                Name = petName,
                Rank = rank,
                Rarity = rarityName,
                Multiplier = mult
            })
            if rank > maxRank then maxRank = rank end
            if rank < minRank then minRank = rank end
        end

        -- Identify best pets (Divine / highest rarity in egg) and lower pets (to sell)
        local bestPets = {}
        local lowerPets = {}
        local hatchTargetPets = {}

        for _, item in ipairs(petRarityData) do
            table.insert(hatchTargetPets, item.Name)
            if maxRank > minRank then
                if item.Rank == maxRank then -- Pet dengan rarity tertinggi/paling bagus dari egg tersebut
                    table.insert(bestPets, item.Name)
                else
                    table.insert(lowerPets, item.Name)
                end
            else
                -- All pets in egg share the same rarity (e.g. Common Egg)
                local highestMult = -1
                for _, p in ipairs(petRarityData) do
                    if p.Multiplier > highestMult then highestMult = p.Multiplier end
                end
                if item.Multiplier == highestMult and #eggPets > 1 then
                    table.insert(bestPets, item.Name)
                else
                    table.insert(lowerPets, item.Name)
                end
            end
        end

        if #lowerPets == 0 and #eggPets > 1 then
            lowerPets = { eggPets[1] }
        end
        if #bestPets == 0 and #eggPets > 0 then
            bestPets = { eggPets[#eggPets] }
        end

        ----------------------------------------------------
        -- 1. HATCH CONFIGURATION PRESET
        -- Otomatis pilih egg yang sama dan isi seluruh pet di egg tersebut
        ----------------------------------------------------
        if HatchFilterEggDropdown and typeof(HatchFilterEggDropdown.SetValue) == "function" then
            HatchFilterEggDropdown:SetValue(matchedEggName)
        end
        if HatchTargetPetDropdown then
            if typeof(HatchTargetPetDropdown.SetValues) == "function" then
                HatchTargetPetDropdown:SetValues(eggPets)
            end
            local hatchDict = arrayToDict(hatchTargetPets)
            if typeof(HatchTargetPetDropdown.SetValue) == "function" then
                HatchTargetPetDropdown:SetValue(hatchDict)
            end
        end
        Automation.Settings.HatchTargetPets = hatchTargetPets

        ----------------------------------------------------
        -- 2. SELL CONFIGURATION PRESET
        -- Otomatis pilih egg yang sama dan pet di egg tersebut kecuali rarity paling bagus (misal Divine/Mythic)
        -- Default weight below 6, default age below 3
        ----------------------------------------------------
        if SellFilterEggDropdown and typeof(SellFilterEggDropdown.SetValue) == "function" then
            SellFilterEggDropdown:SetValue(matchedEggName)
        end
        if SellTargetPetDropdown then
            if typeof(SellTargetPetDropdown.SetValues) == "function" then
                SellTargetPetDropdown:SetValues(eggPets)
            end
            local sellDict = arrayToDict(lowerPets)
            if typeof(SellTargetPetDropdown.SetValue) == "function" then
                SellTargetPetDropdown:SetValue(sellDict)
            end
        end
        Automation.Settings.SellTargetPets = lowerPets

        -- Default Sell Weight: Below 6.0
        Automation.Settings.SellWeightCondition = "Below"
        Automation.Settings.SellWeightValue = 6.0
        if SellWeightConditionDropdown and typeof(SellWeightConditionDropdown.SetValue) == "function" then
            SellWeightConditionDropdown:SetValue("Below")
        end
        if SellWeightValueInput and typeof(SellWeightValueInput.SetValue) == "function" then
            SellWeightValueInput:SetValue("6")
        end

        -- Default Sell Age: Below 3
        Automation.Settings.SellAgeCondition = "Below"
        Automation.Settings.SellAgeValue = 3
        if SellAgeConditionDropdown and typeof(SellAgeConditionDropdown.SetValue) == "function" then
            SellAgeConditionDropdown:SetValue("Below")
        end
        if SellAgeValueInput and typeof(SellAgeValueInput.SetValue) == "function" then
            SellAgeValueInput:SetValue("3")
        end

        ----------------------------------------------------
        -- 3. ADVANCED SELL CONFIGURATION PRESET
        -- Advanced sell biarkan kosong
        ----------------------------------------------------
        if AdvSellFilterEggDropdown and typeof(AdvSellFilterEggDropdown.SetValue) == "function" then
            AdvSellFilterEggDropdown:SetValue(matchedEggName)
        end
        if AdvSellTargetPetDropdown then
            if typeof(AdvSellTargetPetDropdown.SetValues) == "function" then
                AdvSellTargetPetDropdown:SetValues(eggPets)
            end
            if typeof(AdvSellTargetPetDropdown.SetValue) == "function" then
                AdvSellTargetPetDropdown:SetValue({})
            end
        end
        Automation.Settings.AdvSellTargetPets = {}
        Automation.Settings.AdvTargetPets = {}

        ----------------------------------------------------
        -- 4. BRONTO MODE PRESET
        -- Langsung pake 'Weight + Selected Pet', pilih pet divine/best, default weight above 4
        ----------------------------------------------------
        Automation.Settings.BrontoModeType = "Weight + Selected Pet"
        if BrontoModeTypeDropdown and typeof(BrontoModeTypeDropdown.SetValue) == "function" then
            BrontoModeTypeDropdown:SetValue("Weight + Selected Pet")
        end

        if BrontoFilterEggDropdown and typeof(BrontoFilterEggDropdown.SetValue) == "function" then
            BrontoFilterEggDropdown:SetValue(matchedEggName)
        end
        if BrontoPetDropdown then
            if typeof(BrontoPetDropdown.SetValues) == "function" then
                BrontoPetDropdown:SetValues(eggPets)
            end
            local brontoDict = arrayToDict(bestPets)
            if typeof(BrontoPetDropdown.SetValue) == "function" then
                BrontoPetDropdown:SetValue(brontoDict)
            end
        end
        Automation.Settings.BrontoTargetPets = bestPets
        Automation.Settings.BrontoPets = bestPets

        -- Default Bronto Weight: Above 4.0
        Automation.Settings.BrontoWeightCondition = "Above"
        Automation.Settings.BrontoMinKG = 4.0
        if BrontoWeightConditionDropdown and typeof(BrontoWeightConditionDropdown.SetValue) == "function" then
            BrontoWeightConditionDropdown:SetValue("Above")
        end
        if BrontoMinKGInput and typeof(BrontoMinKGInput.SetValue) == "function" then
            BrontoMinKGInput:SetValue("4")
        end

        if Automation and typeof(Automation.SaveConfig) == "function" then
            Automation.SaveConfig()
        end

        if notifyUser and Fluent and typeof(Fluent.Notify) == "function" then
            Fluent:Notify({
                Title = "Auto Preset Applied",
                Content = string.format("Configured Hatch, Sell & Bronto presets for %s!", matchedEggName),
                Duration = 4
            })
        end
    end

    local eggOptions, eggMap = getBackpackEggs()
    if #eggOptions == 0 then
        eggOptions = { "No Eggs in Backpack" }
    end

    local savedEggDefault = eggOptions[1] or "No Eggs in Backpack"
    if Automation.Settings.SelectedEgg or Automation.Settings.PlaceEggName then
        local searchName = Automation.Settings.SelectedEgg or Automation.Settings.PlaceEggName
        for _, opt in ipairs(eggOptions) do
            if opt:lower():find(searchName:lower(), 1, true) then
                savedEggDefault = opt
                break
            end
        end
    end

    EggDropdown = HatchTab:AddDropdown("EggSelectDropdown", {
        Title = "Select Egg Type",
        Description = "Shows only eggs available in your Backpack (Applies auto preset)",
        Values = eggOptions,
        Default = savedEggDefault,
        Callback = function(val)
            if type(val) == "string" then
                local rawName = val:match("^(.-)%s*%(") or val:match("^(.-)%s*x%d+") or val
                rawName = rawName:gsub("^%s*(.-)%s*$", "%1")
                Automation.Settings.SelectedEgg = rawName
                Automation.Settings.PlaceEggName = rawName
                if Automation and typeof(Automation.SaveConfig) == "function" then Automation.SaveConfig() end

                -- Trigger Automatic Preset across Hatch, Sell & Bronto
                applyEggPreset(rawName, true)
            end
        end
    })

    if eggOptions[1] and eggOptions[1] ~= "No Eggs in Backpack" and not Automation.Settings.SelectedEgg then
        local rawName = eggOptions[1]:match("^(.-)%s*%(") or eggOptions[1]
        rawName = rawName:gsub("^%s*(.-)%s*$", "%1")
        Automation.Settings.SelectedEgg = rawName
        Automation.Settings.PlaceEggName = rawName
    end

    HatchTab:AddButton({
        Title = "Refresh Backpack Eggs List",
        Description = "Updates dropdown with current Backpack eggs",
        Callback = function()
            local updatedOptions, _ = getBackpackEggs()
            if #updatedOptions == 0 then
                updatedOptions = { "No Eggs in Backpack" }
            end
            if EggDropdown and typeof(EggDropdown.SetValues) == "function" then
                EggDropdown:SetValues(updatedOptions)
                EggDropdown:SetValue(updatedOptions[1])
            end
            if updatedOptions[1] and updatedOptions[1] ~= "No Eggs in Backpack" then
                local rawName = updatedOptions[1]:match("^(.-)%s*%(") or updatedOptions[1]
                rawName = rawName:gsub("^%s*(.-)%s*$", "%1")
                Automation.Settings.SelectedEgg = rawName
                Automation.Settings.PlaceEggName = rawName
                applyEggPreset(rawName, true)
            end
            if Fluent and typeof(Fluent.Notify) == "function" then
                local count = (#updatedOptions == 1 and updatedOptions[1] == "No Eggs in Backpack") and 0 or #updatedOptions
                Fluent:Notify({ Title = "Backpack Scanner", Content = string.format("Found %d egg types in Backpack!", count), Duration = 3 })
            end
        end
    })

    HatchTab:AddInput("EggPlaceAmountInput", {
        Title = "Target Garden Eggs (Place Amount)",
        Default = tostring(Automation.Settings.EggPlaceAmount or Automation.Settings.PlaceEggAmount or 13),
        Placeholder = "Target jumlah egg di garden (misal 13)...",
        Numeric = true,
        Callback = function(val)
            local amt = tonumber(val) or 13
            Automation.Settings.EggPlaceAmount = amt
            Automation.Settings.PlaceEggAmount = amt
            if Automation and typeof(Automation.SaveConfig) == "function" then Automation.SaveConfig() end
        end
    })

    HatchTab:AddButton({
        Title = "Place Selected Eggs Now",
        Description = "Menempatkan telur ke garden hingga mencapai target jumlah yang ditentukan",
        Callback = function()
            local eggName = Automation.Settings.SelectedEgg or Automation.Settings.PlaceEggName or "Common Egg"
            local amt = Automation.Settings.EggPlaceAmount or Automation.Settings.PlaceEggAmount or 13
            local ok, reason = HatchFunctions.PlaceEgg(eggName, amt, Automation)
            
            local cur = HatchFunctions.GetCurrentPlacedEggCount()
            local maxS = HatchFunctions.GetMaxEggSlots(Automation)

            if Fluent and typeof(Fluent.Notify) == "function" then
                if reason == "TargetAlreadyReached" or reason == "TargetReached" then
                    Fluent:Notify({ Title = "Egg Placer", Content = string.format("Garden sudah mencapai target (%d/%d egg)!", cur, amt), Duration = 3 })
                elseif reason == "NoEggTool" then
                    Fluent:Notify({ Title = "Egg Placer", Content = string.format("Egg di backpack habis! Total di garden: %d egg.", cur), Duration = 3 })
                elseif reason == "MaxSlotsReached" then
                    Fluent:Notify({ Title = "Egg Placer", Content = string.format("Kapasitas egg penuh (%d/%d)! Stop placing.", cur, maxS), Duration = 3 })
                else
                    Fluent:Notify({ Title = "Egg Placer", Content = string.format("Berhasil place! Total di garden saat ini: %d egg.", cur), Duration = 3 })
                end
            end
        end
    })

    ----------------------------------------------------------------------------
    -- 3. HATCH & KEEP CONFIGURATION (KONFIGURASI HATCH & KEEP)
    ----------------------------------------------------------------------------
    HatchTab:AddSection("Hatch & Keep Filters")

    HatchTab:AddParagraph({
        Title = "ℹ️ Hatch & Keep Filter Info",
        Content = "Specify target pets to keep when hatching. Unmatched pets will be automatically protected or sold depending on your configured sell filter mode."
    })

    HatchTab:AddButton({
        Title = "Hatch All Ready Eggs Now",
        Description = "Instantly triggers HatchPet remote on ALL ready eggs on your farm (ignores all filters & Bronto)",
        Callback = function()
            local hatchTeam = Automation.Settings.Teams and Automation.Settings.Teams.Hatch
            if hatchTeam and type(hatchTeam) == "table" and #hatchTeam > 0 then
                HatchFunctions.EquipTeam(hatchTeam)
                task.wait(0.5)
            end
            local ok = HatchFunctions.HatchEggStep(
                Automation.Settings.SelectedEgg,
                99,
                EggsPetsData,
                Automation,
                false, -- enforceHatchFilter = false
                false  -- overrideBrontoMode = false (Normal Hatch All)
            )
            if Fluent and typeof(Fluent.Notify) == "function" then
                if ok then
                    Fluent:Notify({ Title = "Hatch All Eggs", Content = "Hatched all ready eggs on farm!", Duration = 3 })
                else
                    Fluent:Notify({ Title = "Hatch All Eggs", Content = "No ready eggs found on farm.", Duration = 3 })
                end
            end
        end
    })

    HatchTab:AddButton({
        Title = "Hatch Filtered Eggs Now",
        Description = "Only hatches ready eggs that match your Target Hatch Pets Filter (Ignores Bronto Mode)",
        Callback = function()
            local hatchTeam = Automation.Settings.Teams and Automation.Settings.Teams.Hatch
            if hatchTeam and type(hatchTeam) == "table" and #hatchTeam > 0 then
                HatchFunctions.EquipTeam(hatchTeam)
                task.wait(0.5)
            end
            local ok = HatchFunctions.HatchEggStep(
                Automation.Settings.SelectedEgg,
                99,
                EggsPetsData,
                Automation,
                true,  -- enforceHatchFilter = true
                false  -- overrideBrontoMode = false (Normal Hatch Filter)
            )
            if Fluent and typeof(Fluent.Notify) == "function" then
                if ok then
                    Fluent:Notify({ Title = "Hatch Filtered Eggs", Content = "Hatched matching filtered eggs on farm!", Duration = 3 })
                else
                    Fluent:Notify({ Title = "Hatch Filtered Eggs", Content = "No matching filtered eggs found on farm.", Duration = 3 })
                end
            end
        end
    })

    local initialHatchPetValues = getPetsForEgg(Automation.Settings.SelectedEgg or savedEggDefault)

    HatchFilterEggDropdown = HatchTab:AddDropdown("HatchFilterEggTypeDropdown", {
        Title = "Select Egg Type for Hatch Filter",
        Description = "Filter pet choices below based on selected egg pool (A-Z)",
        Values = filterEggOptions,
        Default = Automation.Settings.SelectedEgg or savedEggDefault,
        Callback = function(val)
            local currentEggFilter = val
            local newPetValues = getPetsForEgg(currentEggFilter)
            if HatchTargetPetDropdown and typeof(HatchTargetPetDropdown.SetValues) == "function" then
                HatchTargetPetDropdown:SetValues(newPetValues)
            end
        end
    })

    HatchTargetPetDropdown = HatchTab:AddDropdown("HatchTargetPetsDropdown", {
        Title = "Target Hatch Pets Filter",
        Description = "Select specific pet names you want to hatch/keep",
        Values = initialHatchPetValues,
        Multi = true,
        Default = arrayToDict(Automation.Settings.HatchTargetPets or initialHatchPetValues)
    })

    HatchTargetPetDropdown:OnChanged(function(Value)
        local rawTargetPets = {}
        for petKey, isSelected in pairs(Value) do
            if isSelected then
                local rawName = petKey:match("^(.-)%s*%(") or petKey
                table.insert(rawTargetPets, rawName)
            end
        end
        Automation.Settings.HatchTargetPets = rawTargetPets
        if Automation and typeof(Automation.SaveConfig) == "function" then Automation.SaveConfig() end
    end)


    ----------------------------------------------------------------------------
    -- 4. SELL PET CONFIGURATION (KONFIGURASI SELL PET)
    ----------------------------------------------------------------------------
    HatchTab:AddSection("Sell Pet Configuration")

    HatchTab:AddParagraph({
        Title = "ℹ️ Standard Sell Rules Info",
        Content = "Standard Sell filters unfavorited target pets matching your specific Weight (KG) and Age thresholds."
    })

    local initialSellPetValues = getPetsForEgg(Automation.Settings.SelectedEgg or savedEggDefault)

    SellFilterEggDropdown = HatchTab:AddDropdown("SellFilterEggTypeDropdown", {
        Title = "Select Egg Type for Sell Filter",
        Description = "Filter sellable pets below based on selected egg pool (A-Z)",
        Values = filterEggOptions,
        Default = Automation.Settings.SelectedEgg or savedEggDefault,
        Callback = function(val)
            local currentEggFilter = val
            local newPetValues = getPetsForEgg(currentEggFilter)
            if SellTargetPetDropdown and typeof(SellTargetPetDropdown.SetValues) == "function" then
                SellTargetPetDropdown:SetValues(newPetValues)
            end
        end
    })

