    })

    local function getBackpackPetNames()
        if HatchFunctions and typeof(HatchFunctions.GetFormattedBackpackPets) == "function" then
            local pets = HatchFunctions.GetFormattedBackpackPets()
            if pets and #pets > 0 then return pets end
        end
        return {}
    end

    local backpackPetOptions = getBackpackPetNames()
    if #backpackPetOptions == 0 then
        backpackPetOptions = { "No Pets in Backpack" }
    end

    local function listToDict(list)
        local d = {}
        if type(list) == "table" then
            for _, item in ipairs(list) do
                d[item] = true
            end
        end
        return d
    end

    local function createTeamDropdown(key, title, desc)
        local dropdown = nil
        dropdown = HatchTab:AddDropdown("Team_" .. key .. "_Dropdown", {
            Title = title,
            Description = desc .. " (Maksimal 8 Pet dari Backpack)",
            Values = backpackPetOptions,
            Multi = true,
            Default = listToDict(Automation.Settings.Teams[key]),
            Callback = function(val)
                local selectedList = {}
                local count = 0
                for petName, selected in pairs(val or {}) do
                    if selected and petName ~= "No Pets in Backpack" then
                        count = count + 1
                        if count <= 8 then
                            table.insert(selectedList, petName)
                        else
                            val[petName] = false
                        end
                    end
                end
                if count > 8 then
                    pcall(function() dropdown:SetValue(val) end)
                    if Fluent and typeof(Fluent.Notify) == "function" then
                        Fluent:Notify({
                            Title = "Tim Pet Limit",
                            Content = "Maksimal 8 pet untuk " .. title .. "!",
                            Duration = 3
                        })
                    end
                end
                Automation.Settings.Teams[key] = selectedList
                if Automation and typeof(Automation.SaveConfig) == "function" then Automation.SaveConfig() end
            end
        })
        return dropdown
    end

    local reduceTeamDropdown = createTeamDropdown("Reduce", "Tim Reduce", "Pilih pet dari backpack")
    local hatchTeamDropdown  = createTeamDropdown("Hatch", "Tim Hatch", "Pilih pet dari backpack")
    local sellTeamDropdown   = createTeamDropdown("Sell", "Tim Sell", "Pilih pet dari backpack")
    local brontoTeamDropdown = createTeamDropdown("Bronto", "Tim Bronto", "Pilih pet dari backpack")

    HatchTab:AddButton({
        Title = "Refresh Backpack Pets for Teams",
        Description = "Memperbarui daftar pilihan pet di seluruh tim dari Backpack",
        Callback = function()
            local updatedPets = getBackpackPetNames()
            if #updatedPets == 0 then
                updatedPets = { "No Pets in Backpack" }
            end
            local dropdowns = { reduceTeamDropdown, hatchTeamDropdown, sellTeamDropdown, brontoTeamDropdown }
            for _, dd in ipairs(dropdowns) do
                if dd and typeof(dd.SetValues) == "function" then
                    dd:SetValues(updatedPets)
                end
            end
            if Fluent and typeof(Fluent.Notify) == "function" then
                local count = (#updatedPets == 1 and updatedPets[1] == "No Pets in Backpack") and 0 or #updatedPets
                Fluent:Notify({ Title = "Backpack Scanner", Content = string.format("Berhasil refresh! Ditemukan %d pet di backpack.", count), Duration = 3 })
            end
        end
    })
end
end)(); _hatchTab(Tabs.Hatch, Automation, EggsPetsData, MainFunctions, HatchFunctions, InventoryFunctions, MiscFunctions, UILibrary); end)
pcall(function() local _invTab = (function()
--[[
    GAG 1 Hub - Inventory Tab Layout
    Manages Pet Inventory Overview, Favorite Pet Actions, Trade Ticket System, and Gift System.
--]]

return function(InventoryTab, Automation, EggsPetsData, MainFunctions, HatchFunctions, InventoryFunctions, MiscFunctions, Fluent)

    ----------------------------------------------------------------------------
    -- A. FAVORITE PET MANAGEMENT
    ----------------------------------------------------------------------------
    InventoryTab:AddSection("Favorite Pet Manager")

    InventoryTab:AddParagraph({
        Title = "ℹ️ Favorite Pet Manager Info",
        Content = "Quickly favorite or unfavorite matching pets in your inventory based on species, weight (KG), and age conditions to protect your valuable pets from accidental selling."
    })

    -- State variables for Favorite Pet Filtering
