    -- Get initial pet dropdown list from actual player inventory
    local initialPetList = InventoryFunctions.GetInventoryPetNames()

    -- 1. Select Pet Dropdown (Multi-Select with Live Search & Select All/Clear All)
    local SelectPetDropdown = InventoryTab:AddDropdown("SelectFavPetDropdown", {
        Title = "Select Pets to Favorite",
        Description = "Choose specific species or select all (Searchable)",
        Values = initialPetList,
        Multi = true,
        Default = {},
        Callback = function(val)
            selectedFavPets = val or {}
        end
    })

    -- Periodically refresh Select Pet dropdown choices dynamically only when inventory changes
    task.spawn(function()
        local lastPetsJoined = ""
        while task.wait(3) do
            if SelectPetDropdown and typeof(SelectPetDropdown.SetValues) == "function" then
                pcall(function()
                    local currentPets = InventoryFunctions.GetInventoryPetNames()
                    local petsJoined = table.concat(currentPets, ",")
                    if petsJoined ~= lastPetsJoined then
                        lastPetsJoined = petsJoined
                        SelectPetDropdown:SetValues(currentPets)
                    end
                end)
            end
        end
    end)

    -- 2. Weight (KG) Input & Condition (Below / Above) Dropdown
    InventoryTab:AddInput("FavPetWeightInput", {
        Title = "Weight (KG)",
        Default = "0",
        Numeric = true,
        Finished = false,
        Callback = function(val)
            favWeightInputVal = val
        end
    })

    InventoryTab:AddDropdown("FavPetWeightCondDropdown", {
        Title = "Weight Condition",
        Values = { "Above", "Below" },
        Default = "Above",
        Callback = function(val)
            favWeightCondVal = val
        end
    })

    -- 3. Age Input & Condition (Below / Above) Dropdown
    InventoryTab:AddInput("FavPetAgeInput", {
        Title = "Age",
        Default = "0",
        Numeric = true,
