        Callback = function(val)
            favAgeInputVal = val
        end
    })

    InventoryTab:AddDropdown("FavPetAgeCondDropdown", {
        Title = "Age Condition",
        Values = { "Above", "Below" },
        Default = "Above",
        Callback = function(val)
            favAgeCondVal = val
        end
    })

    -- 4. Action Buttons: Favorite Pet & Unfavorite Pet
    InventoryTab:AddButton({
        Title = "Favorite Pet",
        Description = "Favorites matching pets in your inventory",
        Callback = function()
            local count = InventoryFunctions.SetPetFavorite(
                selectedFavPets,
                favWeightInputVal,
                favWeightCondVal,
                favAgeInputVal,
                favAgeCondVal,
                true
            )
            
            if Fluent and typeof(Fluent.Notify) == "function" then
                Fluent:Notify({
                    Title = "Favorite Pet Manager",
                    Content = string.format("Favorited %d pet(s) matching criteria!", count),
                    Duration = 3.5
                })
            end
        end
    })

    InventoryTab:AddButton({
        Title = "Unfavorite Pet",
        Description = "Unfavorites matching pets in your inventory",
        Callback = function()
            local count = InventoryFunctions.SetPetFavorite(
                selectedFavPets,
                favWeightInputVal,
                favWeightCondVal,
                favAgeInputVal,
                favAgeCondVal,
                false
            )

            if Fluent and typeof(Fluent.Notify) == "function" then
                Fluent:Notify({
                    Title = "Favorite Pet Manager",
                    Content = string.format("Unfavorited %d pet(s) matching criteria!", count),
                    Duration = 3.5
                })
            end
        end
    })

    ----------------------------------------------------------------------------
    -- B. TRADE TICKET MANAGEMENT
    ----------------------------------------------------------------------------
    InventoryTab:AddSection("Trade Ticket")

    InventoryTab:AddParagraph({
        Title = "🎟️ Trade Ticket Info",
        Content = "Send trade tickets for matching pets directly to players in your server, or accept incoming trade tickets automatically."
    })

    -- State variables for Trade Ticket
    local selectedTradePlayer    = ""
    local selectedTicketPets     = {}
    local ticketWeightInputVal   = "0"
    local ticketWeightCondVal    = "Below"
    local ticketAgeInputVal      = "1"
    local ticketAgeCondVal       = "Below"

    -- 1. Select Server Player Dropdown
    local initialPlayerList = InventoryFunctions.GetServerPlayerList()
    local SelectPlayerDropdown = InventoryTab:AddDropdown("SelectTradePlayerDropdown", {
        Title = "Pilih Player di Server",
        Description = "Pilih player tujuan yang ada di dalam server",
        Values = initialPlayerList,
        Multi = false,
        Default = initialPlayerList[1] or "",
        Callback = function(val)
            selectedTradePlayer = tostring(val or "")
        end
    })
    selectedTradePlayer = initialPlayerList[1] or ""

    -- Periodically refresh player list as players join/leave
    task.spawn(function()
        local lastPlayersJoined = ""
        while task.wait(3) do
            if SelectPlayerDropdown and typeof(SelectPlayerDropdown.SetValues) == "function" then
                pcall(function()
                    local currentPlayers = InventoryFunctions.GetServerPlayerList()
                    local joined = table.concat(currentPlayers, ",")
                    if joined ~= lastPlayersJoined then
                        lastPlayersJoined = joined
                        SelectPlayerDropdown:SetValues(currentPlayers)
                    end
                end)
            end
        end
    end)

    -- 2. Select Pets for Trade Ticket Dropdown (e.g. "Mimic Octopus x7")
    local selectedTicketSpeciesMap = {}

    local function cleanSpeciesName(str)
        if not str then return "" end
        local raw = tostring(str):match("^(.-)%s+x%d+$") or tostring(str)
        return raw:gsub("%s*%[[^%]]+%]%s*", "")
                  :gsub("%s*%([^%)]+%)%s*", "")
                  :gsub("%s*x%d+$", "")
                  :gsub("%s*#%d+$", "")
                  :gsub("[\r\n\t\0\160]", " ")
                  :gsub("%s+", " ")
                  :match("^%s*(.-)%s*$"):lower()
    end

    local initialTicketPetList = (InventoryFunctions.GetTicketInventoryPetNamesWithCount and InventoryFunctions.GetTicketInventoryPetNamesWithCount()) or initialPetList
    local SelectTicketPetDropdown = InventoryTab:AddDropdown("SelectTicketPetDropdown", {
        Title = "Select Pet",
        Description = "Pilih jenis pet yang akan dimasukkan ke dalam tiket (Searchable)",
