                local item = (v == true and k) or (type(v) == "string" and v)
                if item then
                    local clean = cleanSpeciesName(item)
                    if clean and clean ~= "" then
                        selectedTicketSpeciesMap[clean] = true
                    end
                end
            end
            if Automation and Automation.Settings then
