                    local currentPets = (InventoryFunctions.GetTicketInventoryPetNamesWithCount and InventoryFunctions.GetTicketInventoryPetNamesWithCount()) or InventoryFunctions.GetInventoryPetNames()
                    local petsJoined = table.concat(currentPets, ",")
                    if petsJoined ~= lastTicketPetsJoined then
                        lastTicketPetsJoined = petsJoined
                        
                        -- Reconstruct active selection table based on clean species names
                        local newSelectedValues = {}
                        for _, optionStr in ipairs(currentPets) do
                            local clean = cleanSpeciesName(optionStr)
                            if selectedTicketSpeciesMap[clean] then
                                newSelectedValues[optionStr] = true
                            end
                        end
                        
                        SelectTicketPetDropdown:SetValues(currentPets)
                        if typeof(SelectTicketPetDropdown.SetValue) == "function" then
                            SelectTicketPetDropdown:SetValue(newSelectedValues)
                        end
                    end
                end)
            end
        end
    end)

    -- 3. Input Berat (Weight KG) & Kondisi (Below / Above)
    InventoryTab:AddInput("TicketWeightInput", {
