        Values = { "Below", "Above" },
        Default = "Below",
        Callback = function(val)
            ticketWeightCondVal = val
            if Automation and Automation.Settings then
                Automation.Settings.TicketWeightCond = val
            end
        end
    })

    -- 4. Input Level / Age & Kondisi (Below / Above)
