        Default = Automation.States.AutoSendTradeTicket or false,
        Callback = function(Value)
            Automation.States.AutoSendTradeTicket = Value
            if Value then
                task.spawn(function()
                    while Automation.States.AutoSendTradeTicket do
                        if selectedTradePlayer and selectedTradePlayer ~= "" then
                            -- Check if any matching pets exist
                            local remainingMatching = InventoryFunctions.GetMatchingTradePets(
                                selectedTicketSpeciesMap,
                                ticketWeightInputVal,
                                ticketWeightCondVal,
                                ticketAgeInputVal,
                                ticketAgeCondVal,
                                1
                            )

                            if #remainingMatching == 0 then
                                Automation.States.AutoSendTradeTicket = false
                                if SendTicketToggle and typeof(SendTicketToggle.SetValue) == "function" then
                                    SendTicketToggle:SetValue(false)
                                end
                                if Fluent and typeof(Fluent.Notify) == "function" then
                                    Fluent:Notify({
                                        Title = "Trade Ticket",
                                        Content = "Semua pet target sudah habis terkirim! Toggle Kirim Tiket otomatis dimatikan.",
                                        Duration = 5
                                    })
                                end
                                break
                            end

                            if not InventoryFunctions.IsTradeSessionActive() then
                                local status, msg = InventoryFunctions.SendTradeTicket(
                                    selectedTradePlayer,
                                    selectedTicketSpeciesMap,
                                    ticketWeightInputVal,
                                    ticketWeightCondVal,
                                    ticketAgeInputVal,
                                    ticketAgeCondVal
                                )

                                if status == 0 and msg == "NoPetsRemaining" then
                                    Automation.States.AutoSendTradeTicket = false
                                    if SendTicketToggle and typeof(SendTicketToggle.SetValue) == "function" then
                                        SendTicketToggle:SetValue(false)
                                    end
                                    if Fluent and typeof(Fluent.Notify) == "function" then
                                        Fluent:Notify({
                                            Title = "Trade Ticket",
                                            Content = "Semua pet target sudah habis terkirim! Toggle Kirim Tiket otomatis dimatikan.",
                                            Duration = 5
                                        })
                                    end
                                    break
                                end

                                -- Wait until trade session opens and then finishes
                                local waitStart = os.clock()
                                local sawTradeActive = false
                                while os.clock() - waitStart < 45 and Automation.States.AutoSendTradeTicket do
                                    if InventoryFunctions.IsTradeSessionActive() then
                                        sawTradeActive = true
                                    elseif sawTradeActive and not InventoryFunctions.IsTradeSessionActive() then
                                        -- Trade session has finished!
                                        break
                                    end
                                    task.wait(0.5)
                                end

                                -- Wait for inventory to sync after trade
                                task.wait(1.5)
                            end
                        end
                        task.wait(1)
                    end
                end)
            end
        end
    })

    -- 6. Toggle Terima Tiket
    local AcceptTicketToggle = InventoryTab:AddToggle("AutoAcceptTicketToggle", {
        Title = "Terima Tiket",
        Description = "Murni terima tiket masuk, looping accept & confirm (tanpa masukkan item apapun)",
        Default = Automation.States.AutoAcceptTradeTicket or false,
        Callback = function(Value)
            Automation.States.AutoAcceptTradeTicket = Value
            if Value then
                task.spawn(function()
                    while Automation.States.AutoAcceptTradeTicket do
                        -- 1. Terima request tiket yang masuk
                        InventoryFunctions.AcceptTradeTicket()

                        -- 2. Jika sesi trade aktif, looping Accept dan Confirm sampai selesai
                        if InventoryFunctions.IsTradeSessionActive() then
                            task.wait(1.0)
                            local loopStart = os.clock()
                            while InventoryFunctions.IsTradeSessionActive() and (os.clock() - loopStart < 45) and Automation.States.AutoAcceptTradeTicket do
                                InventoryFunctions.AcceptActiveTrade()
                                task.wait(0.5)
                                InventoryFunctions.ConfirmActiveTrade()
                                task.wait(0.5)
                            end
                            task.wait(1.0)
                        end

                        task.wait(0.5)
                    end
                end)
            end
        end
    })

    ----------------------------------------------------------------------------
    -- C. GIFT SYSTEM
    ----------------------------------------------------------------------------
    InventoryTab:AddSection("Gift System")

    InventoryTab:AddParagraph({
        Title = "🎁 Terima Gift",
        Content = "Otomatis accept setiap notifikasi gift pet yang masuk dari player lain."
    })

    InventoryTab:AddToggle("AutoAcceptGiftToggle", {
        Title = "Terima Gift",
        Description = "Otomatis accept setiap notifikasi gift pet yang masuk",
        Default = false,
        Callback = function(Value)
            if Automation and Automation.States then
                Automation.States.AutoAcceptGift = Value
            end
        end
    })
end
end)(); _invTab(Tabs.Inventory, Automation, EggsPetsData, MainFunctions, HatchFunctions, InventoryFunctions, MiscFunctions, UILibrary); end)
pcall(function() local _miscTab = (function()
--[[
    GAG 1 Hub - Miscellaneous & Utility Tab Layout
    Contains Server Management, Performance Booster, and Visual ESP.
--]]

return function(MiscTab, Automation, EggsPetsData, MainFunctions, HatchFunctions, InventoryFunctions, MiscFunctions, Fluent)

    ----------------------------------------------------------------------------
    -- A. SERVER UTILITIES
    ----------------------------------------------------------------------------
    MiscTab:AddSection("Server Management")

    MiscTab:AddParagraph({
        Title = "ℹ️ Server Management Info",
        Content = "Teleport to a fresh public Roblox server or rejoin your current server instance."
    })

    MiscTab:AddButton({
        Title = "Server Hop (Find New Server)",
        Description = "Teleports you to another active public server",
        Callback = function()
            if Fluent and typeof(Fluent.Notify) == "function" then
                Fluent:Notify({ Title = "Server Hop", Content = "Searching for available server...", Duration = 3 })
            end
            MiscFunctions.ServerHop()
        end
    })

    MiscTab:AddButton({
        Title = "Rejoin Current Server",
        Description = "Rejoins the current Place / Server instance",
        Callback = function()
            if Fluent and typeof(Fluent.Notify) == "function" then
                Fluent:Notify({ Title = "Rejoining", Content = "Teleporting back to server...", Duration = 3 })
            end
            MiscFunctions.RejoinServer()
        end
    })

    ----------------------------------------------------------------------------
    -- B. VISUALS & ESP
    ----------------------------------------------------------------------------
    MiscTab:AddSection("Visuals & Garden ESP")

    MiscTab:AddParagraph({
        Title = "ℹ️ Visual ESP Info",
        Content = "Toggle floating 3D text billboards above garden eggs and active pets on your farm showing pet species, mutation, weight KG, and level."
    })

    MiscTab:AddToggle("ESPEggToggle", {
        Title = "Enable Garden Egg ESP",
        Description = "Shows floating text above physical eggs in your farm (Pet Name & Weight KG)",
        Default = Automation.States.ESPEgg or false,
        Callback = function(state)
            Automation.ToggleTask("ESPEgg", state, function()
                MiscFunctions.UpdateEggESP()
                task.wait(1)
            end)
            if not state then
                MiscFunctions.ClearEggESP()
            end
        end
    })

    MiscTab:AddToggle("ESPPetToggle", {
        Title = "Enable Garden Pet ESP",
        Description = "Shows floating text above pets in farm (Name, Mutation, Weight, Level, Passive/Skill)",
        Default = Automation.States.ESPPet or false,
        Callback = function(state)
            Automation.ToggleTask("ESPPet", state, function()
                MiscFunctions.UpdatePetESP()
                task.wait(1)
            end)
            if not state then
                MiscFunctions.ClearPetESP()
            end
        end
    })


    ----------------------------------------------------------------------------
    -- C. DISCORD WEBHOOK CONFIGURATION
    ----------------------------------------------------------------------------
    MiscTab:AddSection("Discord Webhook Configuration")

    MiscTab:AddParagraph({
        Title = "ℹ️ Discord Webhook Info",
        Content = "Receive instant real-time cycle execution reports, egg open stats, and inventory capacity alerts directly in your Discord server channel."
    })

    MiscTab:AddToggle("WebhookEnableToggle", {
        Title = "Enable Discord Webhook",
        Description = "Enable or disable sending Discord Webhook notifications",
        Default = Automation.Settings.WebhookEnabled or false,
        Callback = function(state)
            Automation.Settings.WebhookEnabled = state
            if Automation and typeof(Automation.SaveConfig) == "function" then Automation.SaveConfig() end
        end
    })

    MiscTab:AddInput("WebhookUrlInput", {
        Title = "Discord Webhook URL",
        Description = "Input your Discord Webhook URL link",
        Default = Automation.Settings.WebhookUrl or "",
        Placeholder = "https://discord.com/api/webhooks/...",
        Callback = function(val)
            Automation.Settings.WebhookUrl = val
            if Automation and typeof(Automation.SaveConfig) == "function" then Automation.SaveConfig() end
        end
    })

    MiscTab:AddButton({
        Title = "Test Webhook Connection",
        Description = "Sends a test message embed to your Discord Webhook URL",
        Callback = function()
            local url = Automation.Settings.WebhookUrl
            if not url or url == "" or not url:find("http") then
                if Fluent and typeof(Fluent.Notify) == "function" then
                    Fluent:Notify({ Title = "Webhook Test", Content = "Please enter a valid Discord Webhook URL first!", Duration = 3 })
                end
                return
            end

            local ok, err = MiscFunctions.TestWebhook(url)
            if Fluent and typeof(Fluent.Notify) == "function" then
                if ok then
                    Fluent:Notify({ Title = "Webhook Test", Content = "Successfully sent test message to Discord Webhook!", Duration = 4 })
                else
                    Fluent:Notify({ Title = "Webhook Test Error", Content = "Failed to send: " .. tostring(err or "Unknown Error"), Duration = 4 })
                end
            end
        end
    })

    ----------------------------------------------------------------------------
    -- D. PERFORMANCE & FPS BOOSTER
    ----------------------------------------------------------------------------
    MiscTab:AddSection("Performance & Lag Reduction")

    MiscTab:AddParagraph({
        Title = "ℹ️ Performance Booster Info",
        Content = "Boost game FPS and eliminate lag during long auto hatching sessions by toggling potato graphics or clearing visual particle effects."
    })

    MiscTab:AddToggle("FPSBoosterToggle", {
        Title = "FPS Booster (Potato Graphics Mode)",
        Description = "Lowers texture detail, disables shadows and lighting for maximum hatch FPS",
        Default = Automation.States.FPSBooster or false,
        Callback = function(state)
            Automation.States.FPSBooster = state
            MiscFunctions.BoostFPS(state)
            if Automation and typeof(Automation.SaveConfig) == "function" then Automation.SaveConfig() end
        end
    })

    MiscTab:AddButton({
        Title = "Remove Visual Particles & Effects",
        Description = "Destroys laggy hatch particle emitters and smoke from world",
        Callback = function()
            MiscFunctions.RemoveEffects()
            if Fluent and typeof(Fluent.Notify) == "function" then
                Fluent:Notify({ Title = "Cleaner", Content = "Visual particle effects removed!", Duration = 3 })
            end
        end
    })
end
end)(); _miscTab(Tabs.Misc, Automation, EggsPetsData, MainFunctions, HatchFunctions, InventoryFunctions, MiscFunctions, UILibrary); end)
pcall(function() local _settTab = (function()
--[[
    GAG 1 Hub - Settings Tab Sub-Menu UI
    Native Web Dashboard Telemetry, Auto Save Config & Script Controls
--]]

return function(SettingsTab, Automation, MainFunctions, Window, UILibrary)
    SettingsTab:AddSection("Automatic Config Persistence")

    SettingsTab:AddParagraph({
        Title = "ℹ️ Config Persistence Info",
        Content = "Manually save or reload your script settings to JSON configuration files for easy multi-account automation."
    })

    SettingsTab:AddButton({
        Title = "Save Settings Now",
        Description = "Manually trigger auto-save for current configuration",
        Callback = function()
            if Automation and typeof(Automation.SaveConfig) == "function" then
                Automation.SaveConfig()
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "Config Manager", Content = "Settings saved to GAG1_Krexel_Config.json", Duration = 3 })
                end
            end
        end
    })

    SettingsTab:AddButton({
        Title = "Reload Settings",
        Description = "Reload saved configuration from GAG1_Krexel_Config.json",
        Callback = function()
            if Automation and typeof(Automation.LoadConfig) == "function" then
                Automation.LoadConfig()
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "Config Manager", Content = "Configuration reloaded successfully!", Duration = 3 })
                end
            end
        end
    })

    ----------------------------------------------------------------------------
    -- C. SCRIPT CONTROLS & CLEAN UNLOAD
    ----------------------------------------------------------------------------
    SettingsTab:AddSection("Script Controls")

    SettingsTab:AddParagraph({
        Title = "ℹ️ Script Unloader Info",
        Content = "Cleanly terminate all background automation loops, disconnect event listeners, and unload the Krexel Hub interface."
    })

    SettingsTab:AddButton({
        Title = "Unload Script Hub",
        Description = "Closes interface and cleans up active connections & background loops",
        Callback = function()
            -- Stop all automation tasks
            if Automation and Automation.States then
                for taskName, _ in pairs(Automation.States) do
                    Automation.StopTask(taskName)
                end
            end

            -- Disable Anti-AFK if active
            if MainFunctions and typeof(MainFunctions.DisableAntiAFK) == "function" then
                MainFunctions.DisableAntiAFK()
            end

            if Window and typeof(Window.Destroy) == "function" then
                Window:Destroy()
            end

            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({ Title = "Unload", Content = "GAG 1 Script Hub unloaded successfully.", Duration = 3 })
            end
        end
    })
end
end)(); _settTab(Tabs.Settings, Automation, MainFunctions, Window, UILibrary); end)

